import { BadRequestException, Inject, Injectable, NotFoundException, Optional } from "@nestjs/common";
import { PrismaService } from "../data-access/prisma.service";
import { AuthService } from "../auth/auth.service";
import { AuditService } from "../audit/audit.service";
import type { SessionClaims } from "../auth/auth.dto";

export interface CreateOrganizationDto {
  slug: string;
  name: string;
  description?: string;
}

export interface CreateUserDto {
  email: string;
  displayName: string;
  password: string;
  role?: string;
  organizationId?: string;
}

export interface UpdateUserDto {
  displayName?: string;
  status?: "active" | "suspended";
  role?: string;
  organizationId?: string;
}

export interface CreateGroupDto {
  slug: string;
  name: string;
  description?: string;
  organizationId?: string;
}

export interface AddGroupMemberDto {
  userId: string;
  role?: string;
}

export interface AddProjectMemberDto {
  userId: string;
  role?: string;
}

/**
 * AdminService
 *
 * Implements administrative user, organization, group, and project governance.
 * Enforces:
 * 1. Immediate session revocation upon user suspension or deletion.
 * 2. Self-describing scrypt password hashing for user creation.
 * 3. Security audit event recording for every mutation via AuditService.
 * 4. Passwords and hashes are strictly masked from all return types.
 */
@Injectable()
export class AdminService {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private prisma: any | null = null;

  constructor(
    @Inject(AuthService) private readonly authService: AuthService,
    @Inject(AuditService) private readonly auditService: AuditService,
    @Optional() @Inject(PrismaService) prismaService?: PrismaService
  ) {
    if (prismaService) {
      this.prisma = prismaService;
    }
  }

  /**
   * @deprecated Retained strictly as a test seam. Production must use NestJS DI.
   */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
  private requirePrisma(): void {
    if (!this.prisma) {
      throw new NotFoundException("Database not available in this environment");
    }
  }

  // ---------------------------------------------------------------------------
  // Organizations
  // ---------------------------------------------------------------------------

  async createOrganization(dto: CreateOrganizationDto, actorClaims: SessionClaims) {
    this.requirePrisma();

    if (!dto.slug || !dto.name) {
      throw new BadRequestException("slug and name are required");
    }

    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    const organization = await this.prisma.organization.create({
      data: {
        slug: dto.slug.toLowerCase().trim(),
        name: dto.name.trim(),
        description: dto.description?.trim() ?? null
      }
    });

    await this.auditService.recordWithClaims(actorClaims, {
      action: "ORGANIZATION_CREATE",
      resourceType: "Organization",
      resourceId: organization.id,
      details: { slug: organization.slug, name: organization.name }
    });

    return organization;
  }

  async listOrganizations() {
    this.requirePrisma();
    // eslint-disable-next-line @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    return this.prisma.organization.findMany({
      orderBy: { createdAt: "desc" }
    });
  }

  // ---------------------------------------------------------------------------
  // Users
  // ---------------------------------------------------------------------------

  async listUsers(organizationId?: string) {
    this.requirePrisma();
    // eslint-disable-next-line @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    return this.prisma.user.findMany({
      where: organizationId ? { organizationId } : {},
      select: {
        id: true,
        email: true,
        displayName: true,
        organizationId: true,
        status: true,
        createdAt: true,
        updatedAt: true,
        roles: { include: { role: { select: { key: true, name: true } } } }
      },
      orderBy: { createdAt: "desc" }
    });
  }

  async createUser(dto: CreateUserDto, actorClaims: SessionClaims) {
    this.requirePrisma();

    if (!dto.email || !dto.password) {
      throw new BadRequestException("email and password are required");
    }

    const passwordHash = await this.authService.hashPassword(dto.password);
    const userId = `usr_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;

    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    const user = await this.prisma.user.create({
      data: {
        id: userId,
        email: dto.email.toLowerCase().trim(),
        displayName: dto.displayName.trim() || dto.email,
        passwordHash,
        organizationId: dto.organizationId ?? actorClaims.organizationId ?? null,
        status: "active"
      },
      select: {
        id: true,
        email: true,
        displayName: true,
        organizationId: true,
        status: true,
        createdAt: true
      }
    });

    // Assign role if specified
    const roleKey = dto.role ?? "Viewer";
    try {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
      const roleRecord = await this.prisma.role.findUnique({ where: { key: roleKey } });
      if (roleRecord) {
        // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
        await this.prisma.userRole.create({
          data: { userId: user.id, roleId: roleRecord.id }
        });
      }
    } catch {
      // ignore
    }

    await this.auditService.recordWithClaims(actorClaims, {
      action: "USER_CREATE",
      resourceType: "User",
      resourceId: user.id,
      details: { email: user.email, role: roleKey }
    });

    return user;
  }

  async updateUser(id: string, dto: UpdateUserDto, actorClaims: SessionClaims) {
    this.requirePrisma();

    const data: Record<string, unknown> = {};
    if (dto.displayName) data.displayName = dto.displayName.trim();
    if (dto.organizationId !== undefined) data.organizationId = dto.organizationId;
    if (dto.status) data.status = dto.status;

    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    const updated = await this.prisma.user.update({
      where: { id },
      data,
      select: {
        id: true,
        email: true,
        displayName: true,
        organizationId: true,
        status: true,
        updatedAt: true
      }
    });

    // If status is changed to suspended, IMMEDIATELY revoke all active sessions
    if (dto.status === "suspended") {
      await this.authService.revokeAllUserSessions(id);
    }

    await this.auditService.recordWithClaims(actorClaims, {
      action: "USER_UPDATE",
      resourceType: "User",
      resourceId: updated.id,
      details: { status: dto.status, displayName: dto.displayName }
    });

    return updated;
  }

  // ---------------------------------------------------------------------------
  // Groups
  // ---------------------------------------------------------------------------

  async listGroups(organizationId?: string) {
    this.requirePrisma();
    // eslint-disable-next-line @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    return this.prisma.group.findMany({
      where: organizationId ? { organizationId } : {},
      include: {
        members: {
          include: {
            user: { select: { id: true, email: true, displayName: true } }
          }
        }
      },
      orderBy: { createdAt: "desc" }
    });
  }

  async createGroup(dto: CreateGroupDto, actorClaims: SessionClaims) {
    this.requirePrisma();

    if (!dto.slug || !dto.name) {
      throw new BadRequestException("slug and name are required");
    }

    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    const group = await this.prisma.group.create({
      data: {
        slug: dto.slug.toLowerCase().trim(),
        name: dto.name.trim(),
        description: dto.description?.trim() ?? null,
        organizationId: dto.organizationId ?? actorClaims.organizationId ?? null
      }
    });

    await this.auditService.recordWithClaims(actorClaims, {
      action: "GROUP_CREATE",
      resourceType: "Group",
      resourceId: group.id,
      details: { slug: group.slug, name: group.name }
    });

    return group;
  }

  async addGroupMember(groupId: string, dto: AddGroupMemberDto, actorClaims: SessionClaims) {
    this.requirePrisma();

    if (!dto.userId) {
      throw new BadRequestException("userId is required");
    }

    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    const member = await this.prisma.groupMember.upsert({
      where: { groupId_userId: { groupId, userId: dto.userId } },
      create: { groupId, userId: dto.userId, role: dto.role ?? "member" },
      update: { role: dto.role ?? "member" }
    });

    await this.auditService.recordWithClaims(actorClaims, {
      action: "GROUP_MEMBER_ADD",
      resourceType: "Group",
      resourceId: groupId,
      details: { memberUserId: dto.userId, role: dto.role ?? "member" }
    });

    return member;
  }

  async removeGroupMember(groupId: string, userId: string, actorClaims: SessionClaims) {
    this.requirePrisma();

    // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    await this.prisma.groupMember.deleteMany({
      where: { groupId, userId }
    });

    await this.auditService.recordWithClaims(actorClaims, {
      action: "GROUP_MEMBER_REMOVE",
      resourceType: "Group",
      resourceId: groupId,
      details: { removedUserId: userId }
    });

    return { removed: true, groupId, userId };
  }

  // ---------------------------------------------------------------------------
  // Project Memberships
  // ---------------------------------------------------------------------------

  async listProjectMembers(projectId: string) {
    this.requirePrisma();
    // eslint-disable-next-line @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    return this.prisma.projectMember.findMany({
      where: { projectId },
      include: {
        user: { select: { id: true, email: true, displayName: true } }
      }
    });
  }

  async addProjectMember(projectId: string, dto: AddProjectMemberDto, actorClaims: SessionClaims) {
    this.requirePrisma();

    if (!dto.userId) {
      throw new BadRequestException("userId is required");
    }

    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    const member = await this.prisma.projectMember.upsert({
      where: { projectId_userId: { projectId, userId: dto.userId } },
      create: { projectId, userId: dto.userId, role: dto.role ?? "Viewer" },
      update: { role: dto.role ?? "Viewer" }
    });

    await this.auditService.recordWithClaims(actorClaims, {
      action: "PROJECT_MEMBER_ADD",
      resourceType: "Project",
      resourceId: projectId,
      details: { memberUserId: dto.userId, role: dto.role ?? "Viewer" }
    });

    return member;
  }

  async removeProjectMember(projectId: string, userId: string, actorClaims: SessionClaims) {
    this.requirePrisma();

    // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    await this.prisma.projectMember.deleteMany({
      where: { projectId, userId }
    });

    await this.auditService.recordWithClaims(actorClaims, {
      action: "PROJECT_MEMBER_REMOVE",
      resourceType: "Project",
      resourceId: projectId,
      details: { removedUserId: userId }
    });

    return { removed: true, projectId, userId };
  }
}

import { BadRequestException, NotFoundException, ServiceUnavailableException } from "@nestjs/common";

export const EVENT_PAGE_LIMIT = 128;
const terminal = new Set(["COMPLETED", "FAILED", "CANCELLED"]);

/** Read-only snapshot. Transport frames and model output never enter this read model. */
export async function readAgentEventPage(db: any, runId: string, cursor = 0, limit = EVENT_PAGE_LIMIT) {
  if (!Number.isSafeInteger(cursor) || cursor < 0 || !Number.isSafeInteger(limit) || limit < 1 || limit > EVENT_PAGE_LIMIT)
    throw new BadRequestException("AGENT_EVENT_CURSOR_INVALID");
  return db.$transaction(async (tx: any) => {
    const run = await tx.agentRun.findUnique({ where: { id: runId }, select: { status: true, eventSeq: true, eventTerminalSeq: true } });
    if (!run) throw new NotFoundException("Agent run not found");
    if (!Number.isSafeInteger(run.eventSeq) || run.eventSeq < 0) throw new ServiceUnavailableException("AGENT_EVENT_SEQUENCE_UNAVAILABLE");
    if (cursor > run.eventSeq) throw new BadRequestException("AGENT_EVENT_CURSOR_INVALID");
    const watermark = terminal.has(run.status) ? run.eventTerminalSeq : null;
    if (terminal.has(run.status) && watermark !== run.eventSeq) throw new ServiceUnavailableException("AGENT_EVENT_WATERMARK_INVALID");
    const events = await tx.agentRunEvent.findMany({ where: { agentRunId: runId, seq: { gt: cursor, lte: run.eventSeq } },
      orderBy: { seq: "asc" }, take: limit });
    let nextCursor = cursor;
    for (const e of events) {
      if (e.agentRunId !== runId || e.seq !== nextCursor + 1) throw new ServiceUnavailableException("AGENT_EVENT_SEQUENCE_GAP");
      nextCursor = e.seq;
    }
    if (nextCursor < run.eventSeq && events.length < limit) throw new ServiceUnavailableException("AGENT_EVENT_SEQUENCE_GAP");
    return { runId, events, nextCursor, watermark: run.eventSeq, terminalWatermark: watermark,
      status: run.status, hasMore: nextCursor < run.eventSeq, replayComplete: watermark !== null && nextCursor === watermark };
  }, { isolationLevel: "RepeatableRead" });
}

/** Legacy IDs are aliases only; all subsequent pagination/order uses seq. */
export async function resolveAgentEventCursor(db: any, runId: string, lastEventId?: string): Promise<number> {
  if (!lastEventId) return 0;
  const prefix = `${runId}:`;
  if (lastEventId.startsWith(prefix)) {
    const suffix = lastEventId.slice(prefix.length);
    if (!/^(0|[1-9][0-9]*)$/.test(suffix) || !Number.isSafeInteger(Number(suffix))) throw new BadRequestException("AGENT_EVENT_CURSOR_INVALID");
    return Number(suffix);
  }
  const event = await db.agentRunEvent.findUnique({ where: { id: lastEventId }, select: { agentRunId: true, seq: true } });
  if (!event || event.agentRunId !== runId) throw new BadRequestException("AGENT_EVENT_CURSOR_INVALID");
  if (!Number.isSafeInteger(event.seq) || event.seq < 1) throw new ServiceUnavailableException("AGENT_EVENT_SEQUENCE_UNAVAILABLE");
  return event.seq;
}

import { Controller, Query, Get, Param, Headers, UseGuards, Sse, Inject, type MessageEvent } from '@nestjs/common';
import { Observable } from 'rxjs';
import { AuthService } from '../auth/auth.service';
import { AuthzGuard } from '../auth/authz.guard';
import { AgentRuntimeService } from './agent-runtime.service';
import type { SessionClaims } from '../auth/auth.dto';

/**
 * SSE endpoint for streaming AgentRunEvents to the frontend.
 *
 * Guarantees:
 * - Authenticated via durable session cookie (no JWT in query)
 * - Authorization scoped to the requesting user's organization/project
 * - Supports Last-Event-ID to resume missed events with total ordering
 * - Server-owned per-run sequence pagination
 */
@Controller('agent-runs')
@UseGuards(AuthzGuard)
export class AgentRuntimeEventsController {
  constructor(
    @Inject(AgentRuntimeService) private readonly agentRuntime: AgentRuntimeService,
    @Inject(AuthService) private readonly authService: AuthService,
  ) {}

  @Get(':id/recovery')
  async recoverRun(
    @Param('id') id: string,
    @Headers('cookie') cookieHeader: string | undefined,
    @Query('cursor') cursor = '0',
    @Query('limit') limit = '128',
  ) {
    const claims = await this.authService.validateDurableSession(cookieHeader);
    return this.agentRuntime.recoverRunSnapshot(id, claims, Number(cursor), Number(limit));
  }

  @Get(':id/events/replay')
  async replayEvents(
    @Param('id') id: string,
    @Headers('cookie') cookieHeader: string | undefined,
    @Query('cursor') cursor = '0',
    @Query('limit') limit = '128',
  ) {
    const claims = await this.authService.validateDurableSession(cookieHeader);
    return this.agentRuntime.replayEvents(id, claims, Number(cursor), Number(limit));
  }

  /**
   * Stream persisted AgentRunEvent records for a given run.
   *
   * @param id          AgentRun identifier
   * @param cookieHeader Session cookie header for auth
   * @param lastEventId Optional Last‑Event‑ID header for replay
   */
  @Get(':id/events')
  @Sse()
  async streamEvents(
    @Param('id') id: string,
    @Headers('cookie') cookieHeader: string | undefined,
    @Headers('last-event-id') lastEventId?: string,
  ): Promise<Observable<MessageEvent>> {
    const claims: SessionClaims = typeof this.authService.validateDurableSession === 'function'
      ? await this.authService.validateDurableSession(cookieHeader)
      : await (this.authService as any).sessionClaims(cookieHeader);
    // Authorize read access to the run (reuse service method)
    await this.agentRuntime.authorizeRunRead(id, claims);
    // Return a hot observable that polls the DB for new events
    return this.agentRuntime.createEventObservable(id, claims, lastEventId);
  }
}

