  /**
   * Verify that the caller has READ permission on the specified AgentRun.
   * Reuses the same authorization logic as getAgentRun.
   */
  async authorizeRunRead(runId: string, claims: SessionClaims): Promise<void> {
    const db = this.requirePrisma();
    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    const run = await db.agentRun.findUnique({
      where: { id: runId },
      select: { id: true, projectId: true, userId: true },
    });

    if (!run) {
      throw new NotFoundException(`Agent run '${runId}' not found`);
    }

    if (this.projectAccess) await this.projectAccess.assert(claims, run.projectId);
    await this.resourceAuthz.assertAuthorized(
      this.subjectFromClaims(claims),
      "READ",
      {
        resourceType: "AgentRun",
        id: run.id as string,
        projectId: run.projectId as string,
        userId: run.userId as string,
        organizationId: claims.organizationId,
      },
    );
  }

  async recoverRunSnapshot(runId: string, claims: SessionClaims, cursor = 0, limit = 128) {
    await this.authorizeRunRead(runId, claims);
    if (!this.recovery) throw new ServiceUnavailableException("AGENT_RUN_RECOVERY_UNAVAILABLE");
    return this.recovery.snapshot(runId, cursor, limit);
  }

  async replayEvents(runId: string, claims: SessionClaims, cursor = 0, limit = 128) {
    await this.authorizeRunRead(runId, claims);
    return readAgentEventPage(this.requirePrisma(), runId, cursor, limit);
  }

  /** Transport frames are projections of persisted sequence pages, never authority. */
  createEventObservable(
    runId: string, claims: SessionClaims, lastEventId?: string,
    options?: { pollIntervalMs?: number; keepaliveIntervalMs?: number },
  ): Observable<MessageEvent> {
    const db = this.requirePrisma();
    const pollIntervalMs = options?.pollIntervalMs ?? 2000;
    const idleThreshold = Math.max(1, Math.round((options?.keepaliveIntervalMs ?? 10000) / pollIntervalMs));
    return new Observable<MessageEvent>((subscriber) => {
      let closed = false, polling = false, initialized = false, cursor = 0, idle = 0;
      const poll = async () => {
        if (closed || polling) return;
        polling = true;
        try {
          if (!initialized) {
            cursor = await resolveAgentEventCursor(db, runId, lastEventId);
            initialized = true;
          }
          const page = await readAgentEventPage(db, runId, cursor);
          for (const event of page.events) {
            if (closed) return;
            cursor = event.seq;
            subscriber.next({ id: `${runId}:${event.seq}`, type: event.eventType, data: event });
          }
          if (page.events.length) idle = 0;
          else if (++idle >= idleThreshold) {
            subscriber.next({ type: 'ping', data: { authoritative: false, timestamp: new Date().toISOString() } });
            idle = 0;
          }
          if (page.replayComplete && !closed) {
            subscriber.next({ type: 'stream-drained', data: { authoritative: false, runId,
              cursor: page.nextCursor, terminalWatermark: page.terminalWatermark, status: page.status } });
            subscriber.complete();
          }
        } catch (error) { subscriber.error(error); }
        finally { polling = false; }
      };
      const interval = setInterval(() => { void poll(); }, pollIntervalMs);
      void poll();
      return () => { closed = true; clearInterval(interval); };
    });
  }

  private async recordEvent(
    agentRunId: string,
    eventType: string,
    payload: any,
    stepIndex?: number,
    actor: string = 'system',
  ): Promise<void> {
    const db = this.requirePrisma();
    const id = `ev_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
    // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    await db.agentRunEvent.create({
      data: {
        id,
        agentRunId,
        stepIndex: stepIndex ?? null,
        eventType,
        actor,
        payload,
        timestamp: new Date()
      }
    });
  }

  /**
   * Transaction-aware event recording.
   * Uses the provided Prisma transaction client instead of the root client.
   */
  private async recordEventTx(
    tx: any,
    agentRunId: string,
    eventType: string,
    payload: any,
    stepIndex?: number,
    actor: string = 'system',
  ): Promise<void> {
    const id = `ev_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
    await tx.agentRunEvent.create({
      data: {
        id,
        agentRunId,
        stepIndex: stepIndex ?? null,
        eventType,
        actor,
        payload,
        timestamp: new Date(),
      },
    });
  }

  // ---------------------------------------------------------------------------
  // 5. Query Run Detail
  // ---------------------------------------------------------------------------

  async getRun(id: string, claims: SessionClaims): Promise<AgentRunDetailDto> {
    const db = this.requirePrisma();

    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    let run = await db.agentRun.findUnique({
      where: { id },
      include: {
        plans: { orderBy: { version: "desc" } },
        approvals: { where: { status: "PENDING" } },
        artifacts: { where: { artifactType: CONTROL_ARTIFACT } }
      }
    });

    if (!run) {
      throw new NotFoundException(`Agent run '${id}' not found`);
    }

    if (this.projectAccess) await this.projectAccess.assert(claims, run.projectId);
    // Authorize read access
    // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
    await this.resourceAuthz.assertAuthorized(
      this.subjectFromClaims(claims),
      "READ",
      {
        resourceType: "AgentRun",
        id: run.id as string,
        // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
        projectId: run.projectId as string,
        // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
        userId: run.userId as string,
        organizationId: claims.organizationId
      }
    );
    run = await exactContinuationRunTx(new RuntimeLedgerService(db), db, run);
    const savedExecution = await this.planExecution?.view(id, claims) ?? null;
    const execution = savedExecution?.planVersion === run.planVersion ? savedExecution : null;
    const inspection = await this.inspections?.view(id, claims) ?? null;
    const pauseRecord = await this.runtimeControl?.ledger.read<WorkflowPause>(db, "WORKFLOW_PAUSE", id);
    const runtimeAction = id.startsWith("rtrun_") ? await this.runtimeControl?.snapshot(claims, id) : null;
    const runtimeActionReceipt = runtimeAction?.execution ? {
      id: runtimeAction.execution.attribution.executionId, state: runtimeAction.execution.state,
      verificationState: runtimeAction.execution.verificationState,
      target: String(runtimeAction.execution.attribution.validatedInput.path ?? "")
    } : null;
    const presentation = presentPlan(run.plans?.[0]?.steps);
    if (execution?.receipts?.length) {
      presentation.evidence = [...presentation.evidence, ...execution.receipts];
    }
    const standaloneRead = runtimeReadReceipt(runtimeAction);
    if (standaloneRead && !presentation.evidence.some(e => e.id === standaloneRead.id)) presentation.evidence.push(standaloneRead);
    const projectedEvidence = new Set(presentation.evidence.flatMap(item => [
      item.id, item.runtimeReference?.receiptId, item.runtimeReference?.operationId
    ].filter((value): value is string => Boolean(value))));
    for (const reference of inspection?.evidence ?? []) {
      if (reference.verificationState !== "VERIFIED") continue;
      const operation = inspection?.operations.find(item => item.request.operationId === reference.operationId);
      if (operation && (operation.verification !== "VERIFIED" || operation.evidence?.receiptId !== reference.receiptId)) continue;
      const keys = [`runtime:${reference.receiptId}`, reference.receiptId, reference.operationId];
      if (keys.some(key => projectedEvidence.has(key))) continue;
      const tool = operation?.action.tool;
      const truncated = reference.truncated || operation?.state === "TRUNCATED";
      const receipt: EvidenceReceipt = {
        id: `runtime:${reference.receiptId}`,
        sourceType: "workspace",
        ...(tool ? { operation: tool } : {}),
        runtimeReference: reference,
        label: reference.relativePath,
        relativePath: reference.relativePath,
        outcome: truncated ? "TRUNCATED" : tool === "filesystem.read" ? "READ" : tool ? "SCANNED" : "VERIFIED",
        discovered: true,
        read: tool === "filesystem.read",
        selected: false,
        usedInAnswer: "UNKNOWN",
        truncated,
        selectionReason: "Verified runtime observation recorded by this inspection."
      };
      presentation.evidence.push(receipt);
      for (const key of keys) projectedEvidence.add(key);
    }

    return {
      ...this.mapRunSummary(run),
      inspection,
      execution,
      workflowDecision: run.plans?.[0] ? (await this.runtimeControl?.ledger.read<WorkflowDecision>(db, "WORKFLOW_DECISION", workflowDecisionKey(claims.sub, run.conversationId, run.plans[0].id)))?.payload ?? null : null,
      workflowPause: pauseRecord ? { ...pauseRecord.payload, revision: pauseRecord.revision } : null,
      runtimeActionReceipt,
      presentation,
      control: presentControl(run.artifacts ?? [], run),
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      plans: (run.plans ?? []).map((p: any) => ({
        id: p.id,
        agentRunId: p.agentRunId,
        version: p.version,
        summary: p.summary,
        steps: Array.isArray(p.steps) ? p.steps : JSON.parse(p.steps as string),
        requiresApproval: p.requiresApproval,
        status: p.status,
        reviewedBy: p.reviewedBy,
        reviewNotes: p.reviewNotes,
        createdAt: p.createdAt
      })),
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      pendingApprovals: (run.approvals ?? []).map((a: any) => ({
        id: a.id,
        agentRunId: a.agentRunId,
        approvalType: a.approvalType,
        status: a.status,
        requestedBy: a.requestedBy,
        requiredRole: a.requiredRole,
        decidedBy: a.decidedBy,
        decision: a.decision,
        notes: a.notes,
        revisedPlan: a.revisedPlan ? (typeof a.revisedPlan === "string" ? JSON.parse(a.revisedPlan) : a.revisedPlan) : null,
        dueAt: a.dueAt,
        createdAt: a.createdAt,
        decidedAt: a.decidedAt
      }))
    };
  }

  async inspectionView(id: string, claims: SessionClaims) { return await this.inspections?.view(id, claims) ?? null; }
  async executionView(id: string, claims: SessionClaims, planVersion?: number) { return await this.planExecution?.view(id, claims, planVersion) ?? null; }

  async continueInspectionConversation(conversationId: string, claims: SessionClaims, content: string, clientId?: unknown, attachmentIds: string[] = []) {
    if (!this.inspections) return null;
    const candidates = await this.requirePrisma().agentRun.findMany({ where: { conversationId, userId: claims.sub,
      status: { notIn: ["COMPLETED", "FAILED", "CANCELLED"] } }, orderBy: { createdAt: "desc" }, take: 20 });
    const active = [];
    for (const run of candidates) {
      const view = await this.inspections.view(run.id, claims);
      if (view && !["COMPLETED", "PARTIAL", "FAILED", "CANCELLED"].includes(view.state)) active.push(run);
    }
    if (active.length !== 1) return null; // Never guess between independent runs.
    const result = await this.inspections.message(active[0].id, claims, conversationId, content, clientId, attachmentIds);
    if (!result.duplicate) this.scheduleRunExecution(active[0].id, claims, content);
    return result;
  }

  /**
   * Lists agent runs visible to the authenticated subject.
   * Admin visibility is organization-scoped via Project.organizationId.
   * Non-admin visibility uses the existing AgentRun database scope filter.
   */
  async listRuns(claims: SessionClaims): Promise<AgentRunSummaryDto[]> {
    const db = this.requirePrisma();
    const subject = this.subjectFromClaims(claims);
    const projectIds = this.projectAccess ? await this.projectAccess.visibleIds(claims) : undefined;
    const orgConstraint = claims.organizationId
      ? { project: { organizationId: claims.organizationId } }
      : {};

    const where = subject.isSystemAdmin
      ? orgConstraint
      : {
        AND: [
          await this.resourceAuthz.buildDatabaseScopeFilter(subject, "AgentRun", "READ"),
          orgConstraint
        ]
      };

    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    const runs = await db.agentRun.findMany({
      where: projectIds ? { AND: [where, { projectId: { in: projectIds } }] } : where,
      orderBy: { updatedAt: "desc" },
      include: { plans: { orderBy: { version: "desc" }, take: 1, select: { steps: true } } },
      take: 50
    });

    // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
    return (runs ?? []).map((run: unknown) => this.mapRunSummary(run));
  }

  // ---------------------------------------------------------------------------
  // 6. Startup Recovery of Unfinished Runs
  // ---------------------------------------------------------------------------

  async recoverUnfinishedRuns(): Promise<{ recoveredCount: number }> {
    if (!this.prisma || !this.recovery) {
      return { recoveredCount: 0 };
    }

    try {
      // Find runs that were left unfinished before application restart
      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
      const unfinishedRuns = await this.prisma.agentRun.findMany({
        where: {
          status: { in: ["QUEUED", "PLANNING", "RUNNING"] },
          NOT: { id: { startsWith: "rtrun_" } }
        }
      });

      let recovered = 0;
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      for (const run of unfinishedRuns ?? []) {
        if (isEngineeringPlanningRun(run.id)) {
          // Runtime receipts and pending continuation recover through their own durable ledger.
          if (await this.planExecution?.isPlanRunTx(this.prisma, run.id, run.planVersion)) continue;
          if (await this.recovery.parkInterrupted(run.id, true)) recovered++;
          continue; // Interrupted generation requires a new explicit version; never call GLM on restoration.
        }
        if (this.inspections && await this.inspections.has(run.id)) continue;
        // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
        if (this.runningRunIds.has(run.id as string)) continue;

        // Never recreate session authority or redispatch physical work on process restoration.
        if (await this.recovery.parkInterrupted(run.id)) recovered++;
      }
      return { recoveredCount: recovered };
    } catch {
      return { recoveredCount: 0 };
    }
  }

  async steerRun(runId: string, claims: SessionClaims, dto: SteerRunDto): Promise<AgentRunSummaryDto> {
    if (isEngineeringPlanningRun(runId)) { await this.getRun(runId, claims); throw new BadRequestException("Generate a new immutable plan version to revise engineering intent"); }
    if (this.inspections && await this.inspections.has(runId)) { await this.inspections.view(runId, claims); throw new BadRequestException("Cancel the current inspection before changing its bound objective."); }
    const db = this.requirePrisma();

    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    const run = await db.agentRun.findUnique({ where: { id: runId } });
    if (!run) throw new NotFoundException(`Run ${runId} not found`);

    await this.resourceAuthz.assertAuthorized(
      this.subjectFromClaims(claims),
      "UPDATE",
      {
        resourceType: "AgentRun",
        id: runId,
        organizationId: claims.organizationId,
        userId: claims.sub,
      },
    );

    if (run.status !== "RUNNING") {
      throw new BadRequestException(`Steering is only allowed for RUNNING runs (current status: ${run.status})`);
    }

    // Record STEERING_SUBMITTED and audit atomically
    await db.$transaction(async (tx: any) => {
      if (this.controlStore && await this.controlStore.read(tx, runId)) {
        const current = await tx.agentRun.findUnique({ where: { id: runId } });
        await this.controlStore.lock(tx, current);
        await this.controlStore.invalidate(tx, current, "REQUEST_CHANGED", claims);
      }
      await tx.agentRunEvent.create({
        data: {
          id: `ev_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
          agentRunId: runId,
          eventType: "STEERING_SUBMITTED",
          actor: "user",
          payload: {
            instruction: dto.instruction,
            consumed: false,
          },
          timestamp: new Date(),
        },
      });

      await this.auditService.recordWithClaimsTx(tx, claims, {
        action: "AGENT_RUN_STEER",
        resourceType: "AgentRun",
        resourceId: runId,
        details: { instruction: dto.instruction },
      });
    });

    // No state change on the run itself; return fresh summary
    const refreshed = await db.agentRun.findUnique({ where: { id: runId } });
    return this.mapRunSummary(refreshed);
  }

  /**
   * Consume at most one pending steering instruction for the step that is about to run.
   * This method is called after a step finishes (checkpoint) and before the next step execution.
   */
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  private async consumePendingSteering(runId: string, _claims: SessionClaims, nextStepIndex: number, steps: AgentPlanStep[]) {
    const db = this.requirePrisma();
    // If there is no next step, nothing to steer.
    if (nextStepIndex >= steps.length) return;

    await db.$transaction(async (tx: any) => {
      // Find the oldest unconsumed steering event
      const pending = await tx.agentRunEvent.findFirst({
        where: {
          agentRunId: runId,
          eventType: "STEERING_SUBMITTED",
          payload: { path: ["consumed"], equals: false },
        },
        orderBy: [{ timestamp: "asc" }, { id: "asc" }],
      });
      if (!pending) return; // nothing to consume

      // Claim the event (optimistic claim)
      const claim = await tx.agentRunEvent.updateMany({
        where: {
          id: pending.id,
          payload: { path: ["consumed"], equals: false },
        },
        data: {
          payload: { ...pending.payload, consumed: true },
        },
      });
      if (claim.count === 0) return; // another worker claimed it

      // Apply steering to the next step's parameters
      const step = steps[nextStepIndex];
      const existing = (step.parameters?.steeringInstructions as string[]) ?? [];
      const instruction = pending.payload.instruction as string;
      step.parameters = {
        ...(step.parameters ?? {}),
        steeringInstructions: [...existing, instruction],
      };

      // Persist the updated plan steps (latest plan version)
      const plan = await tx.agentPlan.findFirst({
        where: { agentRunId: runId },
        orderBy: { version: "desc" },
      });
      if (plan) {
        await tx.agentPlan.update({
          where: { id: plan.id },
          data: { steps },
        });
      }

      // Record STEERING_CONSUMED event (immutable audit trail)
      await tx.agentRunEvent.create({
        data: {
          id: `ev_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
          agentRunId: runId,
          eventType: "STEERING_CONSUMED",
          actor: "system",
          payload: {
            originalEventId: pending.id,
            instruction,
          },
          timestamp: new Date(),
        },
      });
    });
  }

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private mapRunSummary(run: any): AgentRunSummaryDto {
    return {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      id: run.id as string,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      conversationId: run.conversationId as string,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      projectId: run.projectId as string,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      userId: run.userId as string,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      agentName: run.agentName as string,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      title: run.title as string,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      status: run.status as AgentRunStatus,
      outcome: persistedRunOutcome(run),
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      planVersion: run.planVersion as number,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      currentStepIndex: run.currentStepIndex as number,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      progressPercent: run.progressPercent as number,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      pausedAt: run.pausedAt as Date | null,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      startedAt: run.startedAt as Date | null,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      completedAt: run.completedAt as Date | null,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      failureReason: run.failureReason as string | null,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      cancellationReason: run.cancellationReason as string | null,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      createdAt: run.createdAt as Date,
      // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
      updatedAt: run.updatedAt as Date
    };
  }
}

import { Injectable, Optional, Inject } from "@nestjs/common";
import { PrismaService } from "../../data-access/prisma.service";
import { ResourceAuthorizationService } from "../../auth/resource-authz.service";
import { WorkspacePathService } from "../../workspace-intelligence/workspace-path.service";
import { WorkspaceSecurityService } from "../../workspace-intelligence/security/workspace-security.service";
import { ExecutionExecutorRegistry } from "./execution-executor.registry";
import { ExecutionPolicyService } from "./execution-policy.service";
import type {
  ExecutionApprovalState,
  ExecutionContext,
  ExecutionPolicyDecision,
  ExecutionRequest,
  ExecutionResult
} from "./execution-plane.types";

/**
 * Deny-by-default foundation. This service is the only future route to an
 * executor, and its policy gate runs before executor resolution/invocation.
 */
@Injectable()
export class ExecutionPlaneService {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private readonly cancelled = new Set<string>();

  constructor(
    private readonly policy: ExecutionPolicyService,
    private readonly executors: ExecutionExecutorRegistry,
    private readonly authorization: ResourceAuthorizationService,
    private readonly paths: WorkspacePathService,
    private readonly workspaceSecurity: WorkspaceSecurityService,
    @Optional() @Inject(PrismaService) private readonly prisma?: PrismaService
  ) {}

  async request(request: ExecutionRequest): Promise<ExecutionResult> {
    const started = Date.now();
    let decision: ExecutionPolicyDecision;
    try {
      this.validateWorkspaceScope(request);
      await this.validateDurableScope(request);
      await this.authorization.assertAuthorized(request.subject, "EXECUTE", {
        resourceType: "AgentRun",
        id: request.agentRunId,
        projectId: request.projectId,
        organizationId: request.subject.organizationId,
        userId: request.subject.userId
      });
      decision = this.policy.evaluate(request);
    } catch (error) {
      decision = this.policy.evaluate(request);
      const result = this.blocked(request, decision, Date.now() - started, this.workspaceErrorCode(error) ?? "EXECUTION_ACCESS_DENIED");
      await this.record(request, "EXECUTION_BLOCKED", result);
      return result;
    }

    await this.record(request, "EXECUTION_REQUESTED", this.metadataOnlyResult(request, decision, "QUEUED", Date.now() - started));
    const approvalState = await this.resolveApprovalState(request, decision);
    if (!decision.allowed || approvalState !== "APPROVED") {
      const errorCode = !decision.allowed ? decision.reason : approvalState === "REJECTED" ? "EXECUTION_APPROVAL_REJECTED" : "EXECUTION_APPROVAL_REQUIRED";
      const result = this.blocked(
        request,
        decision,
        Date.now() - started,
        errorCode,
        decision.allowed && approvalState === "APPROVAL_REQUIRED"
      );
      await this.record(request, result.status === "AWAITING_APPROVAL" ? "EXECUTION_APPROVAL_REQUIRED" : "EXECUTION_BLOCKED", result);
      return result;
    }

    // Kept for future capability activation. With 5D-A policy this branch is unreachable.
    const executor = this.executors.resolve(request.capability);
    if (!executor) {
      const result = this.blocked(request, decision, Date.now() - started, "EXECUTION_EXECUTOR_UNAVAILABLE");
      await this.record(request, "EXECUTION_BLOCKED", result);
      return result;
    }
    const context: ExecutionContext = {
      request,
      policy: decision,
      approvalState,
      limits: decision.limits,
      workspace: decision.workspaceScope,
      isCancellationRequested: () => this.cancelled.has(request.executionId)
    };
    await this.record(request, "EXECUTION_STARTED", this.metadataOnlyResult(request, decision, "RUNNING", Date.now() - started));
    const result = await executor.execute(context);
    await this.record(request, result.status === "CANCELLED" ? "EXECUTION_CANCELLED" : result.status === "SUCCEEDED" ? "EXECUTION_COMPLETED" : "EXECUTION_FAILED", result);
    return result;
  }

  /** Future executors can observe cancellation; 5D-A never terminates a process. */
  async cancel(executionId: string): Promise<{ executionId: string; status: "CANCELLED" }> {
    this.cancelled.add(executionId);
    return { executionId, status: "CANCELLED" };
  }

  private validateWorkspaceScope(request: ExecutionRequest): void {
    if (!request.workspace?.trustedRoot || !request.workspace?.workspaceId) throw new Error("EXECUTION_WORKSPACE_SCOPE_REQUIRED");
    const relativePath = this.paths.normalizeRelativePath(request.workspace.relativePath);
    const candidate = this.workspaceSecurity.resolveInsideRoot(request.workspace.trustedRoot, relativePath);
    if (this.workspaceSecurity.isEscapingSymlink(request.workspace.trustedRoot, candidate)) throw new Error("EXECUTION_WORKSPACE_SYMLINK_ESCAPE");
    const segments = relativePath.split("/");
    if (segments.some((segment) => this.workspaceSecurity.isForbiddenDirectoryName(segment))) throw new Error("EXECUTION_WORKSPACE_FORBIDDEN_PATH");
    if (this.workspaceSecurity.isSensitiveFile(this.paths.fileNameOf(relativePath))) throw new Error("EXECUTION_WORKSPACE_SENSITIVE_PATH");
  }

  /** If durable state is available, bind request identifiers to the persisted AgentRun. */
  private async validateDurableScope(request: ExecutionRequest): Promise<void> {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const agentRun = (this.prisma as any)?.agentRun;
    if (!agentRun || typeof agentRun.findUnique !== "function") return;
    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call
    const run = await agentRun.findUnique({
      where: { id: request.agentRunId },
      select: { id: true, projectId: true, conversationId: true, userId: true }
    });
    if (!run || run.projectId !== request.projectId || run.conversationId !== request.conversationId || run.userId !== request.subject.userId) {
      throw new Error("EXECUTION_SCOPE_MISMATCH");
    }
  }

  private async resolveApprovalState(request: ExecutionRequest, decision: ExecutionPolicyDecision): Promise<ExecutionApprovalState> {
    if (!decision.requiresApproval) return "NO_APPROVAL";
    if (!request.approvalId || !this.prisma) return "APPROVAL_REQUIRED";
    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
    const approval = await this.prisma.agentApproval.findUnique({ where: { id: request.approvalId } }).catch(() => null);
    if (!approval || approval.agentRunId !== request.agentRunId) return "APPROVAL_REQUIRED";
    if (approval.decision === "REJECTED" || approval.status === "REJECTED") return "REJECTED";
    return approval.decision === "APPROVED" || approval.status === "APPROVED" ? "APPROVED" : "APPROVAL_REQUIRED";
  }

  private blocked(request: ExecutionRequest, policy: ExecutionPolicyDecision, durationMs: number, errorCode: string, awaitingApproval = false): ExecutionResult {
    return {
      ...this.metadataOnlyResult(request, policy, awaitingApproval ? "AWAITING_APPROVAL" : "BLOCKED", durationMs),
      errorCode,
      sanitizedError: this.safeMessage(errorCode)
    };
  }

  private metadataOnlyResult(request: ExecutionRequest, policy: ExecutionPolicyDecision, status: ExecutionResult["status"], durationMs: number): ExecutionResult {
    return {
      executionId: request.executionId,
      status,
      exitCode: null,
      stdout: "",
      stderr: "",
      durationMs,
      timedOut: false,
      cancelled: false,
      truncated: false,
      artifacts: [],
      policy: { capability: policy.capability, policyVersion: policy.policyVersion, requiresApproval: policy.requiresApproval }
    };
  }

  private async record(request: ExecutionRequest, eventType: string, result: ExecutionResult): Promise<void> {
    if (!this.prisma) return;
    const details = {
      executionId: request.executionId,
      capability: request.capability,
      policyVersion: result.policy.policyVersion,
      policyRequiresApproval: result.policy.requiresApproval,
      workspaceId: request.workspace.workspaceId,
      relativePath: request.workspace.relativePath,
      status: result.status,
      durationMs: result.durationMs,
      exitCode: result.exitCode,
      truncated: result.truncated,
      errorCode: result.errorCode
    };
    const id = `ev_exec_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
    // Existing AgentRun event stream; no output, command, trusted root, metadata, or secrets are persisted.
    // A partial Prisma test/durable binding may only provide AgentRun lookup; audit
    // delegates are optional in that narrow case and must never mask a block.
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const db = this.prisma as any;
    if (db.agentRunEvent?.create) {
      await db.agentRunEvent.create({ data: { id, agentRunId: request.agentRunId, eventType, actor: "execution-plane", payload: details, timestamp: new Date() } }).catch(() => {});
    }
    if (db.agentAuditRecord?.create) {
      await db.agentAuditRecord.create({ data: { id: `audit_exec_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`, agentRunId: request.agentRunId, projectId: request.projectId, eventType, actor: request.subject.userId, actorRole: request.subject.role, details, timestamp: new Date() } }).catch(() => {});
    }
  }

  private workspaceErrorCode(error: unknown): string | undefined {
    if (error && typeof error === "object" && "code" in error && typeof (error as { code?: unknown }).code === "string") return (error as { code: string }).code;
    if (error instanceof Error && error.message.startsWith("EXECUTION_")) return error.message;
    return undefined;
  }

  private safeMessage(code: string): string {
    const messages: Record<string, string> = {
      EXECUTION_NOT_ENABLED: "This execution capability is not enabled.",
      EXECUTION_CAPABILITY_UNKNOWN: "This execution capability is not recognized.",
      EXECUTION_APPROVAL_REQUIRED: "Execution requires an approved authorization.",
      EXECUTION_APPROVAL_REJECTED: "Execution approval was rejected.",
      EXECUTION_ACCESS_DENIED: "You are not authorized to request execution.",
      EXECUTION_WORKSPACE_SCOPE_REQUIRED: "A valid workspace scope is required."
    };
    return messages[code] ?? "The execution request was blocked by policy.";
  }
}

import { ForbiddenException, Inject, Injectable, Optional } from "@nestjs/common";
import { ResourceAuthorizationService, type AuthSubject } from "../../auth/resource-authz.service";
import type { NormalizedDocumentContent } from "../../file-intelligence/models/normalized-document-content";
import type { WorkspaceNode, WorkspaceTree } from "../../workspace-intelligence/models/workspace.types";
import { WorkspaceIntelligenceError } from "../../workspace-intelligence/workspace-intelligence.errors";
import { WorkspaceIntelligenceService } from "../../workspace-intelligence/workspace-intelligence.service";
import { WorkspacePathService } from "../../workspace-intelligence/workspace-path.service";
import { WorkspaceSecurityService } from "../../workspace-intelligence/security/workspace-security.service";
import {
  AGENT_FILE_READER_LIMITS,
  type AgentFileReaderCapability,
  type CapabilityAudit,
  type EvidenceItem,
  type WorkspaceContext
} from "./workspace-context";
import { WorkspaceSourceResolver } from "./workspace-source.resolver";
import { ExecutionNotImplementedError } from "./execution-plane.types";
import { RESERVED_GITLAB_MUTATION_CAPABILITIES } from "./workspace-source.types";
import { WorkspaceBindingService } from "../../workspace-intelligence/workspace-binding.service";
import { fileReadOutcome, hasReadableContent } from "../../file-intelligence/file-read-outcome";

export interface CapabilityRequest {
  projectId: string;
  workspaceId?: string;
  name?: string;
  trustedRoot?: string;
  authorizedRoots?: string;
  workspaceVersion?: string;
  userId: string;
  userRole: AuthSubject["role"];
  organizationId?: string;
  agentRunId?: string;
  isSystemAdmin?: boolean;
}

@Injectable()
export class WorkspaceCapabilityService {
  constructor(
    private readonly workspaceIntelligence: WorkspaceIntelligenceService,
    private readonly resolver: WorkspaceSourceResolver,
    private readonly paths: WorkspacePathService,
    private readonly security: WorkspaceSecurityService,
    @Optional() @Inject(ResourceAuthorizationService) private readonly resourceAuthz?: ResourceAuthorizationService,
    @Optional() @Inject(WorkspaceBindingService) private readonly bindings?: WorkspaceBindingService
  ) {}

  gitlabMutation(_capability: (typeof RESERVED_GITLAB_MUTATION_CAPABILITIES)[number]): never {
    throw new WorkspaceIntelligenceError("WORKSPACE_SOURCE_UNSUPPORTED");
  }

  powershellExecute(): never {
    throw new ExecutionNotImplementedError();
  }

  async discover(request: CapabilityRequest, relativePath?: string, query = ""): Promise<{
    tree: WorkspaceTree;
    context: WorkspaceContext;
    audit: CapabilityAudit;
  }> {
    const started = Date.now();
    await this.assertProjectRead(request);
    const trusted = this.resolver.resolveLocal(this.sourceInput(request));
    const { workspace, tree } = await this.workspaceIntelligence.inspectWorkspace(trusted, query);
    let scoped = tree;
    if (relativePath) {
      const node = this.findNode(tree.root, this.paths.normalizeRelativePath(relativePath));
      if (!node || node.type !== "directory") {
        throw new WorkspaceIntelligenceError("WORKSPACE_FILE_NOT_FOUND");
      }
      scoped = {
        ...tree,
        root: node
      };
    }
    this.assertNoAbsolutePaths(scoped.root);
    const audit = this.audit("workspace.discover", request, started, {
      relativePaths: relativePath ? [this.paths.normalizeRelativePath(relativePath)] : [],
      truncated: scoped.truncated,
      allowed: true,
      status: "ok"
    });
    return {
      tree: scoped,
      context: this.contextFromTree(request, workspace.source === "local" ? "local" : "unknown", scoped, [], []),
      audit
    };
  }

  async list(request: CapabilityRequest, relativeDirectory: string): Promise<{
    path: string;
    children: WorkspaceNode[];
    audit: CapabilityAudit;
  }> {
    const started = Date.now();
    await this.assertProjectRead(request);
    const dir = relativeDirectory.trim() === "" || relativeDirectory === "." ? "" : this.paths.normalizeRelativePath(relativeDirectory);
    if (dir.split("/").some((segment) => this.security.isForbiddenDirectoryName(segment))) {
      throw new WorkspaceIntelligenceError("WORKSPACE_FILE_ACCESS_DENIED");
    }
    const { tree } = await this.discover(request);
    const node = dir ? this.findNode(tree.root, dir) : tree.root;
    if (!node || node.type !== "directory") {
      throw new WorkspaceIntelligenceError("WORKSPACE_FILE_NOT_FOUND");
    }
    const children = (node.children ?? []).slice(0, AGENT_FILE_READER_LIMITS.MAX_LIST_CHILDREN);
    const truncated = (node.children ?? []).length > children.length;
    const audit = this.audit("workspace.list", request, started, {
      relativePaths: [dir || "."],
      truncated: truncated || tree.truncated,
      allowed: true,
      status: "ok"
    });
    return { path: dir, children, audit };
  }

  async search(request: CapabilityRequest, query: string, pathPrefix?: string): Promise<{
    query: string;
    matches: Array<{ path: string; name: string; type: string; kind?: string }>;
    truncated: boolean;
    audit: CapabilityAudit;
  }> {
    const started = Date.now();
    await this.assertProjectRead(request);
    const needle = query.trim().toLowerCase();
    if (!needle) {
      throw new WorkspaceIntelligenceError("WORKSPACE_PATH_INVALID", "Search query is required.");
    }
    const prefix = pathPrefix ? this.paths.normalizeRelativePath(pathPrefix) : "";
    const { tree } = await this.discover(request, undefined, query);
    const matches: Array<{ path: string; name: string; type: string; kind?: string }> = [];
    this.walk(tree.root, (node) => {
      if (!node.path) return;
      if (prefix && node.path !== prefix && !node.path.startsWith(`${prefix}/`)) return;
      if (node.type === "file" && this.security.isSensitiveFile(node.name)) return;
      if (node.path.toLowerCase().includes(needle) || node.name.toLowerCase().includes(needle)) {
        matches.push({
          path: node.path,
          name: node.name,
          type: node.type,
          kind: typeof node.metadata?.kind === "string" ? node.metadata.kind : undefined
        });
      }
    });
    matches.sort((a, b) => a.path.localeCompare(b.path, "en"));
    const truncated = matches.length > AGENT_FILE_READER_LIMITS.MAX_SEARCH_RESULTS;
    const limited = matches.slice(0, AGENT_FILE_READER_LIMITS.MAX_SEARCH_RESULTS);
    const audit = this.audit("workspace.search", request, started, {
      relativePaths: limited.map((m) => m.path),
      truncated: truncated || tree.truncated,
      allowed: true,
      status: "ok"
    });
    return { query: needle, matches: limited, truncated: truncated || tree.truncated, audit };
  }

  async inspect(request: CapabilityRequest, relativePath: string): Promise<{
    document: NormalizedDocumentContent;
    audit: CapabilityAudit;
  }> {
    const started = Date.now();
    await this.assertProjectRead(request);
    const safePath = this.paths.normalizeRelativePath(relativePath);
    const trusted = this.resolver.resolveLocal(this.sourceInput(request));
    try {
      const document = await this.workspaceIntelligence.inspectFile(trusted, safePath);
      if (this.containsAbsolutePath(document.fileName)) {
        throw new WorkspaceIntelligenceError("WORKSPACE_INSPECTION_FAILED");
      }
      const audit = this.audit("file.inspect", request, started, {
        relativePaths: [safePath],
        truncated: document.truncated,
        allowed: true,
        status: "ok"
      });
      return { document, audit };
    } catch (err) {
      if (err instanceof WorkspaceIntelligenceError && err.code === "WORKSPACE_FILE_ACCESS_DENIED") {
        this.audit("file.inspect", request, started, {
          relativePaths: [safePath],
          truncated: false,
          allowed: false,
          status: "denied",
          deniedReason: "WORKSPACE_FILE_ACCESS_DENIED"
        });
      }
      throw err;
    }
  }

  async collectEvidence(request: CapabilityRequest, relativePaths: string[]): Promise<{
    context: WorkspaceContext;
    audit: CapabilityAudit;
  }> {
    const started = Date.now();
    await this.assertProjectRead(request);
    const unique = [...new Set(relativePaths)];
    const limitedPaths = unique.slice(0, AGENT_FILE_READER_LIMITS.MAX_EVIDENCE_ITEMS);
    const evidence: EvidenceItem[] = [];
    const warnings: string[] = [];
    const limitsEncountered: string[] = [];
    if (unique.length > limitedPaths.length) {
      limitsEncountered.push("MAX_EVIDENCE_ITEMS");
      warnings.push("Evidence collection was capped at the configured file limit.");
    }
    const auditedPaths: string[] = [];
    for (const requestedPath of limitedPaths) {
      let relativePath = "[invalid path]";
      try {
        relativePath = this.paths.normalizeRelativePath(requestedPath);
        auditedPaths.push(relativePath);
        const { document } = await this.inspect(request, relativePath);
        const text = document.text.slice(0, AGENT_FILE_READER_LIMITS.MAX_EVIDENCE_TEXT_CHARS);
        evidence.push({
          relativePath,
          outcome: document.scanned ? "SCANNED" : document.truncated || text.length < document.text.length ? "TRUNCATED" : "READ",
          fileType: document.detectedMime,
          extractorId: document.extractorId,
          text,
          truncated: document.truncated || text.length < document.text.length,
          warnings: document.warnings,
          sourceIdentity: `${request.projectId}:${relativePath}`
        });
      } catch (err) {
        if (relativePath === "[invalid path]") auditedPaths.push(relativePath);
        const outcome = fileReadOutcome(err);
        const notice = `File read outcome: ${outcome}`;
        warnings.push(`${relativePath}: ${notice}`);
        evidence.push({ relativePath, outcome, text: "", truncated: false, warnings: [notice], sourceIdentity: `${request.projectId}:${relativePath}` });
      }
    }
    const context: WorkspaceContext = {
      workspaceId: request.workspaceId ?? request.projectId,
      projectId: request.projectId,
      source: "local",
      selectedFiles: evidence.filter(item => hasReadableContent(item.outcome)).map((item) => item.relativePath),
      evidence,
      warnings,
      truncated: limitsEncountered.length > 0 || evidence.some((item) => item.truncated),
      provenance: evidence.map((item) => item.sourceIdentity),
      limitsEncountered
    };
    const audit = this.audit("evidence.collect", request, started, {
      relativePaths: auditedPaths,
      truncated: context.truncated,
      allowed: true,
      status: "ok"
    });
    return { context, audit };
  }

  private sourceInput(request: CapabilityRequest) {
    return {
      workspaceId: request.workspaceId ?? request.projectId,
      projectId: request.projectId,
      name: request.name ?? request.projectId,
      trustedRoot: request.trustedRoot,
      authorizedRoots: request.authorizedRoots
    };
  }

  private async assertProjectRead(request: CapabilityRequest): Promise<void> {
    if (this.bindings) {
      const bound = await this.bindings.resolve({ sub: request.userId, role: request.userRole, organizationId: request.organizationId,
        email: "", displayName: "" }, request.projectId, request.workspaceVersion);
      Object.assign(request, bound.context, { isSystemAdmin: request.userRole === "Admin", workspaceVersion: bound.binding.version });
    }
    if (!this.resourceAuthz) return;
    const subject: AuthSubject = {
      userId: request.userId,
      email: "",
      displayName: "",
      role: request.userRole,
      organizationId: request.organizationId,
      isSystemAdmin: request.isSystemAdmin === true
    };
    try {
      await this.resourceAuthz.assertAuthorized(subject, "READ", {
        resourceType: "Project",
        id: request.projectId,
        projectId: request.projectId,
        organizationId: request.organizationId
      });
    } catch (err) {
      if (err instanceof ForbiddenException) {
        throw new WorkspaceIntelligenceError("WORKSPACE_ACCESS_DENIED");
      }
      throw err;
    }
  }

  private findNode(root: WorkspaceNode, relativePath: string): WorkspaceNode | undefined {
    if (!relativePath || root.path === relativePath) return root;
    for (const child of root.children ?? []) {
      if (child.path === relativePath) return child;
      if (relativePath.startsWith(`${child.path}/`)) {
        const found = this.findNode(child, relativePath);
        if (found) return found;
      }
    }
    return undefined;
  }

  private walk(node: WorkspaceNode, visit: (node: WorkspaceNode) => void): void {
    visit(node);
    for (const child of node.children ?? []) {
      this.walk(child, visit);
    }
  }

  private assertNoAbsolutePaths(node: WorkspaceNode): void {
    if (this.containsAbsolutePath(node.path) || this.containsAbsolutePath(node.name)) {
      throw new WorkspaceIntelligenceError("WORKSPACE_INSPECTION_FAILED");
    }
    for (const child of node.children ?? []) {
      this.assertNoAbsolutePaths(child);
    }
  }

  private containsAbsolutePath(value: string): boolean {
    return this.paths.isAbsolutePath(value);
  }

  private contextFromTree(
    request: CapabilityRequest,
    source: "local" | "unknown",
    tree: WorkspaceTree,
    evidence: EvidenceItem[],
    selectedFiles: string[]
  ): WorkspaceContext {
    return {
      workspaceId: tree.workspaceId,
      projectId: request.projectId,
      source,
      fileCount: tree.fileCount,
      directoryCount: tree.directoryCount,
      totalBytes: tree.totalBytes,
      selectedFiles,
      evidence,
      warnings: tree.warnings,
      truncated: tree.truncated,
      provenance: [`workspace:${tree.workspaceId}`],
      limitsEncountered: tree.truncated ? ["WORKSPACE_DISCOVERY_TRUNCATED"] : []
    };
  }

  private audit(
    capability: AgentFileReaderCapability,
    request: CapabilityRequest,
    started: number,
    extra: {
      relativePaths: string[];
      truncated: boolean;
      allowed: boolean;
      status: CapabilityAudit["status"];
      deniedReason?: string;
    }
  ): CapabilityAudit {
    return {
      capability,
      agentRunId: request.agentRunId,
      projectId: request.projectId,
      workspaceId: request.workspaceId ?? request.projectId,
      relativePaths: extra.relativePaths,
      allowed: extra.allowed,
      deniedReason: extra.deniedReason,
      truncated: extra.truncated,
      durationMs: Date.now() - started,
      status: extra.status
    };
  }
}

import { BadRequestException, Inject, Injectable, NotFoundException, ServiceUnavailableException } from '@nestjs/common';
import { PrismaService } from '../../data-access/prisma.service';

export const AGENT_PROJECTION_LIMITS = Object.freeze({ scannedEvents: 64, events: 32, textBytes: 512, toolOutputBytes: 2048, totalBytes: 16384, identityBytes: 192 });
const TYPES = ['TOOL_CALL', 'TOOL_RESULT', 'STATUS_CHANGE', 'PROGRESS', 'WORKFLOW_PAUSE_REQUESTED', 'WORKFLOW_PAUSED', 'WORKFLOW_RESUMED', 'WORKFLOW_STOPPED'];
const STATE_TYPES = TYPES.filter(t => !t.startsWith('TOOL_'));
type DurableEvent = { id: string; agentRunId: string; seq: number; stepIndex: number | null; eventType: string; payload: unknown };
type State = { runId: string; cursor: number; watermark: number; stepIndex: number; status: string };
export interface ProjectedEvent {
  seq: number; reference: string; stepIndex: number | null; type: string;
  actionId?: string; skillId?: string; actionReference?: string; correlation?: 'MATCHED' | 'UNMATCHED' | 'AMBIGUOUS';
  text?: string; output?: string; truncated: boolean;
}

function object(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
}
function clip(value: string, bytes: number): { text: string; truncated: boolean } {
  let text = '', size = 0;
  for (const character of value) {
    const next = Buffer.byteLength(character, 'utf8');
    if (size + next > bytes) return { text, truncated: true };
    text += character; size += next;
  }
  return { text, truncated: false };
}
function identity(value: unknown): string | undefined {
  if (typeof value !== 'string' || !value || Buffer.byteLength(value) > AGENT_PROJECTION_LIMITS.identityBytes) return undefined;
  return value;
}
function key(event: DurableEvent): string | undefined {
  const p = object(event.payload);
  const declared = [p.toolCallId, p.actionId, p.operationId].filter(v => v !== undefined);
  if (declared.some(v => !identity(v)) || new Set(declared).size > 1) return undefined;
  const explicit = identity(declared[0]);
  const skill = identity(p.skillId);
  return explicit ? JSON.stringify([event.stepIndex, 'explicit', explicit]) : skill ? JSON.stringify([event.stepIndex, 'legacy-skill', skill]) : undefined;
}
function render(event: DurableEvent): ProjectedEvent {
  const p = object(event.payload);
  // Explicit allowlist: never forward parameters, approval payloads, model/token frames or arbitrary objects.
  const text = typeof p.summary === 'string' ? p.summary : typeof p.newStatus === 'string' ? p.newStatus : '';
  const bounded = clip(text, AGENT_PROJECTION_LIMITS.textBytes);
  const output = object(p.output);
  const rawOutput = typeof p.output === 'string' ? p.output :
    ['summary', 'text', 'content', 'status', 'receiptId'].filter(k => typeof output[k] === 'string')
      .map(k => `${k}: ${output[k]}`).join('\n');
  const tool = clip(event.eventType === 'TOOL_RESULT' ? rawOutput : '', AGENT_PROJECTION_LIMITS.toolOutputBytes);
  return { seq: event.seq, reference: `agent-event:${event.agentRunId}:${event.seq}`, stepIndex: event.stepIndex,
    type: event.eventType, ...(identity(p.skillId) ? { skillId: identity(p.skillId) } : {}),
    ...(identity(p.toolCallId) ?? identity(p.actionId) ?? identity(p.operationId) ? { actionId: identity(p.toolCallId) ?? identity(p.actionId) ?? identity(p.operationId) } : {}), ...(bounded.text ? { text: bounded.text } : {}), ...(tool.text ? { output: tool.text } : {}),
    truncated: bounded.truncated || tool.truncated };
}

/** Pure, deterministic projection of a server-read snapshot; never evidence admission or execution authority. */
export function projectDurableAgentContext(state: State, source: DurableEvent[], olderEventsOmitted = false) {
  if (!identity(state.runId) || !identity(state.status) || !Number.isSafeInteger(state.cursor) || state.cursor < 0 ||
      !Number.isSafeInteger(state.watermark) || state.watermark < state.cursor || !Number.isSafeInteger(state.stepIndex) || state.stepIndex < 0)
    throw new BadRequestException('AGENT_PROJECTION_STATE_INVALID');
  if (source.length > AGENT_PROJECTION_LIMITS.scannedEvents) throw new BadRequestException('AGENT_PROJECTION_SCAN_BOUND');
  const warnings = new Set<string>();
  const events: DurableEvent[] = [];
  let previous = 0;
  for (const event of source) {
    if (event.agentRunId !== state.runId || !Number.isSafeInteger(event.seq) || event.seq <= previous || event.seq > state.cursor ||
        (event.stepIndex !== null && (!Number.isSafeInteger(event.stepIndex) || event.stepIndex < 0)))
      throw new ServiceUnavailableException('AGENT_PROJECTION_EVENT_INVALID');
    previous = event.seq;
    if (!TYPES.includes(event.eventType)) continue;
    if (!event.payload || typeof event.payload !== 'object' || Array.isArray(event.payload)) { warnings.add('MALFORMED_PAYLOAD'); continue; }
    if (STATE_TYPES.includes(event.eventType) || (event.stepIndex !== null && event.stepIndex >= Math.max(0, state.stepIndex - 1) && event.stepIndex <= state.stepIndex)) events.push(event);
  }
  const units: ProjectedEvent[][] = [];
  const pending = new Map<string, ProjectedEvent[][]>();
  for (const event of events) {
    const item = render(event);
    if (event.eventType === 'TOOL_CALL') {
      const unit = [item]; units.push(unit);
      const k = key(event);
      if (k) { const queue = pending.get(k) ?? []; queue.push(unit); pending.set(k, queue); }
      else { item.correlation = 'UNMATCHED'; warnings.add('MISSING_ACTION_IDENTITY'); }
    } else if (event.eventType === 'TOOL_RESULT') {
      const k = key(event); const queue = k ? pending.get(k) ?? [] : [];
      if (queue.length === 1) {
        item.actionReference = queue[0][0].reference; item.correlation = 'MATCHED'; queue[0][0].correlation = 'MATCHED';
        queue[0].push(item); pending.delete(k!);
      } else {
        item.correlation = queue.length > 1 ? 'AMBIGUOUS' : 'UNMATCHED';
        warnings.add(queue.length > 1 ? 'AMBIGUOUS_ACTION_RESULT' : 'MISSING_ACTION'); units.push([item]);
        if (k && queue.length > 1) { for (const unit of queue) unit[0].correlation = 'AMBIGUOUS'; pending.delete(k); }
      }
    } else units.push([item]);
  }
  for (const queue of pending.values()) for (const unit of queue) { unit[0].correlation = 'UNMATCHED'; warnings.add('MISSING_RESULT'); }
  const base = { version: 1 as const, authority: 'NONE' as const, source: 'POSTGRESQL_AGENT_RUN_EVENTS' as const,
    ...state, limits: AGENT_PROJECTION_LIMITS };
  const selected: ProjectedEvent[] = [];
  let omitted = olderEventsOmitted;
  const finish = () => ({ ...base, events: [...selected].sort((a,b) => a.seq-b.seq), warnings: [...warnings].sort(),
    truncated: omitted || selected.some(e => e.truncated) });
  // Keep action/result units together under all bounds; never cut serialized JSON.
  for (const unit of [...units].sort((a,b) => b.at(-1)!.seq-a.at(-1)!.seq)) {
    if (selected.length + unit.length > AGENT_PROJECTION_LIMITS.events) { omitted = true; continue; }
    selected.push(...unit);
    if (Buffer.byteLength(JSON.stringify(finish())) > AGENT_PROJECTION_LIMITS.totalBytes - 256) { selected.splice(selected.length-unit.length); omitted = true; }
  }
  const projection = finish();
  if (Buffer.byteLength(JSON.stringify(projection)) > AGENT_PROJECTION_LIMITS.totalBytes - 256) throw new ServiceUnavailableException('AGENT_PROJECTION_SIZE_INVALID');
  return projection;
}

@Injectable()
export class AgentContextProjectionService {
  constructor(@Inject(PrismaService) private readonly db: PrismaService) {}
  // Internal server-side API only. Callers retain their existing run/conversation authorization.
  async build(runId: string, options: { cursor?: number; stepIndex?: number } = {}) {
    return this.db.$transaction(tx => this.buildInTransaction(tx, runId, options), { isolationLevel: 'RepeatableRead' });
  }
  /** Shares the recovery snapshot; never opens a second transaction or mutates events. */
  async buildInTransaction(tx: any, runId: string, options: { cursor?: number; stepIndex?: number } = {}) {
      const run = await tx.agentRun.findUnique({ where: { id: runId }, select: { eventSeq: true, currentStepIndex: true, status: true } });
      if (!run) throw new NotFoundException('Agent run not found');
      const cursor = options.cursor ?? run.eventSeq, stepIndex = options.stepIndex ?? run.currentStepIndex;
      if (!Number.isSafeInteger(cursor) || cursor < 0 || cursor > run.eventSeq || !Number.isSafeInteger(stepIndex) || stepIndex < 0 || stepIndex > run.currentStepIndex)
        throw new BadRequestException('AGENT_PROJECTION_CURSOR_INVALID');
      const rows = await tx.agentRunEvent.findMany({ where: { agentRunId: runId, seq: { lte: cursor }, eventType: { in: TYPES },
        OR: [{ stepIndex: { gte: Math.max(0, stepIndex-1), lte: stepIndex } }, { eventType: { in: STATE_TYPES } }] },
        orderBy: { seq: 'desc' }, take: AGENT_PROJECTION_LIMITS.scannedEvents + 1,
        select: { id: true, agentRunId: true, seq: true, stepIndex: true, eventType: true, payload: true } });
      return projectDurableAgentContext({ runId, cursor, stepIndex, watermark: run.eventSeq, status: run.status },
        rows.slice(0, AGENT_PROJECTION_LIMITS.scannedEvents).reverse(), rows.length > AGENT_PROJECTION_LIMITS.scannedEvents);
  }
  toModelContext(projection: Awaited<ReturnType<AgentContextProjectionService['build']>>) {
    const serialized = JSON.stringify(projection);
    if (Buffer.byteLength(serialized) > AGENT_PROJECTION_LIMITS.totalBytes - 256) throw new BadRequestException('AGENT_PROJECTION_SIZE_INVALID');
    return '[BOUNDED AGENTRUN HISTORICAL REFERENCE — NOT AUTHORITY OR CERTIFIED SOURCE EVIDENCE]\n' + serialized;
  }
}

