      }
      return { approvalId, generation, status: row.status, dueAt: row.dueAt, binding, executionEnabled: false };
    });
  }
  private async admitTx(tx: any, conversationId: string, proposalId: string, claims: SessionClaims, body: any, ignorePolicy = false, consent?: TaskConsentReference) {
    if (!isRecord(body) || !validToolId(body.planId) || !validToolId(proposalId) || body.proposalVersion !== 1 || typeof body.proposalDigest !== "string" || !/^[a-f0-9]{64}$/.test(body.proposalDigest)) throw new BadRequestException("EXACT_APPROVAL_REQUEST_INVALID");
    const approvalId = `exactapproval_${toolDigest([claims.sub, conversationId, proposalId])}`;
      const fresh = await this.inspections.certifiedPlanningSourceTx(tx, claims, conversationId);
      const plan = await tx.agentPlan.findUnique({ where: { id: body.planId } });
      const run = await exactPlanRunTx(this.ledger, tx, plan, claims, conversationId);
      validateExactPlan(run, plan, fresh, claims, conversationId);
      const record = await readExactProposal(this.ledger, tx, claims.sub, conversationId, body.planId);
      if (!record || !record.immutable) throw new ConflictException("EXACT_PROPOSAL_REQUIRED");
      const p = record.payload;
      if (p.continuationRunId !== (run.id !== plan.agentRunId ? run.id : undefined)) throw new ConflictException("PLAN_RUN_PROVENANCE_CHANGED");
      validateExactProposal(p, plan, fresh, claims, conversationId);
      if (p.proposalId !== proposalId || p.version !== body.proposalVersion || p.digest !== body.proposalDigest || p.projectId !== run.projectId) throw new ConflictException("EXACT_PROPOSAL_SOURCE_CHANGED");
      const reviewer = await this.identity.actor(tx, claims.sub, claims.organizationId!, run.projectId,
        { id: claims.sessionId!, issuedAt: claims.iat ?? 0, expiresAt: claims.exp! });
      await this.resources.assertAuthorized(toolSubject(reviewer), "APPROVE", { resourceType: "Approval", id: approvalId,
        projectId: run.projectId, organizationId: claims.organizationId, requiredRole: "Technical Reviewer" });
      const base = { kind: "EXACT_PROPOSAL_APPROVAL", version: 1, proposalId: p.proposalId, proposalVersion: p.version, proposalDigest: p.digest,
        planId: p.planId, planVersion: p.planVersion, planDigest: p.planDigest, conversationId, projectId: p.projectId,
        userId: p.userId, organizationId: p.organizationId, workspace: p.workspace, sourceRunId: p.sourceRunId,
        sourceSequence: p.sourceSequence, sourceDigest: p.sourceDigest,
        sourceFingerprint: toolDigest({ workspace: p.workspace, sourceRunId: p.sourceRunId, sourceSequence: p.sourceSequence,
          sourceDigest: p.sourceDigest, evidenceReferences: p.evidenceReferences }), executionEnabled: false };
      const head = await this.ledger.read<any>(tx, "EXACT_APPROVAL_HEAD", [claims.sub, conversationId, proposalId]);
      const row = await tx.agentApproval.findUnique({ where: { id: this.generationId([claims.sub, conversationId, proposalId], head?.payload.generation ?? 1) } });
      const stored = row?.revisedPlan?.taskConsent as TaskConsentReference | undefined;
      const reference = ignorePolicy ? undefined : consent ?? stored;
      if (reference) {
        await this.policies().checkTx(tx, reference, { ...p, session: { id: claims.sessionId, issuedAt: claims.iat ?? 0, expiresAt: claims.exp } });
        const match = await this.policies().selectTx(tx, p, claims, reference);
        if (!match || toolDigest(match) !== toolDigest(reference)) throw new ConflictException("TASK_CONSENT_EXPLICIT_ACTION_REQUIRED");
      }
      const bound = { ...base, ...(reference ? { taskConsent: reference } : {}) };
      return { fresh, run, reviewer, proposal: p, binding: { ...bound, fingerprint: toolDigest(bound) } };
  }
  async approvedTx(tx: any, conversationId: string, proposalId: string, claims: SessionClaims, body: any) {
    const admitted = await this.admitTx(tx, conversationId, proposalId, claims, body);
    const row = await tx.agentApproval.findUnique({ where: { id: body.approvalId } });
    const key = [claims.sub, conversationId, proposalId];
    const head = await this.ledger.read<any>(tx, "EXACT_APPROVAL_HEAD", key);
    const expectedId = this.generationId(key, head?.payload.generation ?? 1);
    if (head && head.payload.approvalId !== expectedId) throw new ConflictException("EXACT_APPROVAL_CHANGED");
    admitted.binding = this.generationBinding(admitted.binding, head?.payload);
    if (!row || row.id !== expectedId || row.agentRunId !== admitted.run.id || row.approvalType !== "EXACT_PROPOSAL" ||
      row.requestedBy !== claims.sub || row.status !== "APPROVED" || row.decision !== "APPROVED" || !row.decidedAt || !row.decidedBy ||
      toolDigest(row.revisedPlan) !== toolDigest(admitted.binding)) throw new ConflictException("EXACT_APPROVAL_REQUIRED");
    if (!row.dueAt || !Number.isFinite(+new Date(row.dueAt)) || +new Date(row.dueAt) <= Date.now()) throw new ConflictException("APPROVAL_EXPIRED");
    const reviewer = await this.identity.actor(tx, row.decidedBy, claims.organizationId!, admitted.run.projectId);
    await this.resources.assertAuthorized(toolSubject(reviewer), "APPROVE", { resourceType: "Approval", id: row.id,
      projectId: admitted.run.projectId, organizationId: claims.organizationId, requiredRole: "Technical Reviewer" });
    return { ...admitted, approval: row };
  }
  private generationId(key: string[], generation: number) {
    if (!Number.isSafeInteger(generation) || generation < 1 || generation > 10000) throw new ConflictException("EXACT_APPROVAL_CHANGED");
    return `exactapproval_${toolDigest(generation === 1 ? key : [...key, generation])}`;
  }
  private generationBinding(binding: any, head?: { generation: number; requestId: string }) {
    if (!head) return binding; // Preserve already-approved legacy fingerprints.
    if (!validToolId(head.requestId)) throw new ConflictException("EXACT_APPROVAL_CHANGED");
    const { fingerprint, ...base } = binding;
    const value = { ...base, generation: head.generation, requestId: head.requestId };
    return { ...value, fingerprint: toolDigest(value) };
  }
  private async event(tx: any, runId: string, claims: SessionClaims, eventType: string, approvalId: string, fingerprint: string) {
    const payload = { approvalId, fingerprint, executionEnabled: false };
    await tx.agentRunEvent.create({ data: { agentRunId: runId, eventType, actor: claims.sub, payload } });
    await this.audit.recordWithClaimsTx(tx, claims, { action: eventType, resourceType: "AgentRun", resourceId: runId, details: payload });
  }
}

import { BadRequestException, ConflictException, Inject, Injectable } from "@nestjs/common";
import type { SessionClaims } from "../../auth/auth.dto";
import { ResourceAuthorizationService } from "../../auth/resource-authz.service";
import { RuntimeIdentityService } from "../../trusted-runtime/runtime-identity.service";
import { RuntimeLedgerService } from "../../trusted-runtime/runtime-ledger.service";
import { RUNTIME_LIMITS } from "../../trusted-runtime/runtime.contract";
import { WorkspaceRuntimeEvidenceService } from "../../workspace-intelligence/workspace-runtime-evidence.service";
import { isRecord, toolDigest, toolSubject, validToolId } from "../tools/tool-contract";
import { ExactProposalApprovalService } from "./exact-proposal-approval.service";

/** One-use workflow permit. Runtime tool authorization and dispatch remain separate gates. */
@Injectable()
export class ExactProposalPermitService {
  constructor(@Inject(RuntimeLedgerService) private readonly ledger: RuntimeLedgerService,
    @Inject(ExactProposalApprovalService) private readonly approvals: ExactProposalApprovalService,
    @Inject(WorkspaceRuntimeEvidenceService) private readonly evidence: WorkspaceRuntimeEvidenceService,
    @Inject(RuntimeIdentityService) private readonly identity: RuntimeIdentityService,
    @Inject(ResourceAuthorizationService) private readonly resources: ResourceAuthorizationService) {}

  private validate(body: unknown): asserts body is Record<string, any> {
    if (!isRecord(body) || Object.keys(body).filter(k => k !== "requestId").sort().join(",") !== "approvalId,planId,proposalDigest,proposalVersion" ||
      (body.requestId !== undefined && !validToolId(body.requestId)) ||
      !validToolId(body.approvalId) || !validToolId(body.planId) || body.proposalVersion !== 1 ||
      typeof body.proposalDigest !== "string" || !/^[a-f0-9]{64}$/.test(body.proposalDigest)) throw new BadRequestException("EXACT_PERMIT_REQUEST_INVALID");
  }
  private async admit(tx: any, conversationId: string, proposalId: string, claims: SessionClaims, body: any) {
    const a = await this.approvals.approvedTx(tx, conversationId, proposalId, claims, body);
    await this.resources.assertAuthorized(toolSubject(a.reviewer), "EXECUTE", { resourceType: "Project", id: a.run.projectId,
      projectId: a.run.projectId, organizationId: claims.organizationId });
    const grant = await this.identity.activeGrant(tx, a.proposal.workspace.runtimeId, a.run.projectId);
    const device = (await this.identity.device(tx, a.proposal.workspace.runtimeId)).payload;
    if (grant.userId !== claims.sub || grant.organizationId !== claims.organizationId ||
      device.fingerprint !== a.proposal.workspace.runtimeFingerprint ||
      a.proposal.actions.some(action => !grant.capabilities.includes(action.tool))) throw new ConflictException("EXACT_PERMIT_RUNTIME_CHANGED");
    const binding = { ...a.binding, approvalId: a.approval.id, approvalState: "APPROVED", approvalDecisionBy: a.approval.decidedBy,
      approvalDecidedAt: new Date(a.approval.decidedAt).toISOString(), actionsDigest: toolDigest(a.proposal.actions), grantId: grant.grantId,
      grantVersion: grant.version, connectionEpoch: device.connectionEpoch,
      sessionId: claims.sessionId, sessionIssuedAt: claims.iat, sessionExpiresAt: claims.exp };
    return { ...a, grant, binding };
  }
  async issue(conversationId: string, proposalId: string, claims: SessionClaims, body: unknown) {
    this.validate(body);
    if (!validToolId(proposalId)) throw new BadRequestException("EXACT_PERMIT_REQUEST_INVALID");
    const key = [claims.sub, conversationId, proposalId], initial = await this.ledger.transaction(tx => this.admit(tx, conversationId, proposalId, claims, body));
    for (const ref of initial.fresh.references) await this.evidence.admit(claims, initial.run.projectId, initial.fresh.sourceConversationId, ref);
    return this.ledger.transaction(async tx => {
      const current = await this.admit(tx, conversationId, proposalId, claims, body);
      if (toolDigest(current.binding) !== toolDigest(initial.binding)) throw new ConflictException("EXACT_PERMIT_SOURCE_CHANGED");
      await this.unusedTx(tx, key);
      const head = await this.ledger.read<any>(tx, "EXACT_PERMIT_HEAD", key);
      const generation = head?.payload.generation ?? 1;
      const prior = await this.ledger.read<any>(tx, "EXACT_EXECUTION_PERMIT", this.issuanceKey(key, generation));
      if (prior && !prior.immutable) throw new ConflictException("EXACT_PERMIT_CHANGED");
      if (head && (!prior || head.payload.permitId !== prior.payload.permitId || head.payload.requestId !== prior.payload.requestId)) throw new ConflictException("EXACT_PERMIT_CHANGED");
      const replay = body.requestId && await this.ledger.read<any>(tx, "EXACT_PERMIT_GENERATION", [...key, body.requestId]);
      if (replay && (replay.payload.generation !== generation || replay.payload.permitId !== prior?.payload.permitId)) throw new ConflictException("EXACT_PERMIT_SUPERSEDED");
      if (prior) {
        if (!body.requestId || prior.payload.requestId === body.requestId) {
          await this.checkTx(tx, prior.payload, current.binding); return prior.payload;
        }
        if (Date.parse(prior.payload.expiresAt) > Date.now()) {
          await this.checkTx(tx, prior.payload, current.binding, true);
          throw new ConflictException("EXACT_PERMIT_REQUEST_CONFLICT");
        }
        // admit() validates current approval, session, active grant and action
        // capabilities. An expired-unused renewal captures their current state;
        // artifact, grant identity and connection bindings still match exactly.
        const renewalBinding: Record<string, unknown> = { ...current.binding };
        for (const field of ["approvalId", "generation", "requestId", "fingerprint", "approvalDecisionBy", "approvalDecidedAt", "taskConsent",
          "sessionId", "sessionIssuedAt", "sessionExpiresAt", "grantVersion"]) {
          if (Object.prototype.hasOwnProperty.call(prior.payload.binding, field)) renewalBinding[field] = prior.payload.binding[field];
          else delete renewalBinding[field]; // Legacy approval bindings omit generation/requestId.
        }
        await this.checkTx(tx, prior.payload, renewalBinding, true);
      } else if (head || replay) throw new ConflictException("EXACT_PERMIT_CHANGED");
      const nextGeneration = prior ? generation + 1 : 1;
      const issuanceKey = this.issuanceKey(key, nextGeneration);
      // PostgreSQL's default now() is transaction start, earlier than admission.
      // Use one timestamp for persisted creation and the maximum expiry bound.
      const createdAt = new Date(Date.now());
      const expires = Math.min(createdAt.getTime() + RUNTIME_LIMITS.permitMs, +new Date(current.approval.dueAt), claims.exp! * 1000,
        current.grant.expiresAt ? Date.parse(current.grant.expiresAt) : Infinity);
      if (!Number.isFinite(expires) || expires <= Date.now()) throw new ConflictException("EXACT_PERMIT_EXPIRED");
      const base = { version: 1, kind: "EXACT_EXECUTION_PERMIT", permitId: `exactpermit_${toolDigest(issuanceKey)}`, binding: current.binding,
        ...(body.requestId ? { generation: nextGeneration, requestId: body.requestId } : {}),
        expiresAt: new Date(expires).toISOString(), oneUse: true, runtimeDispatchEnabled: false };
      const permit = { ...base, digest: toolDigest(base) };
      await this.ledger.create(tx, "EXACT_EXECUTION_PERMIT", issuanceKey, permit, { immutable: true, createdAt });
      if (body.requestId) {
        const next = { generation: nextGeneration, requestId: body.requestId, permitId: permit.permitId };
        await this.ledger.create(tx, "EXACT_PERMIT_GENERATION", [...key, body.requestId], next, { immutable: true });
        if (head) await this.ledger.update(tx, head, next);
        else await this.ledger.create(tx, "EXACT_PERMIT_HEAD", key, next, { immutable: false });
      }
      await tx.agentRunEvent.create({ data: { agentRunId: current.run.id, eventType: "EXACT_EXECUTION_PERMIT_CREATED", actor: claims.sub,
        payload: { permitId: permit.permitId, digest: permit.digest, approvalId: body.approvalId, executionPerformed: false } } });
      return permit;
    });
  }
  private issuanceKey(key: string[], generation: number) {
    if (!Number.isSafeInteger(generation) || generation < 1 || generation > 10000) throw new ConflictException("EXACT_PERMIT_GENERATION_LIMIT");
    return generation === 1 ? key : [...key, generation];
  }
  private async unusedTx(tx: any, key: string[]) {
    // Scope-wide reservation prevents a second execution across all issuances.
    if (await this.ledger.read(tx, "EXACT_PERMIT_CONSUMPTION", key) ||
      await this.ledger.read(tx, "EXACT_PERMIT_CONSUMPTION", `exactpermit_${toolDigest(key)}`)) throw new ConflictException("EXACT_PERMIT_CONSUMED");
  }
  private async checkTx(tx: any, permit: any, binding: any, allowExpired = false) {
    const { digest, ...base } = permit;
    if (digest !== toolDigest(base) || permit.kind !== "EXACT_EXECUTION_PERMIT" || permit.oneUse !== true ||
      toolDigest(permit.binding) !== toolDigest(binding)) throw new ConflictException("EXACT_PERMIT_CHANGED");
    if (!Number.isFinite(Date.parse(permit.expiresAt)) || (!allowExpired && Date.parse(permit.expiresAt) <= Date.now())) throw new ConflictException("EXACT_PERMIT_EXPIRED");
    if (await this.ledger.read(tx, "EXACT_PERMIT_CONSUMPTION", permit.permitId)) throw new ConflictException("EXACT_PERMIT_CONSUMED");
  }
  /** Internal atomic reservation for the production executor, never exposed as a dispatch endpoint. */
  async consumeTx(tx: any, conversationId: string, proposalId: string, claims: SessionClaims, body: unknown, executionIntentId: string, expected?: { permitId: string; generation: number }) {
    this.validate(body);
    if (!validToolId(executionIntentId) || !validToolId(proposalId)) throw new BadRequestException("EXACT_PERMIT_REQUEST_INVALID");
    const current = await this.admit(tx, conversationId, proposalId, claims, body);
    const key = [claims.sub, conversationId, proposalId];
    await this.unusedTx(tx, key);
    const head = await this.ledger.read<any>(tx, "EXACT_PERMIT_HEAD", key);
    if (head && body.requestId !== head.payload.requestId) throw new ConflictException("EXACT_PERMIT_SUPERSEDED");
    const record = await this.ledger.read<any>(tx, "EXACT_EXECUTION_PERMIT", this.issuanceKey(key, head?.payload.generation ?? 1));
    if (!record || !record.immutable) throw new ConflictException("EXACT_PERMIT_REQUIRED");
    if (head && (record.payload.permitId !== head.payload.permitId || record.payload.requestId !== head.payload.requestId)) throw new ConflictException("EXACT_PERMIT_CHANGED");
    if (!head && body.requestId !== record.payload.requestId) throw new ConflictException("EXACT_PERMIT_CHANGED");
    if (expected && (record.payload.permitId !== expected.permitId || (record.payload.generation ?? 1) !== expected.generation))
      throw new ConflictException("EXACT_PERMIT_SUPERSEDED");
    await this.checkTx(tx, record.payload, current.binding);
    await this.ledger.create(tx, "EXACT_PERMIT_CONSUMPTION", record.payload.permitId,
      { permitId: record.payload.permitId, permitDigest: record.payload.digest, executionIntentId, consumedAt: new Date().toISOString() }, { immutable: true });
    await this.ledger.create(tx, "EXACT_PERMIT_CONSUMPTION", key,
      { permitId: record.payload.permitId, permitDigest: record.payload.digest, executionIntentId }, { immutable: true });
    return record.payload;
  }
}

import { BadRequestException, ConflictException, Inject, Injectable } from "@nestjs/common";
import type { SessionClaims } from "../../auth/auth.dto";
import { AiGatewayService } from "../../ai-gateway/ai-gateway.service";
import { WorkspaceRuntimeEvidenceService } from "../../workspace-intelligence/workspace-runtime-evidence.service";
import { RuntimeLedgerService } from "../../trusted-runtime/runtime-ledger.service";
import { AgentInspectionService } from "../inspection/agent-inspection.service";
import { isRecord, toolDigest, validToolId } from "../tools/tool-contract";
import type { AgentPlanningResult } from "../understanding/agent-understanding.types";
import { prepareExactActions } from "./exact-plan-proposal";
import type { ExactPlanAction } from "./plan-execution-state";
import { changeSetForPlan, selectionHead, assertRecommendation, readExactProposal } from "../../conversation/change-selection";
import { createHash } from "node:crypto";
import { runtimeInput } from "../../trusted-runtime/runtime.contract";
import { workspaceTarget } from "../../workspace-intelligence/workspace-runtime.contract";
import { heroConstrainedResult } from "../understanding/hero-title-constraint";

/** Shared immutable plan admission; proposal preparation grants no execution authority. */
export function validateExactPlan(run: any, plan: any, fresh: any, claims: SessionClaims, conversationId: string): AgentPlanningResult {
  const identity = plan?.steps?.[0]?.parameters?.engineeringPlan, result = plan?.steps?.[0]?.parameters?.planning;
  if (!run || run.conversationId !== conversationId || run.userId !== claims.sub || run.projectId !== fresh.conversation.projectId ||
    !plan || plan.version !== run.planVersion || plan.status !== "PLAN_READY" || !identity || !result?.plan?.validation?.valid || result.plan.readiness !== "PLAN_READY") throw new ConflictException("PLAN_READY_REQUIRED");
  const { digest, ...base } = identity;
  if (identity.executionEnabled !== false || identity.planId !== plan.id || identity.planVersion !== plan.version ||
    digest !== toolDigest({ ...base, summary: plan.summary, result }) || identity.sourceRunId !== fresh.sourceRunId ||
    identity.sourceConversationId !== fresh.sourceConversationId || identity.understandingDigest !== fresh.digest ||
    identity.understandingSequence !== fresh.checkpoint.sequence || toolDigest(identity.evidenceReferences) !== toolDigest(fresh.references) ||
    toolDigest(identity.workspace) !== toolDigest({ workspaceId: fresh.binding.workspaceId, bindingVersion: fresh.binding.version,
      runtimeId: fresh.binding.runtimeId, runtimeFingerprint: fresh.binding.runtimeFingerprint })) throw new ConflictException("PLAN_SOURCE_CHANGED");
  return result;
}

const continuationId = (userId: string, conversationId: string, planId: string) => `exact_plan_run_${toolDigest([userId, conversationId, planId])}`;

/** Resolve the real persisted run; a historical plan is never retargeted or copied. */
export async function exactPlanRunTx(ledger: RuntimeLedgerService, tx: any, plan: any, claims: SessionClaims, conversationId: string, create = false) {
  if (!plan) throw new ConflictException("PLAN_READY_REQUIRED");
  const original = await tx.agentRun.findUnique({ where: { id: plan.agentRunId } });
  if (!original || original.userId !== claims.sub || original.conversationId !== conversationId) throw new ConflictException("PLAN_RUN_PROVENANCE_CHANGED");
  const id = continuationId(claims.sub, conversationId, plan.id), identity = plan.steps?.[0]?.parameters?.engineeringPlan;
  const parts = [claims.sub, conversationId, plan.id];
  const base = { runId: id, originalRunId: original.id, userId: claims.sub, organizationId: claims.organizationId,
    conversationId, projectId: original.projectId, planId: plan.id, planVersion: plan.version, planDigest: identity?.digest,
    stepsDigest: toolDigest(plan.steps), sourceRunId: identity?.sourceRunId, sourceSequence: identity?.understandingSequence,
    sourceDigest: identity?.understandingDigest, workspace: identity?.workspace };
  const prior = await ledger.read<any>(tx, "EXACT_PLAN_CONTINUATION", parts);
  if (prior) {
    const run = await tx.agentRun.findUnique({ where: { id } });
    if (!prior.immutable || toolDigest(prior.payload) !== toolDigest(base) || !run || run.userId !== claims.sub ||
      run.conversationId !== conversationId || run.projectId !== original.projectId || run.planVersion !== plan.version)
      throw new ConflictException("PLAN_RUN_PROVENANCE_CHANGED");
    return run;
  }
  if (original.planVersion === plan.version) return original;
  if (!create) throw new ConflictException("PLAN_READY_REQUIRED");
  if (!Number.isSafeInteger(original.planVersion) || original.planVersion < plan.version || plan.status !== "PLAN_READY" ||
    identity?.planId !== plan.id || identity?.planVersion !== plan.version || !plan.steps?.[0]?.parameters?.planning?.plan?.validation?.valid ||
    !["COMPLETED", "FAILED"].includes(original.status)) throw new ConflictException("PLAN_READY_REQUIRED");
  // Creation is inside the admission transaction: any source/plan validation
  // failure rolls back both the new run and its immutable lineage record.
  const run = await tx.agentRun.create({ data: { id, userId: claims.sub, conversationId, projectId: original.projectId,
    agentName: original.agentName ?? "SekhemEngineer", title: `Exact proposal continuation · Plan ${plan.version}`,
    status: "COMPLETED", planVersion: plan.version, progressPercent: 0, completedAt: new Date() } });
  await ledger.create(tx, "EXACT_PLAN_CONTINUATION", parts, base, { immutable: true });
  await tx.agentRunEvent.create({ data: { id: `${id}_provenance`, agentRunId: id, eventType: "PLAN_CONTINUATION_CREATED", actor: claims.sub,
    payload: { ...base, executionPerformed: false } } });
  return run;
}

/** Read-only relation projection for a continuation with no physical plan FK. */
export async function exactContinuationRunTx(ledger: RuntimeLedgerService, tx: any, run: any) {
  if (!run?.id?.startsWith("exact_plan_run_")) return run;
  const event = await tx.agentRunEvent.findUnique({ where: { id: `${run.id}_provenance` } });
  const p = event?.payload;
  if (!p || event.agentRunId !== run.id || event.eventType !== "PLAN_CONTINUATION_CREATED") throw new ConflictException("PLAN_RUN_PROVENANCE_CHANGED");
  const plan = await tx.agentPlan.findUnique({ where: { id: p.planId } });
  const resolved = await exactPlanRunTx(ledger, tx, plan, { sub: run.userId, organizationId: p.organizationId } as SessionClaims, run.conversationId);
  if (resolved.id !== run.id) throw new ConflictException("PLAN_RUN_PROVENANCE_CHANGED");
  const record = await ledger.read<any>(tx, "EXACT_PLAN_CONTINUATION", [run.userId, run.conversationId, plan.id]);
  if (!record || toolDigest(p) !== toolDigest({ ...record.payload, executionPerformed: false })) throw new ConflictException("PLAN_RUN_PROVENANCE_CHANGED");
  return { ...run, plans: [plan] };
}

export interface ExactProposal {
  changeReview?: { changeSetId: string; changeSetVersion: number; changeSetDigest: string; selectedRevision: number; selectedDigest: string; changeIds: string[]; previousProposalId?: string };
  continuationRunId?: string;
  version: 1; proposalId: string; digest: string; status: "EXACT_PROPOSAL_READY";
  conversationId: string; userId: string; organizationId: string; projectId: string;
  planId: string; planVersion: number; planDigest: string; requestDigest: string;
  sourceRunId: string; sourceSequence: number; sourceDigest: string;
  workspace: { workspaceId: string; bindingVersion: number; runtimeId: string; runtimeFingerprint: string };
  evidenceReferences: any[];
  artifacts: Array<{ stepId: string; artifactId: string; dependencies: string[] }>;
  actions: ExactPlanAction[];
  changes: Array<{ path: string; before: string; after: string; originalHash: string; updatedHash: string }>;
  authorization: "NOT_GRANTED"; executionEnabled: false;
}

export function validateExactProposal(proposal: ExactProposal, plan: any, fresh: any, claims: SessionClaims, conversationId: string) {
  const { digest, ...base } = proposal;
  if (digest !== toolDigest(base) || proposal.status !== "EXACT_PROPOSAL_READY" || proposal.authorization !== "NOT_GRANTED" || proposal.executionEnabled !== false ||
    proposal.conversationId !== conversationId || proposal.userId !== claims.sub || proposal.organizationId !== claims.organizationId ||
    proposal.planId !== plan.id || proposal.planVersion !== plan.version || proposal.planDigest !== plan.steps[0].parameters.engineeringPlan.digest ||
    proposal.sourceRunId !== fresh.sourceRunId || proposal.sourceSequence !== fresh.checkpoint.sequence || proposal.sourceDigest !== fresh.digest ||
    toolDigest(proposal.workspace) !== toolDigest(plan.steps[0].parameters.engineeringPlan.workspace) || toolDigest(proposal.evidenceReferences) !== toolDigest(fresh.references)) throw new ConflictException("EXACT_PROPOSAL_SOURCE_CHANGED");
}

@Injectable()
export class ExactProposalService {
  constructor(@Inject(RuntimeLedgerService) private readonly ledger: RuntimeLedgerService,
    @Inject(AgentInspectionService) private readonly inspections: AgentInspectionService,
    @Inject(AiGatewayService) private readonly gateway: AiGatewayService,
    @Inject(WorkspaceRuntimeEvidenceService) private readonly evidence: WorkspaceRuntimeEvidenceService) {}

  /** Reuse revalidates the immutable artifact without changing endpoint replay semantics. */
  async continuePlan(conversationId: string, claims: SessionClaims, body: unknown) {
    return this.prepare(conversationId, claims, body, true);
  }
  async prepare(conversationId: string, claims: SessionClaims, body: unknown, reuse = false): Promise<ExactProposal> {
    if (!isRecord(body) || Object.keys(body).sort().join(",") !== "planDigest,planId,planVersion,requestId" ||
      !validToolId(body.planId) || !validToolId(body.requestId) || !Number.isSafeInteger(body.planVersion) || Number(body.planVersion) < 1 ||
      typeof body.planDigest !== "string" || !/^[a-f0-9]{64}$/.test(body.planDigest)) throw new BadRequestException("EXACT_PROPOSAL_REQUEST_INVALID");
    const review = await this.ledger.transaction(tx => changeSetForPlan(this.ledger, tx, claims.sub, conversationId, String(body.planId)));
    if (review) return this.prepareSelected(conversationId, claims, body, reuse);
    const key = [claims.sub, conversationId, body.planId], requestDigest = toolDigest(body);
    const admit = async (tx: any) => {
      const fresh = await this.inspections.certifiedPlanningSourceTx(tx, claims, conversationId);
      const plan = await tx.agentPlan.findUnique({ where: { id: body.planId } });
      const existing = await this.ledger.read<ExactProposal>(tx, "EXACT_PROPOSAL", key);
      const run = await exactPlanRunTx(this.ledger, tx, plan, claims, conversationId, !existing);
      if (existing && existing.payload.continuationRunId !== (run.id !== plan.agentRunId ? run.id : undefined)) throw new ConflictException("PLAN_RUN_PROVENANCE_CHANGED");
      const result = validateExactPlan(run, plan, fresh, claims, conversationId);
      if (plan.version !== body.planVersion || plan.steps[0].parameters.engineeringPlan.digest !== body.planDigest) throw new ConflictException("PLAN_SOURCE_CHANGED");
      return { fresh, plan, run, result };
    };
    const admitted = await this.ledger.transaction(async tx => {
      const source = await admit(tx), prior = await this.ledger.read<ExactProposal>(tx, "EXACT_PROPOSAL", key);
      if (prior) {
        validateExactProposal(prior.payload, source.plan, source.fresh, claims, conversationId);
        if (!reuse && prior.payload.requestDigest !== requestDigest) throw new ConflictException("EXACT_PROPOSAL_REQUEST_CONFLICT");
      }
      return { ...source, prior };
    });
    for (const reference of admitted.fresh.references) await this.evidence.admit(claims, admitted.fresh.conversation.projectId, admitted.fresh.sourceConversationId, reference);
    if (admitted.prior) return admitted.prior.payload;
    const actions = await prepareExactActions({ gateway: this.gateway, evidence: this.evidence }, claims, admitted.fresh, admitted.result);
    // Re-admission owns its own ledger transaction; keep it outside the final lock.
    for (const reference of admitted.fresh.references) await this.evidence.admit(claims, admitted.fresh.conversation.projectId, admitted.fresh.sourceConversationId, reference);
    return this.ledger.transaction(async tx => {
      const { fresh, plan, run, result } = await admit(tx);
      if (fresh.digest !== admitted.fresh.digest || toolDigest(plan.steps) !== toolDigest(admitted.plan.steps)) throw new ConflictException("EXACT_PROPOSAL_SOURCE_CHANGED");
      const prior = await this.ledger.read<ExactProposal>(tx, "EXACT_PROPOSAL", key);
      if (prior) {
        validateExactProposal(prior.payload, plan, fresh, claims, conversationId);
        if (!reuse && prior.payload.requestDigest !== requestDigest) throw new ConflictException("EXACT_PROPOSAL_REQUEST_CONFLICT");
        return prior.payload;
      }
      const proposalId = `exact_proposal_${toolDigest(key)}`;
      const base = { version: 1 as const, proposalId, status: "EXACT_PROPOSAL_READY" as const, conversationId, userId: claims.sub,
        ...(run.id !== plan.agentRunId ? { continuationRunId: run.id } : {}),
        organizationId: claims.organizationId!, projectId: run.projectId, planId: plan.id, planVersion: plan.version, planDigest: String(body.planDigest), requestDigest,
        sourceRunId: fresh.sourceRunId, sourceSequence: fresh.checkpoint.sequence, sourceDigest: fresh.digest,
        workspace: plan.steps[0].parameters.engineeringPlan.workspace, evidenceReferences: fresh.references,
        artifacts: result.plan.steps.filter(s => s.type === "PROPOSE" && s.effect === "READ_ONLY").map(s => ({ stepId: s.id, artifactId: proposalId, dependencies: s.dependencies })),
        actions, changes: actions.flatMap(a => a.change ? [{ path: a.relativePath, ...a.change }] : []), authorization: "NOT_GRANTED" as const, executionEnabled: false as const };
      const proposal: ExactProposal = { ...base, digest: toolDigest(base) };
      await this.ledger.create(tx, "EXACT_PROPOSAL", key, proposal, { immutable: true });
      await tx.agentRunEvent.create({ data: { id: proposalId, agentRunId: run.id, eventType: "EXACT_PROPOSAL_READY", actor: claims.sub,
        payload: { proposalId, digest: proposal.digest, planId: plan.id, planVersion: plan.version, executionPerformed: false } } });
      await tx.conversationMessage.create({ data: { id: `${proposalId}_result`, conversationId, senderId: "agent", senderType: "assistant",
        content: `EXACT_PROPOSAL_READY · ${proposalId}\n` + proposal.changes.map(c => `${c.path}\nBefore:\n${c.before}\nAfter:\n${c.after}`).join("\n") + "\nAuthorization NOT_GRANTED. No operation executed.",
        metadata: { exactProposalId: proposalId, exactProposalDigest: proposal.digest, planId: plan.id, planVersion: plan.version, executionPerformed: false } } });
      await tx.conversation.update({ where: { id: conversationId }, data: { updatedAt: new Date() } });
      return proposal;
    });
  }

  private async prepareSelected(conversationId: string, claims: SessionClaims, body: any, reuse: boolean): Promise<ExactProposal> {
    const admit = async (tx: any) => {
      const set = await changeSetForPlan(this.ledger, tx, claims.sub, conversationId, body.planId);
      if (!set || set.organizationId !== claims.organizationId || set.plan.version !== body.planVersion || set.plan.digest !== body.planDigest) throw new ConflictException("CHANGE_SET_CHANGED");
      const fresh = await this.inspections.certifiedPlanningSourceTx(tx, claims, conversationId, set.source.runId);
      const plan = await tx.agentPlan.findUnique({ where: { id: set.plan.id } });
      const run = await exactPlanRunTx(this.ledger, tx, plan, claims, conversationId, true);
      const result = validateExactPlan(run, plan, fresh, claims, conversationId);
      if (fresh.digest !== set.source.digest || fresh.checkpoint.sequence !== set.source.sequence || fresh.checkpoint.version !== set.source.version ||
        toolDigest(set.workspace) !== toolDigest(plan.steps[0].parameters.engineeringPlan.workspace)) throw new ConflictException("CHANGE_SET_SOURCE_CHANGED");
      await assertRecommendation(tx, set);
      const head = await selectionHead(this.ledger, tx, set);
      if (!head || !head.payload.keptChangeIds.length) throw new ConflictException("CHANGE_SELECTION_KEEP_REQUIRED");
      const selection = head.payload;
      const kept = set.changes.filter(c => selection.decisions[c.id] === "KEEP");
      if (toolDigest(kept.map(c => c.id)) !== toolDigest(selection.keptChangeIds)) throw new ConflictException("CHANGE_SELECTION_STALE");
      const prior = await readExactProposal(this.ledger, tx, claims.sub, conversationId, plan.id);
      if (prior) { validateExactProposal(prior.payload, plan, fresh, claims, conversationId); if (!reuse && prior.payload.requestDigest !== toolDigest(body)) throw new ConflictException("EXACT_PROPOSAL_REQUEST_CONFLICT"); }
      return { set, selection, kept, fresh, plan, run, result, prior };
    };
    const a = await this.ledger.transaction(admit);
    for (const reference of a.fresh.references) await this.evidence.admit(claims, a.fresh.conversation.projectId, a.fresh.sourceConversationId, reference);
    if (a.prior) return a.prior.payload;
    const paths = [...new Set(a.kept.map(c => c.path))];
    const steps = a.result.plan.steps.filter(s => !(s.type === "PROPOSE" && s.effect === "READ_ONLY"));
    const writes = steps.filter(s => s.type === "IMPLEMENT" && s.effect === "WRITE"), reads = steps.filter(s => s.type === "VERIFY" && s.effect === "READ_ONLY");
    if (paths.length !== 1 || writes.length !== 1 || reads.length !== 1 || steps.length !== 2 ||
      ![writes[0], reads[0]].every(step => { const scope = a.result.understanding.scope.filter(s => step.scopeRefs.includes(s.id) && s.kind === "EVIDENCE"); return scope.length > 0 && scope.every(s => s.reference === paths[0]); })) throw new ConflictException("CHANGE_SELECTION_PLAN_SCOPE_UNSUPPORTED");
    let source: string | undefined;
    for (const ref of a.fresh.references.filter(r => r.relativePath === paths[0] && !r.truncated)) {
      const admitted = await this.evidence.admit(claims, a.fresh.conversation.projectId, a.fresh.sourceConversationId, ref);
      if (admitted.operation?.tool !== "filesystem.read" || admitted.reference.truncated || typeof admitted.file.text !== "string") continue;
      if (a.kept.every(c => (c.evidenceRef === `runtime:${ref.receiptId}` || c.evidenceRef === ref.receiptId) && c.beforeSha256 === createHash("sha256").update(admitted.file.text).digest("hex"))) source = admitted.file.text;
    }
    if (source === undefined) throw new ConflictException("CHANGE_SET_EXACT_EVIDENCE_REQUIRED");
    const ordered = [...a.kept].sort((x, y) => x.start - y.start);
    for (let i = 0; i < ordered.length; i++) {
      const c = ordered[i];
      if (!Number.isSafeInteger(c.start) || !Number.isSafeInteger(c.end) || c.start < 0 || c.end < c.start || c.end > source.length || source.slice(c.start, c.end) !== c.before ||
        i > 0 && (ordered[i - 1].end > c.start || ordered[i - 1].start === c.start)) throw new ConflictException("CHANGE_SELECTION_RANGE_INVALID");
    }
    let after = source;
    for (const c of [...ordered].reverse()) after = after.slice(0, c.start) + c.after + after.slice(c.end);
    for (const constraint of a.result.plan.constraints.filter(c => c.rule === "HERO_TITLE_TEXT_ONLY"))
      if (!constraint.textChange || heroConstrainedResult(source, constraint.textChange) !== after) throw new ConflictException("HERO_SCOPE_VIOLATION");
    const hash = (s: string) => createHash("sha256").update(s).digest("hex"), originalHash = hash(source), updatedHash = hash(after);
    const start = ordered[0].start, end = ordered.at(-1)!.end, before = source.slice(start, end);
    const proposed = after.slice(start, after.length - (source.length - end));
    if (before.length + proposed.length > 8192 || originalHash === updatedHash) throw new ConflictException("CHANGE_SELECTION_RANGE_INVALID");
    const path = workspaceTarget(a.fresh.binding.rootPath, paths[0]);
    const actions: ExactPlanAction[] = [{ stepId: writes[0].id, tool: "filesystem.write", relativePath: path.relativePath,
      input: runtimeInput("filesystem.write", { path: path.absolutePath, content: after, expectedSha256: originalHash }), expectedAfterHash: updatedHash,
      change: { before, after: proposed, originalHash, updatedHash } }, { stepId: reads[0].id, tool: "filesystem.read", relativePath: path.relativePath,
      input: runtimeInput("filesystem.read", { path: path.absolutePath }), expectedAfterHash: updatedHash }];
    return this.ledger.transaction(async tx => {
      const b = await admit(tx);
      if (b.selection.digest !== a.selection.digest || b.set.digest !== a.set.digest || b.fresh.digest !== a.fresh.digest) throw new ConflictException("CHANGE_SELECTION_STALE");
      if (b.prior) return b.prior.payload;
      const key = [claims.sub, conversationId, b.plan.id, b.set.id, b.selection.revision], proposalId = `exact_proposal_${toolDigest(key)}`;
      const base = { version: 1 as const, proposalId, status: "EXACT_PROPOSAL_READY" as const, conversationId, userId: claims.sub, organizationId: claims.organizationId!, projectId: b.run.projectId,
        ...(b.run.id !== b.plan.agentRunId ? { continuationRunId: b.run.id } : {}), planId: b.plan.id, planVersion: b.plan.version, planDigest: body.planDigest, requestDigest: toolDigest(body),
        sourceRunId: b.fresh.sourceRunId, sourceSequence: b.fresh.checkpoint.sequence, sourceDigest: b.fresh.digest, workspace: b.set.workspace, evidenceReferences: b.fresh.references,
        artifacts: b.result.plan.steps.filter(s => s.type === "PROPOSE" && s.effect === "READ_ONLY").map(s => ({ stepId: s.id, artifactId: proposalId, dependencies: s.dependencies })),
        actions, changes: [{ path: paths[0], before, after: proposed, originalHash, updatedHash }], authorization: "NOT_GRANTED" as const, executionEnabled: false as const,
        changeReview: { changeSetId: b.set.id, changeSetVersion: b.set.version, changeSetDigest: b.set.digest, selectedRevision: b.selection.revision,
          selectedDigest: b.selection.digest, changeIds: b.selection.keptChangeIds, ...(b.set.proposal ? { previousProposalId: b.set.proposal.id } : {}) } };
      const proposal: ExactProposal = { ...base, digest: toolDigest(base) };
      await this.ledger.create(tx, "EXACT_PROPOSAL", key, proposal, { immutable: true });
      await this.ledger.create(tx, "CHANGE_SELECTED_PROPOSAL", [claims.sub, conversationId, b.plan.id], { key, revision: b.selection.revision, digest: b.selection.digest }, { immutable: true });
      await tx.agentRunEvent.create({ data: { id: proposalId, agentRunId: b.run.id, eventType: "EXACT_PROPOSAL_READY", actor: claims.sub, payload: { proposalId, digest: proposal.digest, planId: b.plan.id, planVersion: b.plan.version, executionPerformed: false, changeReview: proposal.changeReview } } });
      await tx.conversationMessage.create({ data: { id: `${proposalId}_result`, conversationId, senderId: "agent", senderType: "assistant", content: "Exact proposal ready from kept changes. Human approval is still required. Nothing was executed.", metadata: { exactProposalId: proposalId, exactProposalDigest: proposal.digest, planId: b.plan.id, planVersion: b.plan.version, executionPerformed: false } } });
      await tx.conversation.update({ where: { id: conversationId }, data: { updatedAt: new Date() } });
      return proposal;
    });
  }
}

import { ConflictException } from "@nestjs/common";
import { RuntimeLedgerService } from "../../trusted-runtime/runtime-ledger.service";
import { toolDigest } from "../tools/tool-contract";
import { executionRecord, type PlanExecutionState } from "./plan-execution-state";
import { reserveRepair } from "./repair-attempt";

interface ExecutionLineage {
  version: 1; id: string; userId: string; organizationId: string; projectId: string;
  rootPlanId: string; attempts: number; limit: 2;
  runId: string; planId: string; requestId: string; terminal: boolean;
}

/** Called inside the existing serialized permit/reservation transaction.
 * parent is obtained only from the validated server-owned conversation transfer.
 */
export async function reserveLineageTx(ledger: RuntimeLedgerService, tx: any,
  previous: PlanExecutionState | undefined, parent: PlanExecutionState | undefined,
  next: Parameters<typeof reserveRepair>[1] & {
    runId: string; requestId: string; userId: string; organizationId: string; projectId: string;
  }) {
  let source = previous ?? parent;
  if (source && (source.userId !== next.userId || source.organizationId !== next.organizationId || source.projectId !== next.projectId))
    throw new ConflictException("REPAIR_LINEAGE_SCOPE_CHANGED");
  // A completed local execution is terminal. A new independent plan has its own root.
  if ((source?.status === "COMPLETED" || source?.status === "CANCELLED" && !source.repair) && source.planId !== next.planId) source = undefined;
  if (source && source.planId !== next.planId && source.status !== "FAILED") throw new ConflictException("REPAIR_UNSETTLED");
  const rootPlanId = source?.rootPlanId ?? source?.repair?.rootPlanId ?? source?.planId ?? next.planId;
  const lineageId = source?.lineageId ?? `execution_lineage_${toolDigest([next.userId, next.organizationId, next.projectId, rootPlanId])}`;
  const record = await ledger.read<ExecutionLineage>(tx, "EXECUTION_LINEAGE", lineageId);
  if (record) {
    const root = record.payload;
    if (root.id !== lineageId || root.userId !== next.userId || root.organizationId !== next.organizationId || root.projectId !== next.projectId ||
        root.rootPlanId !== rootPlanId || root.limit !== 2 || !Number.isSafeInteger(root.attempts) || root.attempts < 0 || root.attempts > 2)
      throw new ConflictException("REPAIR_LINEAGE_CHANGED");
    if (root.terminal) throw new ConflictException("REPAIR_LINEAGE_COMPLETED");
    // A fork pointing at an older failure must resolve the latest root attempt.
    const latest = (await executionRecord(tx, root.runId))?.payload;
    if (!latest || latest.lineageId !== lineageId || latest.planId !== root.planId || latest.requestId !== root.requestId)
      throw new ConflictException("REPAIR_LINEAGE_CHANGED");
    if (latest.status === "COMPLETED") throw new ConflictException("REPAIR_LINEAGE_COMPLETED");
    source = { ...latest, ...(root.attempts ? { repair: { ...latest.repair!, attempt: root.attempts, rootPlanId } } : {}) };
  } else if (source?.lineageId) throw new ConflictException("REPAIR_LINEAGE_REQUIRED");
  // Historical server-ledger state is imported once; client counters are never accepted.
  const repair = reserveRepair(source, next);
  const attempts = repair?.attempt ?? 0;
  const payload: ExecutionLineage = { version: 1, id: lineageId, userId: next.userId, organizationId: next.organizationId, projectId: next.projectId,
    rootPlanId, attempts, limit: 2, runId: next.runId, planId: next.planId, requestId: next.requestId, terminal: false };
  if (record) await ledger.update(tx, record, payload);
  else await ledger.create(tx, "EXECUTION_LINEAGE", lineageId, payload, { immutable: false });
  return { lineageId, rootPlanId, repair };
}

export async function completeLineageTx(ledger: RuntimeLedgerService, tx: any, state: PlanExecutionState) {
  if (!state.lineageId) return;
  const record = await ledger.read<ExecutionLineage>(tx, "EXECUTION_LINEAGE", state.lineageId);
  if (!record || record.payload.runId !== state.runId || record.payload.planId !== state.planId || record.payload.requestId !== state.requestId)
    throw new ConflictException("REPAIR_LINEAGE_CHANGED");
  if (!record.payload.terminal) await ledger.update(tx, record, { ...record.payload, terminal: true });
}

import { RuntimeLedgerService } from "../../trusted-runtime/runtime-ledger.service";
import { toolDigest } from "../tools/tool-contract";
import type { RuntimeTool } from "../../trusted-runtime/runtime.contract";
import { WorkspaceStoreService } from "../../workspace-intelligence/workspace-store.service";

export interface ExactPlanAction {
  stepId: string;
  tool: RuntimeTool;
  input: Record<string, unknown>;
  relativePath: string;
  expectedAfterHash?: string;
  change?: { before: string; after: string; originalHash: string; updatedHash: string };
}

/** Execution progress is separate from the immutable engineering plan. */
export interface PlanExecutionState {
  version: 1;
  runId: string; planId: string; planVersion: number; planDigest: string;
  conversationId: string; userId: string; organizationId: string; projectId: string;
  requestId: string;
  session: { id: string; issuedAt: number; expiresAt: number };
  /** Fresh authority applies only to unfinished read-back; the reservation session stays immutable. */
  verificationSession?: { id: string; issuedAt: number; expiresAt: number };
  verificationRequestId?: string;
  workspace: { workspaceId: string; version: number; runtimeId: string; runtimeFingerprint: string; rootPath: string };
  status: "PREPARING" | "BLOCKED" | "AWAITING_APPROVAL" | "RUNNING" | "COMPLETED" | "FAILED" | "CANCELLED";
  reason?: string | null;
  phase?: string;
  actions: ExactPlanAction[];
  exactPermit?: { permitId: string; digest: string; generation: number; executionIntentId: string; binding: Record<string, any> };
  proposalId?: string;
  proposalDigest?: string;
  artifacts?: Array<{ stepId: string; artifactId: string; dependencies: string[] }>;
  completed: Record<string, { receiptId: string; verifiedAt: string; durationMs: number }>;
  observations?: Record<string, import("./step-observation").StepObservation>;
  failureDiagnostics?: Record<string, import("./failure-diagnostic").FailureDiagnostic>;
  executionSource?: import("./repair-attempt").ExecutionSource;
  repair?: import("./repair-attempt").RepairAttempt;
  failureRecordedAt?: string;
  lineageId?: string;
  rootPlanId?: string;
  repairContinuation?: import("./repair-continuation").RepairContinuation;
  pendingReceiptId?: string | null;
  createdAt: string;
}

/** Artifact completion is not a runtime observation or receipt. */
export function planStepSatisfied(state: PlanExecutionState, id: string, visited = new Set<string>()): boolean {
  if (state.completed[id]) return true;
  if (visited.has(id)) return false;
  const artifact = state.artifacts?.find(a => a.stepId === id && a.artifactId === state.proposalId);
  return !!artifact && artifact.dependencies.every(dependency => planStepSatisfied(state, dependency, new Set([...visited, id])));
}

export const executionRecord = (tx: any, runId: string) =>
  new RuntimeLedgerService(tx).read<PlanExecutionState>(tx, "PLAN_EXECUTION", runId);

export function verificationOnlyEligible(s: PlanExecutionState): boolean {
  return s.status === "BLOCKED" && !!s.actions.some(a => a.tool === "filesystem.write" && s.completed[a.stepId]) &&
    s.actions.filter(a => !s.completed[a.stepId]).length > 0 &&
    s.actions.filter(a => !s.completed[a.stepId]).every(a => a.tool === "filesystem.read" && !!a.expectedAfterHash);
}

/** Proves reservation linkage from immutable ledger records, not presentation metadata. */
export async function exactExecutionReservationTx(tx: any, s: PlanExecutionState): Promise<boolean> {
  if (!s.exactPermit || !s.proposalId) return false;
  const p = s.exactPermit, ledger = new RuntimeLedgerService(tx), key = [s.userId, s.conversationId, s.proposalId];
  const record = await ledger.read<any>(tx, "EXACT_EXECUTION_PERMIT", p.generation === 1 ? key : [...key, p.generation]);
  const consumption = await ledger.read<any>(tx, "EXACT_PERMIT_CONSUMPTION", p.permitId);
  const global = await ledger.read<any>(tx, "EXACT_PERMIT_CONSUMPTION", key);
  if (!record?.immutable || !consumption?.immutable || !global?.immutable) return false;
  const { digest, ...base } = record.payload, b = p.binding;
  return digest === p.digest && digest === toolDigest(base) && record.payload.oneUse === true &&
    record.payload.permitId === p.permitId && toolDigest(record.payload.binding) === toolDigest(b) &&
    p.executionIntentId === s.requestId && consumption.payload.executionIntentId === s.requestId &&
    global.payload.executionIntentId === s.requestId && global.payload.permitId === p.permitId &&
    global.payload.permitDigest === p.digest && consumption.payload.permitDigest === p.digest &&
    b.proposalId === s.proposalId && b.proposalDigest === s.proposalDigest && b.planId === s.planId && b.planVersion === s.planVersion &&
    b.conversationId === s.conversationId && b.userId === s.userId && b.organizationId === s.organizationId &&
    b.workspace.workspaceId === s.workspace.workspaceId && b.workspace.bindingVersion === s.workspace.version &&
    b.workspace.runtimeId === s.workspace.runtimeId && b.workspace.runtimeFingerprint === s.workspace.runtimeFingerprint &&
    b.actionsDigest === toolDigest(s.actions) && b.sessionId === s.session.id && b.sessionIssuedAt === s.session.issuedAt && b.sessionExpiresAt === s.session.expiresAt;
}

export interface PlanExecutionView {
  lineageId?: string; rootPlanId?: string;
  version: 1; runId: string; planId: string; planVersion: number; revision: number;
  status: PlanExecutionState["status"]; phase?: string; reason?: string | null;
  completedSteps: number; totalSteps: number;
  observations?: import("./step-observation").StepObservation[];
  failureDiagnostics?: import("./failure-diagnostic").FailureDiagnostic[];
  repair?: import("./repair-attempt").RepairAttempt;
  recovery?: "REVIEW_ONLY" | "VERIFICATION_ONLY" | "PREPARATION_REVIEW";
  changes: Array<{ path: string; before: string; after: string; originalHash: string; updatedHash: string }>;
  receipts?: import("../understanding/agent-presentation").EvidenceReceipt[];
}

export async function executionPhaseTx(tx: any, runId: string, phase: string) {
  const record = await executionRecord(tx, runId);
  if (!record || ["COMPLETED", "FAILED", "CANCELLED"].includes(record.payload.status)) return;
  const status = ["REJECTED", "CANCELLED"].includes(phase) ? "CANCELLED" : ["OUTCOME_UNKNOWN", "RUNTIME_REVALIDATION_FAILED"].includes(phase) ? "FAILED" : "RUNNING";
  await new RuntimeLedgerService(tx).update(tx, record, { ...record.payload, status, phase,
    ...(status === "CANCELLED" ? { pendingReceiptId: null } : {}),
    ...(status === "FAILED" ? { reason: phase, pendingReceiptId: null } : {}) }, ["FAILED", "CANCELLED"].includes(status) ? "settled" : "active");
  await tx.agentRun.update({ where: { id: runId }, data: { status, updatedAt: new Date(),
    ...(["FAILED", "CANCELLED"].includes(status) ? { completedAt: new Date(), failureReason: phase } : {}) } });
}

/** Only server-persisted exact actions can activate a planning-only contract. */
export async function authorizedPlanExecution(tx: any, run: any, request: Record<string, unknown>) {
  const plan = run.plans?.[0];
  if (!plan?.steps?.[0]?.parameters?.engineeringPlan) return undefined;
  if (!tx.auditEvent?.findUnique) return null;
  const record = await executionRecord(tx, run.id);
  const s = record?.payload;
  if (!s || !["RUNNING", "AWAITING_APPROVAL"].includes(s.status) || s.userId !== run.userId ||
    s.conversationId !== run.conversationId || s.projectId !== run.projectId || s.planId !== plan.id ||
    s.planVersion !== plan.version || s.planDigest !== toolDigest(plan.steps)) return null;
  if (!(await exactExecutionReservationTx(tx, s))) return null;
  const action = s.actions.find(a => a.stepId === request.planStepId);
  if (!action || action.tool !== request.toolId || toolDigest(action.input) !== toolDigest(request.input) || s.completed[action.stepId]) return null;
  try { await new WorkspaceStoreService(tx).assertInspectionBindingTx(tx, { ...s.workspace, bindingVersion: s.workspace.version,
    userId: s.userId, organizationId: s.organizationId, projectId: s.projectId }); }
  catch { return null; }
  return s;
}

import { ConflictException } from "@nestjs/common";
import { RuntimeLedgerService, type RuntimeRecord } from "../../trusted-runtime/runtime-ledger.service";
import { executionRecord, type PlanExecutionState } from "./plan-execution-state";
import { toolDigest } from "../tools/tool-contract";

export interface RepairContinuation {
  version: 1;
  userId: string; organizationId: string; projectId: string;
  conversationId: string; planId: string;
  rootExecutionLineageId: string;
  sourceRunId: string; sourceExecutionRecordId: string; sourceExecutionRevision: number;
  sourceExecutionDigest: string;
}
type Target = Pick<RepairContinuation, "userId" | "organizationId" | "projectId" | "conversationId" | "planId"> &
  { workspace: PlanExecutionState["workspace"] };

/** Server-only pinning inside the same serialized admission/permit transaction.
 * A run selector locates evidence; it supplies neither lineage nor a counter.
 */
export async function repairContinuationTx(ledger: RuntimeLedgerService, tx: any, target: Target,
  sourceRunId?: string, required = false) {
  const key = [target.userId, target.conversationId, target.planId];
  let pin = await ledger.read<RepairContinuation>(tx, "REPAIR_CONTINUATION", key);
  if (!pin && sourceRunId) {
    const source = await executionRecord(tx, sourceRunId);
    if (!source) throw new ConflictException("REPAIR_LINEAGE_SCOPE_CHANGED");
    const s = source.payload;
    if (!s.lineageId) throw new ConflictException("REPAIR_LINEAGE_REQUIRED");
    const payload: RepairContinuation = { version: 1, userId: target.userId, organizationId: target.organizationId,
      projectId: target.projectId, conversationId: target.conversationId, planId: target.planId,
      rootExecutionLineageId: s.lineageId, sourceRunId, sourceExecutionRecordId: source.recordId,
      sourceExecutionRevision: source.revision, sourceExecutionDigest: source.payloadDigest };
    // Validate before persisting; rejection rolls back the entire admission.
    await resolveRepairContinuationTx(ledger, tx, payload, target);
    pin = await ledger.create(tx, "REPAIR_CONTINUATION", key, payload, { immutable: true });
  }
  if (!pin) {
    if (required) throw new ConflictException("REPAIR_CONTINUATION_REQUIRED");
    return undefined;
  }
  if (!pin.immutable || sourceRunId && sourceRunId !== pin.payload.sourceRunId)
    throw new ConflictException("REPAIR_CONTINUATION_CHANGED");
  return { pin: pin.payload, source: await resolveRepairContinuationTx(ledger, tx, pin.payload, target) };
}

export async function resolveRepairContinuationTx(ledger: RuntimeLedgerService, tx: any,
  pin: RepairContinuation, target: Target): Promise<PlanExecutionState> {
  if (pin.version !== 1 || pin.userId !== target.userId || pin.organizationId !== target.organizationId ||
      pin.projectId !== target.projectId || pin.conversationId !== target.conversationId || pin.planId !== target.planId ||
      !Number.isSafeInteger(pin.sourceExecutionRevision) || pin.sourceExecutionRevision < 1)
    throw new ConflictException("REPAIR_CONTINUATION_CHANGED");
  const revision = await ledger.read<RuntimeRecord<PlanExecutionState>>(tx, "RUNTIME_REVISION",
    [pin.sourceExecutionRecordId, pin.sourceExecutionRevision]);
  const r = revision?.payload, s = r?.payload;
  if (!revision?.immutable || !r || !s || r.recordType !== "PLAN_EXECUTION" ||
      r.recordId !== pin.sourceExecutionRecordId || r.canonicalKeyDigest !== toolDigest(pin.sourceRunId) ||
      r.revision !== pin.sourceExecutionRevision || r.payloadDigest !== pin.sourceExecutionDigest ||
      toolDigest(s) !== pin.sourceExecutionDigest || s.runId !== pin.sourceRunId ||
      s.lineageId !== pin.rootExecutionLineageId || s.userId !== target.userId ||
      s.organizationId !== target.organizationId || s.projectId !== target.projectId ||
      toolDigest(s.workspace) !== toolDigest(target.workspace)) throw new ConflictException("REPAIR_CONTINUATION_CHANGED");
  if (s.status !== "FAILED") throw new ConflictException("REPAIR_SOURCE_NOT_FAILED");
  const root = await ledger.read<any>(tx, "EXECUTION_LINEAGE", pin.rootExecutionLineageId);
  if (!root) throw new ConflictException("REPAIR_LINEAGE_REQUIRED");
  if (root.payload.id !== pin.rootExecutionLineageId || root.payload.userId !== target.userId ||
      root.payload.organizationId !== target.organizationId || root.payload.projectId !== target.projectId ||
      root.payload.rootPlanId !== s.rootPlanId) throw new ConflictException("REPAIR_CONTINUATION_CHANGED");
  if (root.payload.terminal) throw new ConflictException("REPAIR_LINEAGE_COMPLETED");
  return s;
}

import { BadRequestException, ConflictException, ForbiddenException } from "@nestjs/common";
import type { RuntimeLedgerService } from "../../trusted-runtime/runtime-ledger.service";
import { toolDigest, validToolId, isRecord } from "../tools/tool-contract";
export interface WorkflowDecision {
  conversationId: string; userId: string; planId: string; planVersion: number; planDigest: string;
  decision: "REJECT" | "SKIP"; requestId: string; recordedAt: string;
  canContinue: false; reason: string;
}
export const workflowDecisionKey = (userId: string, conversationId: string, planId: string) => [userId, conversationId, planId];
export async function recordWorkflowDecisionTx(ledger: RuntimeLedgerService, tx: any, conversationId: string, userId: string, body: unknown) {
  if (!isRecord(body) || Object.keys(body).sort().join(",") !== "decision,planDigest,planId,planVersion,requestId" ||
    !["REJECT", "SKIP"].includes(String(body.decision)) || !validToolId(body.requestId) || !validToolId(body.planId) ||
    !Number.isSafeInteger(body.planVersion) || typeof body.planDigest !== "string") throw new BadRequestException("WORKFLOW_DECISION_INVALID");
  const plan = await tx.agentPlan.findUnique({ where: { id: body.planId } });
  const run = plan && await tx.agentRun.findUnique({ where: { id: plan.agentRunId } });
  if (!run || run.userId !== userId || run.conversationId !== conversationId) throw new ForbiddenException("WORKFLOW_OWNER_MISMATCH");
  const identity = plan.steps?.[0]?.parameters?.engineeringPlan;
  if (plan.status !== "PLAN_READY" || plan.version !== body.planVersion || identity?.digest !== body.planDigest)
    throw new ConflictException("PLAN_SOURCE_CHANGED");
  const key = workflowDecisionKey(userId, conversationId, plan.id), old = await ledger.read<WorkflowDecision>(tx, "WORKFLOW_DECISION", key);
  if (old) {
    if (old.payload.requestId !== body.requestId || old.payload.decision !== body.decision || old.payload.planDigest !== body.planDigest) throw new ConflictException("WORKFLOW_DECISION_ALREADY_RECORDED");
    return old.payload;
  }
  if (await ledger.read(tx, "PLAN_EXECUTION", run.id)) throw new ConflictException("WORKFLOW_ALREADY_ADMITTED");
  // The existing exact plan contract has no optional/skippable step. Never infer
  // permission to skip from a model description or silently drop verification.
  const payload: WorkflowDecision = { conversationId, userId, planId: plan.id, planVersion: plan.version, planDigest: body.planDigest,
    requestId: String(body.requestId), decision: body.decision as "REJECT" | "SKIP", recordedAt: new Date().toISOString(), canContinue: false,
    reason: body.decision === "SKIP" ? "REQUIRED_PLAN_STEP_CANNOT_BE_SKIPPED" : "USER_REJECTED_WORKFLOW" };
  await ledger.create(tx, "WORKFLOW_DECISION", key, payload);
  await tx.agentRunEvent.create({ data: { id: `workflow_decision_${toolDigest(key)}`, agentRunId: run.id, actor: userId,
    eventType: body.decision === "SKIP" ? "WORKFLOW_SKIPPED" : "WORKFLOW_REJECTED", payload } });
  await tx.conversationMessage.create({ data: { id: `workflow_decision_message_${toolDigest(key)}`, conversationId, senderId: "agent", senderType: "assistant",
    content: body.decision === "SKIP" ? "Skipped. This required step was not executed. The saved plan cannot continue without it; supply a new planning decision explicitly." : "Rejected. This plan will not execute. Continue the conversation explicitly to revise its scope.",
    metadata: { agentRunId: run.id, workflowDecision: payload } } });
  return payload;
}
export async function assertWorkflowDecisionTx(ledger: RuntimeLedgerService, tx: any, userId: string, conversationId: string, planId: string) {
  const row = await ledger.read<WorkflowDecision>(tx, "WORKFLOW_DECISION", workflowDecisionKey(userId, conversationId, planId));
  if (row) throw new ConflictException(row.payload.reason);
}

import { BadRequestException, Inject, Injectable, NotFoundException } from "@nestjs/common";
import { randomUUID } from "node:crypto";
import { PrismaService } from "../../data-access/prisma.service";
import { ResourceAuthorizationService, type AuthSubject } from "../../auth/resource-authz.service";
import type { SessionClaims } from "../../auth/auth.dto";
import {
  AGENT_INITIATIVE_TASK_STATUSES,
  type AgentInitiativePlanStepInput,
  type CreateAgentInitiativeDto,
  type CreateAgentInitiativeVersionDto,
  type UpdateAgentInitiativeTaskDto
} from "./agent-initiative.dto";

const MAX_PLAN_STEPS = 6;
const MAX_LIST_ITEMS = 12;

/** Durable, human-controlled initiative aggregate. It stores state, not CoT. */
@Injectable()
export class AgentInitiativeService {
  constructor(
    @Inject(PrismaService) private readonly prisma: PrismaService,
    @Inject(ResourceAuthorizationService) private readonly authz: ResourceAuthorizationService
  ) {}

  async create(claims: SessionClaims, dto: CreateAgentInitiativeDto) {
    this.requireText(dto.projectId, "projectId");
    this.requireText(dto.title, "title");
    this.requireText(dto.objective, "objective");
    await this.authorize(claims, "CREATE", dto.projectId, `new:${dto.title}`);
    const project = await this.prisma.project.findUnique({ where: { id: dto.projectId } });
    if (!project) throw new NotFoundException("Project not found");
    const steps = this.planSteps(dto.plan);
    const state = dto.propose === true ? "PROPOSED" : "DRAFT";
    const initiativeId = `agent_init_${randomUUID()}`;
    const versionId = `agent_init_ver_${randomUUID()}`;
    const planId = `agent_init_plan_${randomUUID()}`;
    return this.prisma.$transaction(async (tx: any) => {
      const initiative = await tx.agentInitiative.create({
        data: {
          id: initiativeId,
          projectId: dto.projectId,
          workspaceId: this.optionalText(dto.workspaceId),
          conversationId: this.optionalText(dto.conversationId),
          title: dto.title.trim().slice(0, 240),
          objective: dto.objective.trim().slice(0, 4000),
          problem: this.optionalText(dto.problem),
          scope: this.object(dto.scope),
          constraints: this.strings(dto.constraints),
          status: state,
          currentVersionId: versionId,
          createdBy: claims.sub
        }
      });
      const version = await tx.agentInitiativeVersion.create({
        data: {
          id: versionId,
          initiativeId,
          version: 1,
          status: state,
          evidence: this.evidence(dto.evidence),
          architecture: dto.architecture ? this.object(dto.architecture) : undefined,
          plan: steps,
          risks: this.strings(dto.risks),
          dependencies: this.strings(dto.dependencies),
          successCriteria: this.strings(dto.successCriteria),
          createdBy: claims.sub
        }
      });
      const plan = await tx.agentInitiativePlan.create({
        data: { id: planId, initiativeId, versionId, summary: `Version 1 plan for ${initiative.title}`, steps, status: state }
      });
      if (steps.length > 0) {
        await tx.agentInitiativeTask.createMany({
          data: steps.map((step, position) => ({
            id: `agent_init_task_${randomUUID()}`,
            initiativeId,
            planId,
            title: step.title,
            description: step.description ?? null,
            position,
            evidence: this.strings(step.evidence)
          }))
        });
      }
      await this.audit(tx, dto.projectId, initiativeId, claims.sub, "AGENT_INITIATIVE_CREATED", { version: 1, status: state, evidenceCount: this.evidence(dto.evidence).length });
      return { initiative, version, plan, tasks: await tx.agentInitiativeTask.findMany({ where: { planId }, orderBy: { position: "asc" } }) };
    });
  }

  async createVersion(claims: SessionClaims, initiativeId: string, dto: CreateAgentInitiativeVersionDto) {
    const initiative = await this.getAuthorized(claims, initiativeId, "UPDATE");
    const material = Object.values(dto).some((value) => value !== undefined);
    if (!material) throw new BadRequestException("A version must contain a material state change");
    const latest = await this.prisma.agentInitiativeVersion.findFirst({ where: { initiativeId }, orderBy: { version: "desc" } });
    if (!latest) throw new NotFoundException("Initiative version not found");
    const versionId = `agent_init_ver_${randomUUID()}`;
    const planId = `agent_init_plan_${randomUUID()}`;
    const steps = dto.plan === undefined ? this.planSteps(latest.plan) : this.planSteps(dto.plan);
    return this.prisma.$transaction(async (tx: any) => {
      const version = await tx.agentInitiativeVersion.create({
        data: {
          id: versionId,
          initiativeId,
          version: latest.version + 1,
          status: "DRAFT",
          evidence: dto.evidence === undefined ? latest.evidence : this.evidence(dto.evidence),
          architecture: dto.architecture === undefined ? latest.architecture : this.object(dto.architecture),
          plan: steps,
          risks: dto.risks === undefined ? latest.risks : this.strings(dto.risks),
          dependencies: dto.dependencies === undefined ? latest.dependencies : this.strings(dto.dependencies),
          successCriteria: dto.successCriteria === undefined ? latest.successCriteria : this.strings(dto.successCriteria),
          decisionSummary: this.optionalText(dto.decisionSummary),
          createdBy: claims.sub
        }
      });
      const plan = await tx.agentInitiativePlan.create({ data: { id: planId, initiativeId, versionId, summary: `Version ${version.version} plan for ${initiative.title}`, steps, status: "DRAFT" } });
      if (steps.length > 0) await tx.agentInitiativeTask.createMany({ data: steps.map((step, position) => ({ id: `agent_init_task_${randomUUID()}`, initiativeId, planId, title: step.title, description: step.description ?? null, position, evidence: this.strings(step.evidence) })) });
      await this.audit(tx, initiative.projectId, initiativeId, claims.sub, "AGENT_INITIATIVE_VERSION_CREATED", { version: version.version, basedOn: latest.version });
      return { version, plan, tasks: await tx.agentInitiativeTask.findMany({ where: { planId }, orderBy: { position: "asc" } }) };
    });
  }

  async decide(claims: SessionClaims, initiativeId: string, versionNumber: number, decision: "APPROVE" | "REJECT", notes?: string) {
    const initiative = await this.getAuthorized(claims, initiativeId, "APPROVE");
    const version = await this.prisma.agentInitiativeVersion.findUnique({ where: { initiativeId_version: { initiativeId, version: versionNumber } } });
    if (!version) throw new NotFoundException("Initiative version not found");
    if (!["DRAFT", "PROPOSED"].includes(version.status)) throw new BadRequestException("Only a draft or proposed version can be decided");
    const nextStatus = decision === "APPROVE" ? "APPROVED" : "REJECTED";
    return this.prisma.$transaction(async (tx: any) => {
      const updatedVersion = await tx.agentInitiativeVersion.update({ where: { id: version.id }, data: { status: nextStatus, decisionSummary: this.optionalText(notes) ?? version.decisionSummary } });
      const updatedInitiative = await tx.agentInitiative.update({ where: { id: initiativeId }, data: decision === "APPROVE" ? { status: "APPROVED", currentVersionId: version.id } : { status: "REJECTED" } });
      const recorded = await tx.agentInitiativeDecision.create({ data: { id: `agent_init_decision_${randomUUID()}`, initiativeId, versionId: version.id, decision, notes: this.optionalText(notes), decidedBy: claims.sub } });
      await this.audit(tx, initiative.projectId, initiativeId, claims.sub, `AGENT_INITIATIVE_${decision}D`, { version: version.version, decision });
      return { initiative: updatedInitiative, version: updatedVersion, decision: recorded };
    });
  }

  async resolve(claims: SessionClaims, projectId: string, reference: string) {
    this.requireText(projectId, "projectId"); this.requireText(reference, "reference");
    await this.authorize(claims, "READ", projectId, reference);
    const rows = await this.prisma.agentInitiative.findMany({
      where: { projectId, OR: [{ id: reference }, { title: { contains: reference.trim(), mode: "insensitive" } }] },
      orderBy: { updatedAt: "desc" }, take: 10
    });
    if (rows.length === 0) throw new NotFoundException("Agent initiative not found");
    return rows;
  }

  async getVersion(claims: SessionClaims, initiativeId: string, versionNumber: number) {
    await this.getAuthorized(claims, initiativeId, "READ");
    const version = await this.prisma.agentInitiativeVersion.findUnique({
      where: { initiativeId_version: { initiativeId, version: versionNumber } },
      include: { plans: { orderBy: { createdAt: "desc" } }, decisions: { orderBy: { createdAt: "desc" } } }
    });
    if (!version) throw new NotFoundException("Initiative version not found");
    return version;
  }

  /** Selects an already-approved immutable version as the resume target. */
  async selectApprovedVersion(claims: SessionClaims, initiativeId: string, versionNumber: number, notes?: string) {
    const initiative = await this.getAuthorized(claims, initiativeId, "UPDATE");
    const version = await this.prisma.agentInitiativeVersion.findUnique({ where: { initiativeId_version: { initiativeId, version: versionNumber } } });
    if (!version) throw new NotFoundException("Initiative version not found");
    if (version.status !== "APPROVED") throw new BadRequestException("Only an approved version can become the current resume target");
    return this.prisma.$transaction(async (tx: any) => {
      const updated = await tx.agentInitiative.update({ where: { id: initiativeId }, data: { currentVersionId: version.id, status: "APPROVED" } });
      const decision = await tx.agentInitiativeDecision.create({ data: { id: `agent_init_decision_${randomUUID()}`, initiativeId, versionId: version.id, decision: "SELECT_VERSION", notes: this.optionalText(notes), decidedBy: claims.sub } });
      await this.audit(tx, initiative.projectId, initiativeId, claims.sub, "AGENT_INITIATIVE_VERSION_SELECTED", { version: version.version });
      return { initiative: updated, version, decision };
    });
  }

  /** Explicit lifecycle transitions; approval/rejection always go through decide(). */
  async transition(claims: SessionClaims, initiativeId: string, status: string, notes?: string) {
    const initiative = await this.getAuthorized(claims, initiativeId, "UPDATE");
    const allowed: Record<string, readonly string[]> = {
      DRAFT: ["PROPOSED", "SUPERSEDED"],
      PROPOSED: ["SUPERSEDED"],
      APPROVED: ["ACTIVE", "PAUSED", "BLOCKED", "COMPLETED", "SUPERSEDED"],
      ACTIVE: ["PAUSED", "BLOCKED", "COMPLETED", "SUPERSEDED"],
      PAUSED: ["ACTIVE", "BLOCKED", "COMPLETED", "SUPERSEDED"],
      BLOCKED: ["ACTIVE", "PAUSED", "COMPLETED", "SUPERSEDED"],
      REJECTED: ["SUPERSEDED"],
      COMPLETED: ["SUPERSEDED"],
      SUPERSEDED: []
    };
    if (!allowed[initiative.status]?.includes(status)) throw new BadRequestException(`Transition from ${initiative.status} to ${status} is not permitted`);
    return this.prisma.$transaction(async (tx: any) => {
      const updated = await tx.agentInitiative.update({ where: { id: initiativeId }, data: { status } });
      const versionId = initiative.currentVersionId;
      if (status === "PROPOSED" && versionId) {
        await tx.agentInitiativeVersion.update({ where: { id: versionId }, data: { status: "PROPOSED" } });
      }
      if (versionId) await tx.agentInitiativeDecision.create({ data: { id: `agent_init_decision_${randomUUID()}`, initiativeId, versionId, decision: `TRANSITION_${status}`, notes: this.optionalText(notes), decidedBy: claims.sub } });
      await this.audit(tx, initiative.projectId, initiativeId, claims.sub, "AGENT_INITIATIVE_TRANSITION", { from: initiative.status, to: status });
      return updated;
    });
  }

  async get(claims: SessionClaims, initiativeId: string) {
    const initiative = await this.getAuthorized(claims, initiativeId, "READ");
    return this.prisma.agentInitiative.findUnique({ where: { id: initiative.id }, include: { versions: { orderBy: { version: "desc" } }, plans: { orderBy: { createdAt: "desc" } }, tasks: { orderBy: { position: "asc" } }, decisions: { orderBy: { createdAt: "desc" } } } });
  }

  async resume(claims: SessionClaims, initiativeId: string) {
    const initiative = await this.getAuthorized(claims, initiativeId, "READ");
    const full = await this.prisma.agentInitiative.findUnique({ where: { id: initiative.id }, include: { versions: { orderBy: { version: "desc" } }, plans: { orderBy: { createdAt: "desc" } }, tasks: { orderBy: { position: "asc" } }, decisions: { orderBy: { createdAt: "desc" } } } });
    if (!full) throw new NotFoundException("Agent initiative not found");
    const approved = full.versions.find((version: any) => version.id === full.currentVersionId && version.status === "APPROVED") ?? full.versions.find((version: any) => version.status === "APPROVED");
    if (!approved) throw new BadRequestException("An approved initiative version is required before resume");
    const plan = full.plans.find((item: any) => item.versionId === approved.id) ?? null;
    const openTasks = full.tasks.filter((task: any) => task.planId === plan?.id && !["DONE", "VERIFIED", "CANCELED"].includes(task.status));
    const agentRunIds = openTasks.map((task: any) => task.agentRunId).filter((id: unknown): id is string => typeof id === "string" && id.length > 0);
    const runs = agentRunIds.length > 0 ? await this.prisma.agentRun.findMany({ where: { id: { in: agentRunIds }, projectId: initiative.projectId } }) : [];
    return { initiative: full, version: approved, plan, openTasks, evidence: approved.evidence, decisions: full.decisions, runs };
  }

  async updateTask(claims: SessionClaims, taskId: string, dto: UpdateAgentInitiativeTaskDto) {
    if (!AGENT_INITIATIVE_TASK_STATUSES.includes(dto.status)) throw new BadRequestException("Invalid initiative task status");
    const task = await this.prisma.agentInitiativeTask.findUnique({ where: { id: taskId }, include: { initiative: true } });
    if (!task) throw new NotFoundException("Initiative task not found");
    await this.authorize(claims, "UPDATE", task.initiative.projectId, task.initiativeId);
    return this.prisma.agentInitiativeTask.update({ where: { id: taskId }, data: { status: dto.status, verification: dto.verification ? this.object(dto.verification) as any : undefined } });
  }

  private async getAuthorized(claims: SessionClaims, initiativeId: string, action: "READ" | "UPDATE" | "APPROVE") {
    const initiative = await this.prisma.agentInitiative.findUnique({ where: { id: initiativeId } });
    if (!initiative) throw new NotFoundException("Agent initiative not found");
    await this.authorize(claims, action, initiative.projectId, initiativeId, initiative.createdBy);
    return initiative;
  }

  private async authorize(claims: SessionClaims, action: "READ" | "CREATE" | "UPDATE" | "APPROVE", projectId: string, id: string, ownerId?: string) {
    const subject: AuthSubject = { userId: claims.sub, email: claims.email, displayName: claims.displayName, role: claims.role, organizationId: claims.organizationId, isSystemAdmin: claims.role === "Admin" };
    await this.authz.assertAuthorized(subject, action, { resourceType: "Initiative", id, projectId, organizationId: claims.organizationId, ownerId });
  }

  private planSteps(value: unknown): AgentInitiativePlanStepInput[] {
    if (value === undefined || value === null) return [];
    if (!Array.isArray(value)) throw new BadRequestException("plan must be an array");
    return value.slice(0, MAX_PLAN_STEPS).map((item, index) => {
      if (!item || typeof item !== "object" || typeof (item as any).title !== "string" || !(item as any).title.trim()) throw new BadRequestException(`plan[${index}].title is required`);
      const source = item as AgentInitiativePlanStepInput;
      return { title: source.title.trim().slice(0, 500), description: this.optionalText(source.description), evidence: this.strings(source.evidence) };
    });
  }
  private strings(value: unknown): string[] { return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string" && item.trim().length > 0).slice(0, MAX_LIST_ITEMS).map((item) => item.trim().slice(0, 1000)) : []; }
  private evidence(value: unknown) { return Array.isArray(value) ? value.filter((item) => item && typeof item === "object" && typeof (item as any).provenance === "string").slice(0, MAX_LIST_ITEMS).map((item: any) => ({ provenance: item.provenance.slice(0, 1000), sourceType: typeof item.sourceType === "string" ? item.sourceType.slice(0, 100) : "unknown", reference: typeof item.reference === "string" ? item.reference.slice(0, 1000) : undefined, warnings: this.strings(item.warnings), truncated: item.truncated === true })) : []; }
  private object(value: unknown): Record<string, unknown> { return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {}; }
  private optionalText(value: unknown): string | undefined { return typeof value === "string" && value.trim().length > 0 ? value.trim().slice(0, 4000) : undefined; }
  private requireText(value: unknown, field: string): asserts value is string { if (typeof value !== "string" || !value.trim()) throw new BadRequestException(`${field} is required`); }
