            "IMPLEMENT describes a future change, uses purpose PROPOSE_CHANGE, a non-READ_ONLY effect, and verificationCriterionIds including requested-outcome. VERIFY uses purpose CHECK_OUTCOME. " +
            "dependencyStatus KNOWN means the prerequisite ordering is specified, not that any prerequisite has already executed; dependencies contain existing step IDs. UNKNOWN means genuinely unresolved ordering. " +
            "Reference the supplied certified understanding and verified sources. Evidence is historical: a future pre-edit freshness check may be a planned prerequisite, never a claim that it already happened. " +
            "Use verification appropriate to the requested change and acceptance criteria. Do not invent test commands or require unrelated engineering work. Explicitly report any information genuinely required but unavailable. " : "") +
          "Return the requested JSON object only, with all required arrays, even when empty.",
        schema: (concrete ? AGENT_ENGINEERING_PLAN_SCHEMA : AGENT_PLANNING_SCHEMA) as unknown as Record<string, unknown>, name: "agent_understanding_plan"
      });
    } catch (error) {
      // No raw response, provider URL, credentials or exception text enters the result/audit.
      const diagnostic = callDiagnostic ?? diagnosticFromError(error);
      const code = error instanceof UnauthorizedException || fileReadOutcome(error) === "DENIED" ? "BLOCKED" :
        error instanceof AssistantContextBudgetError ? "FAILED" :
          diagnostic?.finishReason === "length" ? "OUTPUT_TRUNCATED" :
            diagnostic?.httpStatus && diagnostic.httpStatus >= 200 && diagnostic.httpStatus < 300 ? "INVALID_STRUCTURED_OUTPUT" : "PROVIDER_FAILED";
      return finish(notReady(understanding, code));
    }
    // Internal validation exceptions propagate as FAILED, not provider failures.
    if (callDiagnostic?.finishReason === "length") return finish(notReady(understanding, "OUTPUT_TRUNCATED"));
    const parsed = parsePlanningProposal(raw, concrete);
    if (!parsed.proposal) {
      const failure = notReady(understanding, "INVALID_PROPOSAL");
      failure.plan.validation.issues = parsed.issues;
      return finish(failure);
    }
    let result = validatePlanningProposal(understanding, parsed.proposal, visibleEvidence, concrete);
    if (concrete) {
      const information = classifyPlanningInformation(parsed.proposal);
      // Validate the ENTIRE original proposal first, including duplicate IDs,
      // bounds, provenance and step references. Classification cannot hide errors.
      if (result.plan.validation.valid && information.some(item => !item.blocking)) {
        const blockingIds = new Set(information.filter(item => item.blocking).map(item => item.id));
        result = validatePlanningProposal(understanding, {
          ...parsed.proposal,
          unknowns: parsed.proposal.unknowns.filter(item => blockingIds.has(item.id))
        }, visibleEvidence, true);
        if (result.understanding.confidence === "HIGH") result.understanding.confidence = "MEDIUM";
      }
      result.planningInformation = information;
    }
    if (context.truncated && result.understanding.confidence === "HIGH") result.understanding.confidence = "MEDIUM";
    return finish(result, parsed.proposal.unknowns.map(item => item.id), true);
  }

  understand(input: AgentUnderstandingInput): AgentContext {
    const instruction = input.instruction.trim();
    const runtimeEvidence = Boolean(input.runtimeEvidence?.length);
    const classified = this.classifyIntent(instruction);
    const intents = runtimeEvidence && classified.every(i => i === "CHAT" || i === "CONVERSE") ? ["INSPECT" as const] : classified;
    const operationClass = this.operationClass(intents);
    const attachmentIds = [...new Set((input.attachmentIds ?? []).filter((id) => typeof id === "string" && id.trim()))]
      .slice(0, AGENT_UNDERSTANDING_LIMITS.MAX_EVIDENCE_ITEMS);
    const requiresWorkspace = runtimeEvidence || this.requiresWorkspace(instruction);
    const requiresRepository = REPOSITORY_HINT.test(instruction);
    const requiresAttachments = attachmentIds.length > 0 || (!runtimeEvidence && DOCUMENT_HINT.test(instruction));
    const missingContext: MissingContextCode[] = [];
    const warnings: string[] = [];
    if (requiresAttachments && attachmentIds.length === 0) missingContext.push("ATTACHMENT");
    if ((requiresWorkspace || requiresRepository) && !input.projectId) missingContext.push("PROJECT_OR_REPOSITORY");
    if (requiresWorkspace && !input.workspaceAvailable) missingContext.push("WORKSPACE_SCOPE");
    if (operationClass !== "READ") {
      missingContext.push("CAPABILITY_NOT_ENABLED");
      warnings.push("Write and execution intents are recognized but no execution capability is selected or authorized.");
    }
    const selectedCapabilities = this.selectCapabilities(
      input.availableCapabilities,
      requiresAttachments,
      requiresWorkspace,
      requiresRepository,
      operationClass
    );
    const plan = this.plan(selectedCapabilities, missingContext, operationClass);
    const verificationRequired = operationClass !== "READ" || selectedCapabilities.length > 0;
    return {
      userId: input.userId,
      projectId: input.projectId,
      conversationId: input.conversationId,
      agentRunId: input.agentRunId,
      userIntent: intents,
      objective: instruction,
      operationClass,
      constraints: ["No execution capability is enabled by understanding.", "Evidence and plan are bounded."],
      conversationContext: { hasHistory: input.hasConversationHistory === true, attachmentIds },
      memoryContext: { available: input.hasMemoryContext === true, advisory: true },
      workspaceContext: { required: requiresWorkspace, available: input.workspaceAvailable === true },
      attachmentContext: { required: requiresAttachments, attachmentIds },
      repositoryContext: { required: requiresRepository, available: input.repositoryAvailable === true },
      evidence: [],
      availableCapabilities: input.availableCapabilities,
      selectedCapabilities,
      plan,
      verificationState: {
        required: verificationRequired,
        strategy: operationClass === "READ" ? "GROUNDED_EVIDENCE" : "TEST_OR_INSPECTION",
        status: verificationRequired ? "PENDING" : "NOT_REQUIRED",
        evidenceIds: [],
        failures: []
      },
      missingContext: [...new Set(missingContext)],
      assumptions: [
        ...(input.projectId ? [{ key: "targetProject", value: input.projectId, source: "explicit" as const }] : []),
        ...(attachmentIds.length ? [{ key: "targetAttachments", value: attachmentIds.join(","), source: "explicit" as const }] : []),
        ...(input.repositoryConnectionId ? [{ key: "targetRepository", value: input.repositoryConnectionId, source: "explicit" as const }] : [])
      ],
      warnings,
      truncated: false,
      truncation: emptyContextTruncation()
    };
  }

  private classifyIntent(instruction: string): AgentIntent[] {
    const lower = instruction.toLowerCase();
    const positive = positiveIntentText(positiveEngineeringIntentText(lower)).replace(/(?:لا|ولا)\s+(?:تعد[ّ]?ل(?:\s+أي\s+ملف)?|تنف[ّ]?ذ\s+(?:أوامر|أي\s+تعديل\s+أو\s+أمر)|تنشئ\s+خطة\s+تنفيذ)(?=\s*(?:ولا|[،.;\n]|$))/g, " ");
    const intents = new Set<AgentIntent>();
    if (/\b(fix|change|modify|edit|implement|write)\b/.test(positive) || /(اصلح|عد[ّ]?ل|نفذ تعديل)/.test(positive) || packageVersionRequest(lower)) intents.add("MODIFY");
    if (/\b(run|execute|deploy|command|powershell)\b/.test(positive) || /(شغ[ّ]?ل|نفذ)/.test(positive)) intents.add("EXECUTE");
    // A bounded source-text existence question is answered by grounded reading.
    // Keep operational/conditional checks and any other verification request outstanding.
    const verificationRemainder = lower.replace(/\b(?:verify|validate|check)\s+(?:whether|if)\s+(?:the\s+)?(?:exact\s+)?text\s+(["'])([^\r\n]*?)\1\s+(?:exists|appears|is present)\s+in\s+(?:the|this)\s+(?:source\s+)?file\b(?=\s*(?:[.;!?\r\n]|$))/g, " ");
    const sourceCheck = verificationRemainder !== lower && !intents.has("MODIFY") && !intents.has("EXECUTE") &&
      !/\b(?:after|before|following|once|when|post[- ](?:change|edit)|tests?|commands?|runtime|behavio[u]?r(?:al)?|browser|render(?:ed|ing)?|plans?)\b/.test(positiveIntentText(verificationRemainder));
    if (sourceCheck) intents.add("UNDERSTAND");
    if (/\b(tests?|verify|validate|check)\b/.test(sourceCheck ? verificationRemainder : lower)) intents.add("VERIFY");
    if (/\b(debug|bug|failing|failure|broken|investigate|investigation)\b/.test(lower)) intents.add("DEBUG");
    if (/\b(search|find|where)\b/.test(lower)) intents.add("SEARCH");
    if (/\b(compare|difference)\b/.test(lower)) intents.add("COMPARE");
    if (/\b(explain|summarize|what is)\b/.test(lower)) intents.add("EXPLAIN");
    if (/\binspect\b/.test(lower)) intents.add("INSPECT");
    if (/\b(analyze|analyse|understand|read)\b/.test(lower) || /(حلل|اقرأ|افهم)/.test(lower) || requestsSourceAnalysis(instruction)) intents.add("UNDERSTAND");
    if (/\breview\b/.test(lower) && /\b(workspace|project|repository|code|architecture|security)\b/.test(lower)) intents.add("INSPECT");
    if (/\b(research)\b/.test(lower)) intents.add("RESEARCH");
    if (/\b(plan|roadmap|implementation plan)\b/.test(positive) || /(خطة|بلان)/.test(positive)) intents.add("PLAN");
    if (/\b(initiative|save this|save it)\b/.test(lower) || /(احفظ.*initiative|مبادرة)/.test(lower)) intents.add("INITIATIVE");
    if (/\b(security review|security audit)\b/.test(lower)) intents.add("SECURITY_REVIEW");
    if (intents.size === 0) intents.add("CHAT");
    return [...intents];
  }

  private operationClass(intents: AgentIntent[]): AgentOperationClass {
    if (intents.includes("EXECUTE")) return "EXECUTE";
    if (intents.includes("MODIFY")) return "WRITE";
    return "READ";
  }

  private requiresWorkspace(instruction: string): boolean {
    return requestsWorkspace(instruction);
  }

  private selectCapabilities(
    available: string[],
    attachments: boolean,
    workspace: boolean,
    repository: boolean,
    _operationClass: AgentOperationClass
  ): string[] {
    const wanted = [
      ...(attachments ? ["attachment_reader"] : []),
      ...(workspace ? ["workspace_reader"] : []),
      ...(repository ? ["repo_snapshot_reader"] : [])
    ];
    return wanted.filter((capability) => available.includes(capability)).slice(0, AGENT_UNDERSTANDING_LIMITS.MAX_SELECTED_CAPABILITIES);
  }

  private plan(capabilities: string[], missing: MissingContextCode[], operationClass: AgentOperationClass): AgentUnderstandingPlanStep[] {
    const blocked = missing.length > 0;
    const steps: AgentUnderstandingPlanStep[] = [];
    for (const capability of capabilities) {
      const objective = capability === "attachment_reader"
        ? "Collect bounded evidence from conversation-scoped attachments."
        : capability === "repo_snapshot_reader"
          ? "Collect bounded evidence from the authorized repository snapshot."
          : "Collect bounded evidence from the authorized workspace.";
      steps.push({
        id: `understand-${steps.length + 1}`,
        objective,
        capability,
        input: {},
        expectedResult: "Provenance-labelled normalized evidence.",
        dependencies: [],
        status: "PLANNED",
        verificationRequired: true
      });
    }
    if (blocked || operationClass !== "READ") {
      steps.push({
        id: `understand-${steps.length + 1}`,
        objective: blocked ? "Request the missing target or capability context." : "Keep the requested operation gated pending enabled capability, policy, and approval.",
        input: { missingContext: missing },
        expectedResult: "A focused clarification or explicit blocked state.",
        dependencies: capabilities.map((step) => step),
        status: "BLOCKED",
        verificationRequired: false
      });
    }
    if (steps.length === 0) {
      steps.push({ id: "understand-1", objective: "Respond to the user request without a capability call.", input: {}, expectedResult: "A concise conversational response.", dependencies: [], status: "PLANNED", verificationRequired: false });
    }
    return steps.slice(0, AGENT_UNDERSTANDING_LIMITS.MAX_PLAN_STEPS);
  }
}

import { ForbiddenException, Inject, Injectable, Optional } from "@nestjs/common";
import { AttachmentService } from "../../attachment/attachment.service";
import { PrismaService } from "../../data-access/prisma.service";
import { ResourceAuthorizationService, type AuthSubject } from "../../auth/resource-authz.service";
import { RuntimeConfigurationService } from "../../ai-gateway/runtime-configuration.service";
import { RepositoryContentService } from "../../repository-source/repository-content.service";
import { MemoryService } from "../memory/memory.service";
import { AGENT_FILE_READER_LIMITS } from "../capabilities/workspace-context";
import { fileReadOutcome, hasReadableContent } from "../../file-intelligence/file-read-outcome";
import { AttachmentCapabilityService } from "../capabilities/attachment-capability.service";
import { WorkspaceCapabilityService, type CapabilityRequest } from "../capabilities/workspace-capability.service";
import { WorkspaceStoreService } from "../../workspace-intelligence/workspace-store.service";
import { WorkspaceRuntimeEvidenceService } from "../../workspace-intelligence/workspace-runtime-evidence.service";
import type { RuntimeEvidenceReference } from "../../workspace-intelligence/workspace-runtime.contract";
import type { SessionClaims } from "../../auth/auth.dto";
import { transferredConversation } from "../../conversation/conversation-mode";
import {
  AGENT_UNDERSTANDING_LIMITS,
  extractEvidenceQueryTokens,
  scoreEvidencePath,
  type AgentContextSource,
  type AgentEvidence
} from "./agent-understanding.types";

function boundText(text: string, max: number = AGENT_FILE_READER_LIMITS.MAX_EVIDENCE_TEXT_CHARS): { text: string; truncated: boolean } {
  if (text.length <= max) return { text, truncated: false };
  let bounded = text.slice(0, max);
  if (/[\uD800-\uDBFF]$/.test(bounded)) bounded = bounded.slice(0, -1);
  return { text: bounded, truncated: true };
}

function isDenied(error: unknown): boolean {
  if (error instanceof ForbiddenException) return true;
  if (error && typeof error === "object" && "getStatus" in error && typeof (error as { getStatus?: unknown }).getStatus === "function") {
    return (error as { getStatus(): number }).getStatus() === 403;
  }
  return false;
}

/**
 * Bounded evidence collector. This uses the existing Attachment Reader rather
 * than storage paths, raw bytes, or a second extractor implementation.
 */
@Injectable()
export class EvidenceCollectorService {
  constructor(
    @Inject(AttachmentCapabilityService) private readonly attachments: AttachmentCapabilityService,
    @Optional() @Inject(WorkspaceCapabilityService) private readonly workspace?: WorkspaceCapabilityService,
    @Optional() @Inject(AttachmentService) private readonly attachmentCatalog?: AttachmentService,
    @Optional() @Inject(PrismaService) private readonly prisma?: PrismaService,
    @Optional() @Inject(RepositoryContentService) private readonly repositoryContent?: RepositoryContentService,
    @Optional() @Inject(RuntimeConfigurationService) private readonly runtimeConfig?: RuntimeConfigurationService,
    @Optional() @Inject(MemoryService) private readonly memory?: MemoryService,
    @Optional() @Inject(ResourceAuthorizationService) private readonly resourceAuthz?: ResourceAuthorizationService,
    @Optional() @Inject(WorkspaceStoreService) private readonly runtimeWorkspaces?: WorkspaceStoreService,
    @Optional() @Inject(WorkspaceRuntimeEvidenceService) private readonly runtimeEvidence?: WorkspaceRuntimeEvidenceService
  ) {}

  async collectRuntimeWorkspace(claims: SessionClaims | undefined, projectId: string, conversationId: string, references: RuntimeEvidenceReference[]): Promise<AgentEvidence[]> {
    if (!this.runtimeEvidence || !claims) throw new ForbiddenException("WORKSPACE_EVIDENCE_AUTHORITY_REQUIRED");
    const result: AgentEvidence[] = [];
    for (const ref of references) {
      const { reference, file, operation } = await this.runtimeEvidence.admit(claims, projectId, conversationId, ref);
      // Runtime admission already bounds and validates the read. Do not apply
      // the legacy document-extractor cap again; the serializer accounts for
      // all evidence bodies and provenance within the existing shared budget.
      const bounded = boundText(file.text, AGENT_UNDERSTANDING_LIMITS.MAX_MODEL_EVIDENCE_CHARS), truncated = reference.truncated || bounded.truncated;
      result.push({ sourceType: "workspace", sourceId: reference.operationId, relativePath: reference.relativePath,
        // Receipt identity is already immutable and globally unique. Keep full
        // coordinates in runtimeReference without repeating them in every model citation.
        runtimeReference: reference, provenance: `runtime:${reference.receiptId}`,
        status: "COLLECTED", outcome: truncated ? "TRUNCATED" : operation && operation.tool !== "filesystem.read" ? "SCANNED" : "READ", warnings: file.warnings,
        metadata: { runtimeEvidence: reference, ...(operation ? { operation: operation.tool } : {}) }, content: { text: bounded.text, truncated, extractorId: "verified-runtime-read", detectedMime: file.mimeType } });
    }
    return result;
  }

  async collectTransferredWorkspace(claims: SessionClaims, projectId: string, conversationId: string) {
    if (!this.prisma) return null;
    const conversation = await this.prisma.conversation.findUnique({ where: { id: conversationId } });
    if (!conversation || conversation.userId !== claims.sub || conversation.projectId !== projectId) throw new ForbiddenException("CONVERSATION_TRANSFER_SCOPE_INVALID");
    const transfer = await transferredConversation(this.prisma, conversation);
    if (!transfer) return null;
    const evidence = await this.collectRuntimeWorkspace(claims, projectId, transfer.parent.id, transfer.source.evidence);
    return { sourceConversationId: transfer.parent.id as string, evidence };
  }

  async collectAttachments(input: {
    userId: string;
    conversationId: string;
    attachmentIds: string[];
    agentRunId?: string;
  }): Promise<AgentEvidence[]> {
    const ids = [...new Set(input.attachmentIds.filter((id) => typeof id === "string" && id.trim()))]
      .slice(0, AGENT_UNDERSTANDING_LIMITS.MAX_EVIDENCE_ITEMS);
    const evidence: AgentEvidence[] = [];
    for (const attachmentId of ids) {
      evidence.push(await this.readAttachment(input.userId, input.conversationId, attachmentId, input.agentRunId));
    }
    return evidence;
  }

  async collectConversationAttachments(input: {
    userId: string;
    conversationId: string;
    instruction: string;
    excludeIds?: string[];
    agentRunId?: string;
  }): Promise<AgentEvidence[]> {
    if (!this.attachmentCatalog) return [];
    let listed;
    try {
      listed = await this.attachmentCatalog.listAttachmentsForConversation(input.userId, input.conversationId);
    } catch (error) {
      return [{
        sourceType: "attachment",
        sourceId: input.conversationId,
        metadata: {},
        provenance: `CONVERSATION_ATTACHMENT:${input.conversationId}`,
        status: isDenied(error) ? "DENIED" : "UNAVAILABLE",
        warnings: [isDenied(error) ? "Conversation attachment listing was denied." : "Conversation attachments could not be listed."]
      }];
    }
    const excluded = new Set(input.excludeIds ?? []);
    const tokens = extractEvidenceQueryTokens(input.instruction);
    const ranked = listed
      .filter((item) => !excluded.has(item.id))
      .map((item) => ({
        item,
        score: scoreEvidencePath(item.fileName, tokens) + (item.category === "pdf" && /\b(pdf|document|requirements?|spec)\b/i.test(input.instruction) ? 3 : 0)
      }))
      .filter((entry) => entry.score > 0)
      .sort((a, b) => b.score - a.score || a.item.fileName.localeCompare(b.item.fileName, "en"))
      .slice(0, AGENT_UNDERSTANDING_LIMITS.MAX_EVIDENCE_ITEMS);
    const evidence: AgentEvidence[] = [];
    for (const entry of ranked) {
      evidence.push(await this.readAttachment(input.userId, input.conversationId, entry.item.id, input.agentRunId));
    }
    return evidence;
  }

  async collectWorkspace(request: CapabilityRequest, relativePaths: string[]): Promise<AgentEvidence[]> {
    if (!this.workspace) {
      return [{
        sourceType: "workspace",
        sourceId: request.workspaceId ?? request.projectId,
        metadata: {},
        provenance: `${request.projectId}:workspace`,
        status: "UNAVAILABLE",
        warnings: ["Workspace evidence collection is unavailable in this environment."]
      }];
    }
    const collected = await this.workspace.collectEvidence(request, relativePaths);
    return collected.context.evidence.map((item) => ({
      sourceType: "workspace" as const,
      sourceId: collected.context.workspaceId,
      relativePath: item.relativePath,
      outcome: item.outcome ?? (item.truncated ? "TRUNCATED" : "READ"),
      content: hasReadableContent(item.outcome) ? {
        text: item.text,
        extractorId: item.extractorId ?? "unknown",
        detectedMime: item.fileType ?? "application/octet-stream",
        truncated: item.truncated
      } : undefined,
      metadata: { source: collected.context.source },
      provenance: item.sourceIdentity,
      status: hasReadableContent(item.outcome) ? "COLLECTED" as const : item.outcome === "DENIED" ? "DENIED" as const : "UNAVAILABLE" as const,
      warnings: item.warnings
    })).slice(0, AGENT_UNDERSTANDING_LIMITS.MAX_EVIDENCE_ITEMS);
  }

  async collectRepository(input: {
    userId: string;
    userRole: AuthSubject["role"];
    organizationId?: string;
    projectId: string;
    instruction: string;
    repositoryConnectionId?: string;
    agentRunId?: string;
  }): Promise<AgentEvidence[]> {
    if (!this.repositoryContent || !this.runtimeConfig || !input.repositoryConnectionId) {
      return [{
        sourceType: "repository",
        sourceId: input.projectId,
        metadata: {},
        provenance: `${input.projectId}:repository`,
        status: "UNAVAILABLE",
        warnings: ["Repository evidence requires an authorized repository connection id."]
      }];
    }
    try {
      await this.assertProjectRead(input);
      const connection = await this.runtimeConfig.repositoryForUse(input.repositoryConnectionId);
      const snapshot = await this.repositoryContent.snapshot(connection, connection.defaultBranch);
      const tokens = extractEvidenceQueryTokens(input.instruction);
      const ranked = snapshot.chunks
        .map((chunk) => ({ chunk, score: scoreEvidencePath(chunk.path, tokens) }))
        .sort((a, b) => b.score - a.score || a.chunk.path.localeCompare(b.chunk.path, "en"));
      const selected = (ranked.some((entry) => entry.score > 0) ? ranked.filter((entry) => entry.score > 0) : ranked)
        .slice(0, AGENT_UNDERSTANDING_LIMITS.MAX_EVIDENCE_ITEMS);
      const sourceType: AgentContextSource = connection.providerType === "gitlab" ? "gitlab" : "repository";
      return selected.map((entry) => {
        const bounded = boundText(entry.chunk.content);
        return {
          sourceType,
          sourceId: connection.id,
          repositoryId: connection.id,
          relativePath: entry.chunk.path,
          content: {
            text: bounded.text,
            extractorId: "repository_snapshot",
            detectedMime: "text/plain",
            truncated: bounded.truncated
          },
          metadata: { repository: snapshot.repository, commitSha: snapshot.commitSha, providerType: connection.providerType },
          provenance: `${connection.id}:${snapshot.commitSha}:${entry.chunk.path}`,
          status: "COLLECTED" as const,
          warnings: bounded.truncated ? ["Repository chunk truncated to the evidence text limit."] : []
        };
      });
    } catch (error) {
      return [{
        sourceType: "repository",
        sourceId: input.repositoryConnectionId,
        repositoryId: input.repositoryConnectionId,
        metadata: {},
        provenance: `${input.repositoryConnectionId}:repository`,
        status: isDenied(error) ? "DENIED" : "UNAVAILABLE",
        warnings: [isDenied(error) ? "Repository evidence collection was denied." : "Repository evidence could not be collected."]
      }];
    }
  }

  async collectArtifacts(input: {
    userId: string;
    userRole: AuthSubject["role"];
    organizationId?: string;
    projectId: string;
    instruction: string;
  }): Promise<AgentEvidence[]> {
    if (!this.prisma) return [];
    try {
      if (this.resourceAuthz) {
        await this.resourceAuthz.assertAuthorized(this.subject(input), "READ", {
          resourceType: "Artifact",
          id: input.projectId,
          projectId: input.projectId,
          organizationId: input.organizationId
        });
      }
      const rows = await this.prisma.agentArtifact.findMany({
        where: { projectId: input.projectId, isCustomerSafe: true },
        orderBy: { createdAt: "desc" },
        take: 20,
        select: { id: true, title: true, artifactType: true, content: true, summary: true }
      });
      const tokens = extractEvidenceQueryTokens(input.instruction);
      const ranked = (Array.isArray(rows) ? rows : [])
        .map((row: { id: string; title: string; artifactType: string; content: string; summary: string | null }) => ({
          row,
          score: scoreEvidencePath(`${row.title} ${row.artifactType} ${row.summary ?? ""}`, tokens)
        }))
        .filter((entry: { score: number }) => entry.score > 0)
        .sort((a: { score: number; row: { title: string } }, b: { score: number; row: { title: string } }) => b.score - a.score || a.row.title.localeCompare(b.row.title, "en"))
        .slice(0, Math.min(2, AGENT_UNDERSTANDING_LIMITS.MAX_EVIDENCE_ITEMS));
      return ranked.map((entry: { row: { id: string; title: string; artifactType: string; content: string } }) => {
        const bounded = boundText(entry.row.content ?? "");
        return {
          sourceType: "artifact" as const,
          sourceId: entry.row.id,
          content: {
            text: bounded.text,
            extractorId: "agent_artifact",
            detectedMime: "text/plain",
            truncated: bounded.truncated
          },
          metadata: { artifactId: entry.row.id, title: entry.row.title, artifactType: entry.row.artifactType, customerSafe: true },
          provenance: `AGENT_ARTIFACT:${input.projectId}:${entry.row.id}`,
          status: "COLLECTED" as const,
          warnings: bounded.truncated ? ["Artifact content truncated to the evidence text limit."] : []
        };
      });
    } catch (error) {
      return [{
        sourceType: "artifact",
        sourceId: input.projectId,
        metadata: {},
        provenance: `AGENT_ARTIFACT:${input.projectId}`,
        status: isDenied(error) ? "DENIED" : "UNAVAILABLE",
        warnings: [isDenied(error) ? "Artifact evidence collection was denied." : "Artifact evidence could not be collected."]
      }];
    }
  }

  async collectConversation(input: {
    userId: string;
    conversationId: string;
    instruction: string;
  }): Promise<AgentEvidence[]> {
    if (!this.prisma) return [];
    try {
      const conv = await this.prisma.conversation.findUnique({
        where: { id: input.conversationId },
        select: { id: true, userId: true }
      });
      if (!conv) {
        return [{
          sourceType: "conversation",
          sourceId: input.conversationId,
          metadata: {},
          provenance: `CONVERSATION:${input.conversationId}`,
          status: "UNAVAILABLE",
          warnings: ["Conversation was not found for evidence collection."]
        }];
      }
      if (conv.userId !== input.userId) {
        return [{
          sourceType: "conversation",
          sourceId: input.conversationId,
          metadata: {},
          provenance: `CONVERSATION:${input.conversationId}`,
          status: "DENIED",
          warnings: ["Conversation evidence collection was denied."]
        }];
      }
      let messages = await this.prisma.conversationMessage.findMany({
        where: { conversationId: input.conversationId },
        orderBy: { createdAt: "desc" },
        take: 20,
        select: { id: true, content: true, senderType: true, metadata: true }
      });
      if (this.runtimeWorkspaces) messages = await this.runtimeWorkspaces.modelMessages(messages);
      const tokens = extractEvidenceQueryTokens(input.instruction);
      const ranked = (Array.isArray(messages) ? messages : [])
        .filter((message: { content?: string; metadata?: any }) => !message.metadata?.historicalContext && !message.metadata?.accountHistoricalMemory && typeof message.content === "string" && message.content.trim())
        .map((message: { id: string; content: string; senderType: string }) => ({
          message,
          score: scoreEvidencePath(message.content, tokens)
        }))
        .filter((entry: { score: number }) => entry.score > 0)
        .slice(0, 2);
      return ranked.map((entry: { message: { id: string; content: string; senderType: string } }) => {
        const bounded = boundText(entry.message.content);
        return {
          sourceType: "conversation" as const,
          sourceId: entry.message.id,
          content: {
            text: bounded.text,
            extractorId: "conversation_message",
            detectedMime: "text/plain",
            truncated: bounded.truncated
          },
          metadata: { messageId: entry.message.id, senderType: entry.message.senderType },
          provenance: `CONVERSATION:${input.conversationId}:${entry.message.id}`,
          status: "COLLECTED" as const,
          warnings: []
        };
      });
    } catch (error) {
      return [{
        sourceType: "conversation",
        sourceId: input.conversationId,
        metadata: {},
        provenance: `CONVERSATION:${input.conversationId}`,
        status: isDenied(error) ? "DENIED" : "UNAVAILABLE",
        warnings: ["Conversation evidence could not be collected."]
      }];
    }
  }

  async collectMemory(input: { userId: string }): Promise<AgentEvidence[]> {
    if (!this.memory) return [];
    try {
      const text = await this.memory.buildMemoryContext(input.userId);
      if (!text) return [];
      const bounded = boundText(text);
      return [{
        sourceType: "memory",
        sourceId: input.userId,
        content: {
          text: bounded.text,
          extractorId: "user_memory",
          detectedMime: "text/plain",
          truncated: bounded.truncated
        },
        metadata: { advisory: true },
        provenance: `MEMORY:${input.userId}`,
        status: "COLLECTED",
        warnings: ["Memory is advisory and is not a substitute for source evidence."]
      }];
    } catch {
      return [];
    }
  }

  private async readAttachment(userId: string, conversationId: string, attachmentId: string, agentRunId?: string): Promise<AgentEvidence> {
    try {
      const read = await this.attachments.read({ userId, conversationId, attachmentId, agentRunId });
      const bounded = boundText(read.normalizedContent.text);
      return {
        sourceType: "attachment",
        sourceId: attachmentId,
        attachmentId,
        outcome: read.status !== "OK" ? "SCANNED" : read.normalizedContent.truncated || bounded.truncated ? "TRUNCATED" : "READ",
        content: {
          text: bounded.text,
          extractorId: read.normalizedContent.extractorId,
          detectedMime: read.normalizedContent.detectedMime,
          truncated: read.normalizedContent.truncated || bounded.truncated
        },
        metadata: { fileName: read.fileName, size: read.size, status: read.status },
        provenance: `${read.provenance.sourceType}:${read.provenance.conversationId}:${attachmentId}`,
        status: read.status === "OK" ? "COLLECTED" : "UNAVAILABLE",
        warnings: read.warnings
      };
    } catch (error) {
      const outcome = fileReadOutcome(error);
      return {
        sourceType: "attachment",
        sourceId: attachmentId,
        attachmentId,
        outcome,
        metadata: {},
        provenance: `CONVERSATION_ATTACHMENT:${conversationId}:${attachmentId}`,
        status: outcome === "DENIED" ? "DENIED" : "UNAVAILABLE",
        warnings: [`Attachment could not be collected. Read outcome: ${outcome}.`]
      };
    }
  }

  private subject(input: { userId: string; userRole: AuthSubject["role"]; organizationId?: string }): AuthSubject {
    return {
      userId: input.userId,
      email: "",
      displayName: "",
      role: input.userRole,
      organizationId: input.organizationId,
      isSystemAdmin: input.userRole === "Admin"
    };
  }

  private async assertProjectRead(input: {
    userId: string;
    userRole: AuthSubject["role"];
    organizationId?: string;
    projectId: string;
  }): Promise<void> {
    if (!this.resourceAuthz) return;
    await this.resourceAuthz.assertAuthorized(this.subject(input), "READ", {
      resourceType: "Project",
      id: input.projectId,
      projectId: input.projectId,
      organizationId: input.organizationId
    });
  }
}

import { createHash } from "node:crypto";
import { evidenceIdentity, type AgentConstraint, type AgentContext } from "./agent-understanding.types";

const hash = (text: string) => createHash("sha256").update(text, "utf8").digest("hex");
export type HeroTextChange = NonNullable<AgentConstraint["textChange"]>;

/** One bounded Arabic command. Quoted source/target bytes are never normalized. */
export function arabicHeroRequest(objective: string) {
  const match = /^غي[ّ]?ر (?:Hero (?:heading|title)|عنوان الـ?Hero) من "([^"\r\n]+)" إلى "([^"\r\n]+)"([^\r\n]*)[\s]*$/i.exec(objective);
  return match ? { before: match[1], after: match[2], restriction: match[3].trim().replace(/\.$/, "") } : undefined;
}

/** Deliberately narrow source recognition, not HTML rewriting. Unsupported or
 * ambiguous markup needs clarification. Original bytes are never serialized. */
export function heroTitle(source: string) {
  const masked = source.replace(/<!--[\s\S]*?-->|<(script|style|template)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, s => " ".repeat(s.length));
  if (/<!--|<(?:script|style|template)\b/i.test(masked)) return;
  let invalidAttributes = false;
  const sections = [...masked.matchAll(/<section\b[^<>]*>[\s\S]*?<\/section\s*>/gi)].filter(m => {
    const opening = m[0].slice(0, m[0].indexOf(">") + 1);
    const attributes = opening.slice(8, -1), pattern = /\s+([a-z][\w:-]*)\s*=\s*(["'])([^<>]*?)\2/igy;
    let offset = 0, match: RegExpExecArray | null, classes: string[] = [];
    const names = new Set<string>();
    while ((match = pattern.exec(attributes))) {
      const name = match[1].toLowerCase();
      if (names.has(name)) { invalidAttributes = true; return false; }
      names.add(name); offset = pattern.lastIndex;
      if (name === "class") classes = match[3].split(/\s+/);
    }
    if (attributes.slice(offset).trim()) { invalidAttributes = true; return false; }
    return classes.includes("hero");
  });
  if (invalidAttributes || sections.length !== 1 || (sections[0][0].match(/<section\b/gi)?.length ?? 0) !== 1) return;
  const section = sections[0], headings = [...section[0].matchAll(/<h1(?:\s[^<>]*)?>([\s\S]*?)<\/h1\s*>/gi)];
  if (headings.length !== 1) return;
  const heading = headings[0], start = section.index! + heading.index!, excerpt = source.slice(start, start + heading[0].length);
  // Comments, entities, malformed tags or non-span children are not supported by this bounded edit.
  if (excerpt !== heading[0] || excerpt.length > 512 || /&/.test(heading[1])) return;
  const innerOffset = start + heading[0].indexOf(">") + 1;
  const tokens = [...heading[1].matchAll(/<[^>]*>|[^<]+/g)];
  let depth = 0, text = "", indices: number[] = [], pendingSpace: number | undefined;
  for (const token of tokens) {
    if (token[0].startsWith("<")) {
      if (/^<span(?:\s[^<>]*)?>$/i.test(token[0])) depth++;
      else if (/^<\/span\s*>$/i.test(token[0])) depth--;
      else return;
      if (depth < 0 || depth > 1) return;
      continue;
    }
    for (let i = 0; i < token[0].length; i++) {
      const absolute = innerOffset + token.index! + i, c = token[0][i];
      if (/\s/.test(c)) { if (text && pendingSpace === undefined) pendingSpace = absolute; continue; }
      if (pendingSpace !== undefined) { text += " "; indices.push(pendingSpace); pendingSpace = undefined; }
      text += c; indices.push(absolute);
    }
  }
  if (depth || !text || /[<>]/.test(text)) return;
  return { text, indices, excerpt };
}

/** Recognize this bounded user intent only; unrelated constraints remain unresolved. */
export function resolveHeroTextChange(context: AgentContext, visible: ReadonlyMap<string, string>): HeroTextChange | undefined {
  const arabic = arabicHeroRequest(context.objective);
  if ((!arabic && !/(?:\b(?:change|update|replace)|(?:^|\s)(?:غير|عد[ّ]?ل)).{0,100}(?:Hero\s+(?:title|heading)|عنوان\s+الـ?Hero)/i.test(context.objective)) ||
    /(?:do not|don't|never|لا|لن|ممنوع).{0,50}(?:change|update|replace|ت?غير|ت?عد[ّ]?ل).{0,80}Hero/i.test(context.objective)) return;
  const quoted = `(?:"([^"\\r\\n]+)"|'([^'\\r\\n]+)'|“([^”\\r\\n]+)”)`;
  const arrow = new RegExp(`^Change only the Hero heading in index\\.html:\\s*${quoted}\\s*→\\s*${quoted}(?=\\s*(?:\\r?\\n|$))`, "i").exec(context.objective.trim());
  if (arrow && [...context.objective.matchAll(new RegExp(`${quoted}\\s*→\\s*${quoted}`, "g"))].length !== 1) return;
  const pairs = [...context.objective.matchAll(new RegExp(`\\bfrom(?:\\s*:\\s*|\\s+)${quoted}\\s+to(?:\\s*:\\s*|\\s+)${quoted}`, "gi"))];
  if (pairs.length > 1) return;
  const hero = /(?:Hero\s+(?:title|heading)|عنوان\s+الـ?Hero)/i.exec(context.objective)!;
  const tail = context.objective.slice(hero.index + hero[0].length);
  if (pairs.length && !/^\s*(?:text\s*)?(?:in\s+index\.html\s*)?(?:\.\s*Target:\s*Change the existing heading\s*)?$/i.test(context.objective.slice(hero.index + hero[0].length, pairs[0].index))) return;
  if (!pairs.length && /\bfrom\b/i.test(tail)) return;
  const target = new RegExp(`^(?:\\s+)(?:to\\s+|إلى\\s+)${quoted}|^\\s+(?:to\\s+|إلى\\s+)([^\\r\\n]+)$`, "i").exec(tail);
  if (arrow && (arabic || pairs.length)) return;
  const after = arrow ? arrow[4] ?? arrow[5] ?? arrow[6] : arabic ? arabic.after : pairs.length ? (pairs[0][4] ?? pairs[0][5] ?? pairs[0][6]).trim() : (target?.[1] ?? target?.[2] ?? target?.[3] ?? target?.[4] ?? "").trim();
  if (!after || after.length > 160 || !/^[A-Za-z0-9 .,!?()'-]+$/.test(after) || /\s{2}/.test(after)) return;
  const from = arrow ? arrow[1] ?? arrow[2] ?? arrow[3] : arabic ? arabic.before : pairs.length ? pairs[0][1] ?? pairs[0][2] ?? pairs[0][3] : undefined;
  const candidates = context.evidence.filter(e => e.status === "COLLECTED" && e.relativePath === "index.html" &&
    e.metadata.operation === "filesystem.read" && e.runtimeReference?.verificationState === "VERIFIED" &&
    !e.runtimeReference.truncated && !e.content?.truncated && e.content?.text === visible.get(evidenceIdentity(e)));
  if (!candidates.length) return;
  const texts = new Set(candidates.map(e => e.content!.text));
  if (texts.size !== 1) return;
  const evidence = candidates[0], source = evidence.content!.text, title = heroTitle(source);
  if (!title || (from !== undefined && title.text !== from) || title.text === after) return;
  let prefix = 0, suffix = 0;
  while (prefix < Math.min(title.text.length, after.length) && title.text[prefix] === after[prefix]) prefix++;
  while (suffix < Math.min(title.text.length, after.length) - prefix && title.text.at(-suffix - 1) === after.at(-suffix - 1)) suffix++;
  const endIndex = title.text.length - suffix;
  if (prefix >= endIndex) return; // Insert-only edits need a separately established text-node boundary.
  const start = title.indices[prefix], end = title.indices[endIndex - 1] + 1;
  if (source.slice(start, end) !== title.text.slice(prefix, endIndex)) return; // Never cross markup or normalized whitespace.
  const replacement = after.slice(prefix, after.length - suffix);
  const updated = source.slice(0, start) + replacement + source.slice(end);
  if (heroTitle(updated)?.text !== after) return;
  return { relativePath: "index.html", evidenceRef: evidenceIdentity(evidence), sourceSha256: hash(source),
    selector: "section.hero h1", before: title.text, after, start, end, replacement, titleExcerpt: title.excerpt };
}

/** Used again at the existing exact-proposal boundary after fresh evidence admission. */
export function heroConstrainedResult(source: string, change: HeroTextChange): string | undefined {
  if (change.relativePath !== "index.html" || change.selector !== "section.hero h1" || hash(source) !== change.sourceSha256 ||
    !Number.isSafeInteger(change.start) || !Number.isSafeInteger(change.end) || change.start < 0 || change.end <= change.start || change.end > source.length) return;
  const title = heroTitle(source);
  if (!title || title.text !== change.before || title.excerpt !== change.titleExcerpt ||
    !title.indices.includes(change.start) || !title.indices.includes(change.end - 1) || /[<>&]/.test(change.replacement) ||
    /[<>]/.test(source.slice(change.start, change.end))) return;
  const after = source.slice(0, change.start) + change.replacement + source.slice(change.end);
  return heroTitle(after)?.text === change.after ? after : undefined;
}

export function isHeroPreservationClause(quote: string, change?: HeroTextChange) {
  if (change) {
    if (/^Change only the Hero heading in index\.html:$/i.test(quote)) return true;
    if (/^Preserve the existing <h1>, the <span> around "intelligent", surrounding structure\/whitespace, and all other content$/i.test(quote)) return true;
    if (quote === "مع الحفاظ على باقي محتوى الملف كما هو") return true;
    if (/^Preserve markup, CSS, encoding and every other byte$/i.test(quote)) return true;
    const replacement = /^Replace only the text (\w+) inside the existing Hero h1 span with (\w+)$/i.exec(quote);
    if (replacement) return replacement[2] === change.replacement && change.titleExcerpt.includes(`<span>${replacement[1]}</span>`) && change.before.includes(replacement[1]);
    const request = /^(?:Create an engineering plan to )?change only the index\.html Hero (?:title|heading) from (["'])(.*?)\1 to (["'])(.*?)\3$/i.exec(quote);
    if (request) return request[2] === change.before && request[4] === change.after;
    // The heading's period is inside its quotes, so the clause splitter retains
    // the following preservation sentence. Accept only this bounded suffix.
    const headingTextRequest = /^Change only the Hero heading text in index\.html from (["'])(.*?)\1 to (["'])(.*?)\3(?: Preserve the existing h1 element, span tags, formatting, structure, and every other part of index\.html unchanged)?$/i.exec(quote);
    if (headingTextRequest) return headingTextRequest[2] === change.before && headingTextRequest[4] === change.after;
    if (/^Preserve the existing h1 element, span tags, formatting, structure, and every other part of index\.html unchanged$/i.test(quote)) return true;
  }
  return /^(?:change only the Hero title, preserving its existing markup|preserve (?:existing (?:Hero )?markup|HTML|CSS|surrounding content|unrelated content|encoding)|(?:keep|preserve) (?:all )?(?:other|unrelated) (?:content|files) unchanged)$/i.test(quote);
}

import { BadRequestException, ConflictException, HttpException } from "@nestjs/common";
import { diagnosticFromError } from "../../ai-gateway/provider-diagnostic";
import { PROVIDER_FAILURE_CODES } from "../../ai-gateway/providers/vllm-openai-compatible.adapter";
import type { SessionClaims } from "../../auth/auth.dto";
import type { AiGatewayService } from "../../ai-gateway/ai-gateway.service";
import type { AgentInspectionService } from "../inspection/agent-inspection.service";
import { toolDigest, isRecord, validToolId } from "../tools/tool-contract";
import { isAgentFailureOutcome, planningOutcome } from "../agent-result";
import type { AgentContextBuilderService } from "./agent-context-builder.service";
import type { AgentUnderstandingService } from "./agent-understanding.service";
import type { AgentPlanningResult } from "./agent-understanding.types";
import { evidenceReceipt } from "./agent-presentation";
import { executionRecord } from "../execution/plan-execution-state";
import { inspectionReferences } from "../../conversation/workspace-reference";
import type { InspectionView } from "../inspection/inspection.types";
import { planningAcceptanceSection } from "../../conversation/conversation-intent";
import { currentPlanningInformation } from "../../conversation/planning-continuation-information";

export const isEngineeringPlanningRun = (id: string) => id.startsWith("planning_run_");
import type { EngineeringPlanIdentity, PlanningCheckpointResponse } from "./agent-understanding.types";
interface Dependencies { inspections: AgentInspectionService; contexts: AgentContextBuilderService; understanding: AgentUnderstandingService; gateway: AiGatewayService }
type CertifiedSource = Awaited<ReturnType<AgentInspectionService["certifiedPlanningSourceTx"]>>;

/** Separate the known server envelope only after checking its certified source linkage. */
export function resolvedHeroPlanningObjective(instruction: string, source: Pick<CertifiedSource, "checkpoint" | "references">): string {
  const match = /^Create an engineering plan to modify only the resolved hero source target\.\nOriginal request: ([^\r\n]+)\nResolved source target \(context, not authorization\): (\{[^\r\n]+\})$/.exec(instruction);
  if (!match) return instruction;
  let target: unknown;
  try { target = JSON.parse(match[2]); } catch { return instruction; }
  if (!isRecord(target) || Object.keys(target).sort().join(",") !== "concept,evidenceId,factId,path" || target.concept !== "hero") return instruction;
  const references = inspectionReferences("", { state: "COMPLETED", understanding: source.checkpoint, evidence: source.references } as InspectionView);
  if (!references.some(r => r.certified && r.targetKind === "HEADING" && r.factId === target.factId &&
    r.evidenceId === target.evidenceId && r.relativePath === target.path)) return instruction;
  return match[1];
}

/** Re-admit immutable observations; a saved checkpoint alone never supplies fresh authority. */
async function certifiedContext(d: Pick<Dependencies, "contexts">, claims: SessionClaims, source: CertifiedSource, instruction: string, runId?: string) {
  const context = await d.contexts.buildRuntimeInspection({ userId: claims.sub, userRole: claims.role, organizationId: claims.organizationId!, sessionClaims: claims,
    projectId: source.conversation.projectId, conversationId: source.sourceConversationId, agentRunId: runId, instruction,
    runtimeEvidence: source.references, availableCapabilities: ["workspace_reader"] });
  const visible = new Map<string, string>(), prompt = d.contexts.toReasoningPrompt(context, visible), checkpoint = source.checkpoint;
  if (context.truncated || !checkpoint.understanding.facts.length ||
    !checkpoint.evidence.some(e => e.read && checkpoint.understanding.facts.some(f => f.evidenceRef === e.id)) ||
    checkpoint.understanding.facts.some(f => visible.get(f.evidenceRef)?.slice(f.start, f.end) !== f.text)) throw new ConflictException("CERTIFIED_EVIDENCE_UNAVAILABLE");
  return { context, prompt, source };
}

export async function certifiedConversationContext(d: Pick<Dependencies, "inspections" | "contexts">, claims: SessionClaims, conversationId: string, instruction: string) {
  let source: CertifiedSource;
  try { source = await d.inspections.ledger.transaction(tx => d.inspections.certifiedPlanningSourceTx(tx, claims, conversationId)); }
  catch (error) { if (error instanceof ConflictException && error.message.startsWith("CERTIFIED_UNDERSTANDING_REQUIRED:")) return null; throw error; }
  return certifiedContext(d, claims, source, instruction);
}

/** Natural-language entry uses the same reservation, version check and idempotency as the explicit planning API. */
export async function generateConversationPlan(d: Dependencies, claims: SessionClaims, conversationId: string, instruction: string, requestId: string, sourceRunId?: string, continuationMessage?: string) {
  if (!validToolId(requestId) || (sourceRunId !== undefined && !validToolId(sourceRunId))) throw new BadRequestException("PLANNING_REQUEST_INVALID");
  const expectedVersion = await d.inspections.ledger.transaction(async tx => {
    await d.inspections.certifiedPlanningSourceTx(tx, claims, conversationId, sourceRunId);
    const previous = await tx.agentRunEvent.findUnique({ where: { id: `planning_attempt_${toolDigest([conversationId, requestId])}` } });
    if (previous) return previous.payload.version - 1;
    return (await tx.agentRun.findUnique({ where: { id: `planning_run_${toolDigest([claims.sub, conversationId])}` } }))?.planVersion ?? 0;
  });
  return generatePersistedPlan(d, claims, conversationId, { requestId, instruction, expectedVersion }, true, sourceRunId, continuationMessage);
}

/** Persist engineering intent in the existing AgentRun/AgentPlan/Message models. No dispatch dependency. */
export async function generatePersistedPlan(d: Dependencies, claims: SessionClaims, conversationId: string, body: unknown, conversationRequest = false, sourceRunId?: string, continuationMessage?: string): Promise<PlanningCheckpointResponse> {
  if (!isRecord(body) || Object.keys(body).some(k => !["requestId", "instruction", "expectedVersion"].includes(k)) || !validToolId(body.requestId) ||
    !Number.isSafeInteger(body.expectedVersion) || Number(body.expectedVersion) < 0 ||
    (body.instruction !== undefined && (typeof body.instruction !== "string" || !body.instruction.trim() || body.instruction.length > 4000))) throw new BadRequestException("PLANNING_REQUEST_INVALID");
  const runId = `planning_run_${toolDigest([claims.sub, conversationId])}`;
  const attemptId = `planning_attempt_${toolDigest([conversationId, body.requestId])}`;
  let continuationInformation;
  try { continuationInformation = continuationMessage === undefined ? null : currentPlanningInformation(continuationMessage); }
  catch { throw new BadRequestException("PLANNING_CONTINUATION_INFORMATION_INVALID"); }
  if (continuationMessage !== undefined && !continuationInformation) throw new BadRequestException("PLANNING_CONTINUATION_INFORMATION_INVALID");
  const continuationProvenance = continuationInformation ? { messageId: `${attemptId}_message`, userId: claims.sub,
    messageDigest: toolDigest(continuationMessage), information: continuationInformation } : undefined;
  const reserved = await d.inspections.ledger.transaction(async tx => {
    const source = await d.inspections.certifiedPlanningSourceTx(tx, claims, conversationId, sourceRunId);
    await tx.$queryRawUnsafe('SELECT "id" FROM "Conversation" WHERE "id"=$1 FOR NO KEY UPDATE', conversationId);
    const instruction = String(body.instruction ?? source.initiatingMessage?.content ?? "").trim();
    if (!instruction || instruction.length > 4000) throw new BadRequestException("ENGINEERING_OBJECTIVE_REQUIRED");
    const requestDigest = toolDigest({ instruction, expectedVersion: body.expectedVersion, ...(sourceRunId ? { sourceRunId } : {}),
      ...(continuationProvenance ? { continuationProvenance } : {}) });
    const previous = await tx.agentRunEvent.findUnique({ where: { id: attemptId } });
    if (previous) {
      if (previous.payload.requestDigest !== requestDigest) throw new ConflictException("PLANNING_REQUEST_CONFLICT");
      const plan = await tx.agentPlan.findUnique({ where: { id: previous.payload.planId } });
      const run = await tx.agentRun.findUnique({ where: { id: runId } });
      return { cached: { runId, planId: previous.payload.planId, version: previous.payload.version, status: plan?.status ?? (run?.status === "PLANNING" ? "PLANNING" : "PLAN_NOT_READY"),
        digest: plan?.steps?.[0]?.parameters?.engineeringPlan?.digest } };
    }
    const existing = await tx.agentRun.findUnique({ where: { id: runId }, include: { plans: { orderBy: { version: "desc" }, take: 1 } } });
    const execution = await executionRecord(tx, runId);
    if (execution && ["PREPARING", "RUNNING", "AWAITING_APPROVAL"].includes(execution.payload.status)) throw new ConflictException("PLAN_EXECUTION_IN_PROGRESS");
    if (existing?.status === "PLANNING") throw new ConflictException("PLANNING_ALREADY_IN_PROGRESS");
    if ((existing?.planVersion ?? 0) !== body.expectedVersion) throw new ConflictException("PLAN_VERSION_CHANGED");
    const version = (existing?.planVersion ?? 0) + 1, planId = `engineering_plan_${toolDigest([runId, version])}`;
    const data = { status: "PLANNING", planVersion: version, title: instruction.slice(0, 100), progressPercent: 0, startedAt: new Date(), completedAt: null, failureReason: null, pausedAt: null, cancellationReason: null };
    if (existing) await tx.agentRun.update({ where: { id: runId }, data });
    else await tx.agentRun.create({ data: { id: runId, conversationId, projectId: source.conversation.projectId, userId: claims.sub, agentName: "SekhemEngineer", ...data } });
    await tx.agentRunEvent.create({ data: { id: attemptId, agentRunId: runId, eventType: "PLAN_CREATED", actor: claims.sub,
      payload: { phase: "CHECKPOINT_2", state: "REQUESTED", requestDigest, planId, version, sourceRunId: source.sourceRunId, executionPerformed: false } } });
    await tx.conversationMessage.create({ data: { id: `${attemptId}_message`, conversationId, senderId: claims.sub, senderType: "user", content: continuationMessage ?? `Generate an engineering plan:\n${instruction}`,
      metadata: { agentRunId: runId, planningRequest: true, planId, planVersion: version } } });
