  /** Advisory generation reuses re-admitted certified evidence, never a listing. */
  async suggest(conversation: any, claims: any, message: string, requestId: string, certify: () => Promise<any>) {
    if (!/^[A-Za-z0-9_-]{1,128}$/.test(requestId)) throw new BadRequestException("RECOMMENDATION_REQUEST_INVALID");
    const id = `recommendation_${toolDigest([conversation.id, claims.sub, requestId])}`, digest = toolDigest(message);
    const reserved = await this.db.$transaction(async tx => {
      await tx.$queryRawUnsafe('SELECT "id" FROM "Conversation" WHERE "id"=$1 FOR NO KEY UPDATE', conversation.id);
      const saved = await tx.conversationMessage.findUnique({ where: { id } });
      if (saved) {
        if ((saved.metadata as any)?.requestDigest !== digest) throw new ConflictException("RECOMMENDATION_REPLAY_CONFLICT");
        return false;
      }
      await tx.conversationMessage.create({ data: { id, conversationId: conversation.id, senderId: claims.sub, senderType: "user", content: message,
        metadata: { clientMessageId: requestId, requestDigest: digest, recommendationRequest: true } } });
      return true;
    });
    if (!reserved) {
      const reply = await this.db.conversationMessage.findUnique({ where: { id: id + "_reply" } });
      if (!reply) throw new ConflictException("RECOMMENDATION_PENDING_OR_FAILED");
      return reply;
    }
    try {
      const admitted = await certify();
      if (!admitted || admitted.source.sourceConversationId !== conversation.id) throw new ConflictException("CERTIFIED_EVIDENCE_UNAVAILABLE");
      const source = admitted.source;
      const raw = await this.gateway.requestStructuredReasoning({ history: [], question: JSON.stringify({ currentUserRequest: message,
        observed: source.checkpoint.understanding.facts, inferred: source.checkpoint.understanding.inferences, unknowns: source.checkpoint.understanding.unknowns }),
        schema: RECOMMENDATION_SCHEMA, name: "recommendation", purpose: "STRUCTURED_INSPECTION",
        systemInstruction: "Return one bounded improvement recommendation, not a fact, plan, approval or executable action. Use only supplied same-conversation certified evidence. Do not assert unsupported facts. Recommendations are proposed changes, not observations. Do not invent preservation: redesign preservation is UNSPECIFIED unless expressly supplied by the current user. No operations or execution authority." });
      let value: unknown; try { value = JSON.parse(raw); } catch { throw new BadRequestException("RECOMMENDATION_INVALID"); }
      const next = parseRecommendation(value); assertRecommendationPreservation(next, message);
      const fresh = await certify();
      if (!fresh || fresh.source.sourceRunId !== source.sourceRunId || fresh.source.digest !== source.digest ||
        fresh.source.checkpoint.sequence !== source.checkpoint.sequence) throw new ConflictException("UNDERSTANDING_CHANGED");
      return this.db.conversationMessage.create({ data: { id: id + "_reply", conversationId: conversation.id, senderId: "agent", senderType: "assistant",
        content: recommendationMessage(next), metadata: { recommendation: { ...next, generation: 1, sourceRunId: source.sourceRunId,
          sourceSequence: source.checkpoint.sequence, workspaceId: source.binding.workspaceId, bindingVersion: source.binding.version,
          runtimeId: source.binding.runtimeId, runtimeFingerprint: source.binding.runtimeFingerprint }, recommendationRequestId: id } } });
    } catch (error) {
      await persistSubmissionFailure(this.db, conversation, claims.sub, requestId, message, error);
      throw error;
    }
  }
  async accept(conversation: any, claims: any, message: string, requestId: string, prior: any) {
    if (!/^[A-Za-z0-9_-]{1,128}$/.test(requestId)) throw new BadRequestException("RECOMMENDATION_REQUEST_INVALID");
    const id = `recommendation_accept_${toolDigest([conversation.id, claims.sub, requestId])}`, digest = toolDigest(message);
    return this.db.$transaction(async tx => {
      await tx.$queryRawUnsafe('SELECT "id" FROM "Conversation" WHERE "id"=$1 FOR NO KEY UPDATE', conversation.id);
      const saved = await tx.conversationMessage.findUnique({ where: { id } });
      if (saved) {
        if ((saved.metadata as any)?.requestDigest !== digest || (saved.metadata as any)?.recommendationId !== prior.id) throw new ConflictException("RECOMMENDATION_REPLAY_CONFLICT");
        return saved;
      }
      const latest = await tx.conversationMessage.findFirst({ where: { conversationId: conversation.id, senderType: "assistant", metadata: { path: ["recommendation", "sourceRunId"], not: Prisma.DbNull } }, orderBy: [{ createdAt: "desc" }, { id: "desc" }] });
      if (latest?.id !== prior.id) throw new ConflictException("RECOMMENDATION_CHANGED");
      return tx.conversationMessage.create({ data: { id, conversationId: conversation.id, senderId: claims.sub, senderType: "user", content: message,
        metadata: { recommendationResponse: "ACCEPT", recommendationId: prior.id, requestDigest: digest, recommendationGeneration: prior.metadata.recommendation.generation,
          sourceRunId: prior.metadata.recommendation.sourceRunId, planningOnly: true } } });
    });
  }
  async reject(conversation: any, claims: any, message: string, requestId: string, prior: any, source: any) {
    if (!/^[A-Za-z0-9_-]{1,128}$/.test(requestId)) throw new BadRequestException("RECOMMENDATION_REQUEST_INVALID");
    const id = `recommendation_${toolDigest([conversation.id, claims.sub, requestId])}`, digest = toolDigest(message), previous = prior.metadata.recommendation;
    const reserve = await this.db.$transaction(async tx => {
      await tx.$queryRawUnsafe('SELECT "id" FROM "Conversation" WHERE "id"=$1 FOR NO KEY UPDATE', conversation.id);
      const saved = await tx.conversationMessage.findUnique({ where: { id } });
      if (saved) { if ((saved.metadata as any)?.requestDigest !== digest) throw new ConflictException("RECOMMENDATION_REPLAY_CONFLICT"); return false; }
      const latest = await tx.conversationMessage.findFirst({ where: { conversationId: conversation.id, senderType: "assistant", metadata: { path: ["recommendation", "sourceRunId"], not: Prisma.DbNull } }, orderBy: [{ createdAt: "desc" }, { id: "desc" }] });
      if (latest?.id !== prior.id) throw new ConflictException("RECOMMENDATION_CHANGED");
      await tx.conversationMessage.create({ data: { id, conversationId: conversation.id, senderId: claims.sub, senderType: "user", content: message,
        metadata: { clientMessageId: requestId, recommendationResponse: "REJECT", recommendationId: prior.id, requestDigest: digest } } }); return true;
    });
    if (!reserve) { const replay = await this.db.conversationMessage.findUnique({ where: { id: id + "_reply" } }); if (!replay) throw new ConflictException("RECOMMENDATION_PENDING_OR_FAILED"); return replay; }
    try {
    const raw = await this.gateway.requestStructuredReasoning({ history: [], question: JSON.stringify({ currentUserRequest: message, rejectedRecommendation: previous,
      observed: source.checkpoint.understanding.facts, inferred: source.checkpoint.understanding.inferences }), schema: RECOMMENDATION_SCHEMA, name: "recommendation", purpose: "STRUCTURED_INSPECTION",
      systemInstruction: "Return one materially different improvement recommendation, not a plan, fact, approval or executable action. Use only supplied same-conversation certified source as context. Declare strategy from the contract. Choose a different strategy or changeKind and approach with at least four substantive new objective terms, not a reworded title. Do not invent preservation: redesign preservation is UNSPECIFIED unless expressly supplied by the current user. No operations or unsupported factual claims." });
    let value: unknown; try { value = JSON.parse(raw); } catch { throw new BadRequestException("RECOMMENDATION_INVALID"); }
    const next = parseRecommendation(value); assertRecommendationPreservation(next, message);
    if (!materiallyDifferent(previous, next)) throw new BadRequestException("RECOMMENDATION_NOT_DIFFERENT");
    return this.db.conversationMessage.create({ data: { id: id + "_reply", conversationId: conversation.id, senderId: "agent", senderType: "assistant", content: recommendationMessage(next),
      metadata: { recommendation: { ...previous, ...next, generation: (previous.generation ?? 1) + 1, supersedes: prior.id }, rejectionMessageId: id } } });
    } catch (error) {
      await persistSubmissionFailure(this.db, conversation, claims.sub, requestId, message, error);
      throw error;
    }
  }
}

import { readExactProposal } from "./change-selection";
import { RuntimeLedgerService } from "../trusted-runtime/runtime-ledger.service";
import { toolDigest } from "../agent-runtime/tools/tool-contract";
import { ServiceUnavailableException } from "@nestjs/common";
import type { SessionClaims } from "../auth/auth.dto";
import { projectConsent } from "./consent-presentation";
import { exactContinuationRunTx } from "../agent-runtime/execution/exact-proposal.service";
import type { DownstreamWorkflowView } from "./workflow-presentation.contract";
export type { DownstreamWorkflowView } from "./workflow-presentation.contract";

/** Read-only presentation. These fields are never admission or execution authority. */

export async function projectDownstreamWorkflow(db: any, run: any, conversation: any, now = Date.now(), claims?: SessionClaims): Promise<DownstreamWorkflowView | undefined> {
  if (!db.auditEvent?.findUnique) return undefined;
  const ledger = new RuntimeLedgerService(db);
  run = await exactContinuationRunTx(ledger, db, run);
  const plan = run.plans?.[0];
  if (!plan?.id) return undefined;
  let record;
  try { record = await readExactProposal(ledger, db, conversation.userId, conversation.id, plan.id); }
  catch (error) {
    if (error instanceof Error && ["CHANGE_SET_RECOMMENDATION_REJECTED", "CHANGE_SELECTION_STALE", "CHANGE_SET_CHANGED"].includes(error.message)) return undefined;
    throw error;
  }
  if (!record) return undefined;
  const p = record.payload;
  if (typeof p.proposalId !== "string" || !/^[A-Za-z0-9_-]{1,128}$/.test(p.proposalId) || p.version !== 1 ||
    typeof p.digest !== "string" || !/^[a-f0-9]{64}$/.test(p.digest)) throw new ServiceUnavailableException("RUNTIME_LEDGER_CORRUPT");
  const identity = plan.steps?.[0]?.parameters?.engineeringPlan;
  const workspace = conversation.metadata?.runtimeWorkspace;
  const { digest: proposalDigest, ...proposalBase } = p;
  const stale = !record.immutable || p.conversationId !== conversation.id || p.userId !== conversation.userId ||
    (p.continuationRunId !== undefined && p.continuationRunId !== run.id) ||
    (run.id?.startsWith("exact_plan_run_") && p.continuationRunId !== run.id) ||
    p.projectId !== conversation.projectId || p.planId !== plan.id || p.planVersion !== run.planVersion ||
    p.planDigest !== identity?.digest || p.status !== "EXACT_PROPOSAL_READY" || proposalDigest !== toolDigest(proposalBase) ||
    (workspace && (workspace.workspaceId !== p.workspace.workspaceId || workspace.bindingVersion !== p.workspace.bindingVersion));
  const view: DownstreamWorkflowView = { observedAt: now, proposal: { id: p.proposalId, version: p.version, digest: p.digest,
    revision: record.revision, state: stale ? "STALE" : "READY", planId: plan.id,
    verification: Array.isArray(p.actions) && p.actions.some((a: any) => a.tool === "filesystem.read" && /^[a-f0-9]{64}$/.test(a.expectedAfterHash ?? "")) ? ["Read-back and expected content hash comparison", "Exact-change preservation check"] : [],
    changes: Array.isArray(p.changes) ? p.changes.slice(0, 1).filter((c: any) => typeof c.path === "string" && c.path.length <= 1024 && typeof c.before === "string" && c.before.length <= 8192 && typeof c.after === "string" && c.after.length <= 8192).map((c: any) => ({ path: c.path, before: c.before, after: c.after })) : [], ...(stale ? { blocker: "PROPOSAL_BINDING_CHANGED" } : {}) } };
  const key = [conversation.userId, conversation.id, p.proposalId];
  const head = await ledger.read<any>(db, "EXACT_APPROVAL_HEAD", key);
  const generation = head?.payload.generation ?? 1;
  if (!Number.isSafeInteger(generation) || generation < 1 || generation > 10000) throw new ServiceUnavailableException("RUNTIME_LEDGER_CORRUPT");
  const approvalId = `exactapproval_${toolDigest(generation === 1 ? key : [...key, generation])}`;
  const approval = await db.agentApproval.findUnique({ where: { id: approvalId } });
  if (approval) {
    const b = approval.revisedPlan;
    const { fingerprint: decisionFingerprint, ...decisionBinding } = b ?? {};
    const changed = stale || decisionFingerprint !== toolDigest(decisionBinding) || typeof b?.fingerprint !== "string" || !/^[a-f0-9]{64}$/.test(b.fingerprint) || (head && (b.generation !== generation || b.requestId !== head.payload.requestId)) || (head && head.payload.approvalId !== approvalId) || approval.agentRunId !== run.id ||
      approval.approvalType !== "EXACT_PROPOSAL" || b?.proposalId !== p.proposalId || b?.proposalDigest !== p.digest ||
      b?.proposalVersion !== p.version || b?.planId !== p.planId || b?.planVersion !== p.planVersion || b?.planDigest !== p.planDigest ||
      b?.conversationId !== conversation.id || toolDigest(b?.workspace ?? null) !== toolDigest(p.workspace) || b?.sourceDigest !== p.sourceDigest ||
      b?.sourceRunId !== p.sourceRunId || b?.sourceSequence !== p.sourceSequence ||
      b?.sourceFingerprint !== toolDigest({ workspace: p.workspace, sourceRunId: p.sourceRunId, sourceSequence: p.sourceSequence,
        sourceDigest: p.sourceDigest, evidenceReferences: p.evidenceReferences });
    const deadline = approval.dueAt && Number.isFinite(+new Date(approval.dueAt)) ? new Date(approval.dueAt).toISOString() : null;
    const expired = !deadline || Date.parse(deadline) <= now;
    const state = changed || !["PENDING", "APPROVED", "DENIED", "CANCELLED", "EXPIRED"].includes(approval.status) ? "STALE" : expired && ["PENDING", "APPROVED", "EXPIRED"].includes(approval.status) ? "EXPIRED" : approval.status;
    view.approval = { id: approvalId, generation, revision: head?.revision ?? 1, state, deadline,
      actionable: state === "PENDING", ...(!changed ? { fingerprint: b.fingerprint } : {}), ...(changed || expired ? { blocker: changed ? "APPROVAL_BINDING_CHANGED" : "APPROVAL_EXPIRED" } : {}) };
  }
  view.consent = await projectConsent(db, p, plan, approval?.revisedPlan?.taskConsent, claims, stale);
  if (view.consent.selected && view.consent.selected.state !== "ACTIVE" && view.approval && ["PENDING", "APPROVED"].includes(view.approval.state)) {
    view.approval = { ...view.approval, state: "STALE", actionable: false, blocker: view.consent.selected.reasons[0] };
  }
  const permitHead = await ledger.read<any>(db, "EXACT_PERMIT_HEAD", key);
  const permitGeneration = permitHead?.payload.generation ?? 1;
  if (!Number.isSafeInteger(permitGeneration) || permitGeneration < 1 || permitGeneration > 10000) throw new ServiceUnavailableException("RUNTIME_LEDGER_CORRUPT");
  const permit = await ledger.read<any>(db, "EXACT_EXECUTION_PERMIT", permitGeneration === 1 ? key : [...key, permitGeneration]);
  if (permit) {
    const value = permit.payload;
    if (typeof value.permitId !== "string" || !/^[A-Za-z0-9_-]{1,128}$/.test(value.permitId)) throw new ServiceUnavailableException("RUNTIME_LEDGER_CORRUPT");
    const consumed = await ledger.read(db, "EXACT_PERMIT_CONSUMPTION", value.permitId);
    const changed = stale || (permitHead && permitHead.payload.permitId !== value.permitId) ||
      value.binding?.proposalDigest !== p.digest || value.binding?.approvalId !== approvalId ||
      (value.binding?.generation ?? 1) !== generation;
    const state = consumed ? "CONSUMED" : changed ? "STALE" : !Number.isFinite(Date.parse(value.expiresAt)) || Date.parse(value.expiresAt) <= now ? "EXPIRED" : "UNUSED";
    view.permit = { id: value.permitId, generation: permitGeneration, revision: permitHead?.revision ?? permit.revision,
      state, deadline: Number.isFinite(Date.parse(value.expiresAt)) ? new Date(value.expiresAt).toISOString() : "", ...(state === "STALE" || state === "EXPIRED" ? { blocker: `PERMIT_${state}` } : {}) };
  }
  return view;
}

import { Injectable } from "@nestjs/common";
import { FileIntelligenceError } from "../file-intelligence.errors";
import { FILE_INTELLIGENCE_LIMITS } from "../file-intelligence.limits";
import type { FileExtractionInput } from "../models/file-intelligence.types";
import { TextDecoder } from "node:util";
import { WorkspaceSecurityService } from "../../workspace-intelligence/security/workspace-security.service";
import { WorkspacePathService } from "../../workspace-intelligence/workspace-path.service";

const CONTROL_CHARS = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g;

@Injectable()
export class FileIntelligenceSecurityService {
  /** Reuse the existing sensitive-path policy for uploaded names as well. */
  assertSafeFileName(fileName: string): void {
    const policy = new WorkspaceSecurityService(new WorkspacePathService());
    if (String(fileName).replace(/\\/g, "/").split("/").some(part =>
      policy.isSensitiveFile(part) || policy.isForbiddenDirectoryName(part))) {
      throw new FileIntelligenceError("FILE_ACCESS_DENIED");
    }
  }

  assertNoSecrets(text: string): void {
    // Same high-confidence secret forms excluded by repository snapshots.
    if (/-----BEGIN [A-Z ]*PRIVATE KEY-----/.test(text) || /\bAKIA[0-9A-Z]{16}\b/.test(text) ||
      /\bgh[pousr]_[A-Za-z0-9]{30,}\b/.test(text) || /\bsk-[A-Za-z0-9_-]{20,}\b/.test(text) ||
      /(?:password|passwd|api[_-]?key|secret|token|authorization)\s*[:=]\s*["']?[A-Za-z0-9_+./=-]{12,}/i.test(text)) {
      throw new FileIntelligenceError("FILE_ACCESS_DENIED");
    }
  }

  /** Inspect the entire already size-bounded buffer; never accept replacement decoding. */
  inspectText(buffer: Buffer): string {
    let text: string;
    try { text = new TextDecoder("utf-8", { fatal: true }).decode(buffer); }
    catch { throw new FileIntelligenceError("UNSUPPORTED_FILE_FORMAT"); }
    if (/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/.test(text)) {
      throw new FileIntelligenceError("UNSUPPORTED_FILE_FORMAT");
    }
    this.assertNoSecrets(text);
    return text;
  }
  /**
   * Normalize a client-supplied filename to a basename only.
   * Path separators and traversal sequences are discarded; never used as a filesystem path.
   */
  normalizeFileName(fileName: string): string {
    const unified = String(fileName ?? "").replace(/\\/g, "/").replace(/\0/g, "");
    const segments = unified.split("/").filter((part) => part.length > 0 && part !== "." && part !== "..");
    const base = segments.length > 0 ? segments[segments.length - 1] : "unnamed";
    const trimmed = base.trim().slice(0, 255);
    return trimmed.length > 0 ? trimmed : "unnamed";
  }

  assertExtractionInput(input: FileExtractionInput): void {
    if (!input || !Buffer.isBuffer(input.buffer)) {
      throw new FileIntelligenceError("FILE_DETECTION_FAILED");
    }
    if (input.buffer.length === 0) {
      throw new FileIntelligenceError("FILE_DETECTION_FAILED", "File buffer is empty.");
    }
    if (input.buffer.length > FILE_INTELLIGENCE_LIMITS.MAX_FILE_BYTES || input.sizeBytes > FILE_INTELLIGENCE_LIMITS.MAX_FILE_BYTES) {
      throw new FileIntelligenceError("FILE_TOO_LARGE");
    }
  }

  decodeUtf8(buffer: Buffer): string {
    let offset = 0;
    if (buffer.length >= 3 && buffer[0] === 0xef && buffer[1] === 0xbb && buffer[2] === 0xbf) {
      offset = 3;
    }
    return buffer.subarray(offset).toString("utf8");
  }

  normalizeText(text: string): string {
    return text.replace(/\r\n/g, "\n").replace(/\r/g, "\n").replace(CONTROL_CHARS, "");
  }

  applyTextBudget(text: string): { text: string; truncated: boolean } {
    if (text.length <= FILE_INTELLIGENCE_LIMITS.MAX_EXTRACTED_TEXT_CHARS) {
      return { text, truncated: false };
    }
    return {
      text: text.slice(0, FILE_INTELLIGENCE_LIMITS.MAX_EXTRACTED_TEXT_CHARS),
      truncated: true
    };
  }

  detectLanguage(text: string): string | undefined {
    const sample = text.slice(0, 2_000);
    if (/[\u0600-\u06FF]/.test(sample)) {
      return "ar";
    }
    return undefined;
  }

  hasNulBytes(buffer: Buffer, sampleBytes = 1024): boolean {
    const sample = buffer.subarray(0, Math.min(buffer.length, sampleBytes));
    return sample.includes(0x00);
  }
}

import "reflect-metadata";
import { readFileSync } from "node:fs";

function loadEnvFile(path: string): void {
  try {
    const content = readFileSync(path, "utf8");
    for (const line of content.split(/\r?\n/)) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eqIdx = trimmed.indexOf("=");
      if (eqIdx === -1) continue;
      const key = trimmed.slice(0, eqIdx).trim();
      const value = trimmed.slice(eqIdx + 1).trim();
      if (!process.env[key]) process.env[key] = value;
    }
  } catch {}
}
loadEnvFile(".env");
loadEnvFile("backend/.env");

import { NestFactory } from "@nestjs/core";
