    if (!isRecord(body) || Object.keys(body).sort().join(",") !== "capabilities,expectedRevision,mode,projectId,runtimeId" ||
      body.mode !== "TRUSTED_MACHINE" || !validToolId(body.runtimeId) || !validToolId(body.projectId) ||
