      const bucket = this.rate.get(key) ?? { at: now, count: 0 };
      if (++bucket.count > 120 || this.rate.size > 1024) throw new HttpException("RUNTIME_RATE_LIMIT", 429);
      this.rate.set(key, bucket);
    }
  }
  @Post("enrollment") async enrollment(@Req() req: Request, @Body() body: any) {
    this.tls(req, true); boundedRuntime(body); return response(await this.identity.enrollment(body.publicKey, body.runtimeVersion));
  }
  @Post("enrollment-proof") async proof(@Req() req: Request, @Body() body: any) {
    this.tls(req, true); boundedRuntime(body); return response(await this.identity.proveEnrollment(body.code, body.timestamp, body.signature));
  }
  @Post("challenge") async challenge(@Req() req: Request, @Body() body: any) {
    this.tls(req, true); boundedRuntime(body); return response(await this.identity.challenge(body.runtimeId, body.operation, body.payload));
  }
  @Post(":operation") async operation(@Req() req: Request, @Param("operation") operation: string, @Body() body: any) {
    this.tls(req); boundedRuntime(body);
    if (!["connect", "poll", "started", "heartbeat", "result", "folder-result"].includes(operation)) runtimeError("RUNTIME_OPERATION_INVALID");
    return response(await this.executions.request(operation as any, body.payload, body.auth));
  }
}

import type { RuntimeLedgerService } from "./runtime-ledger.service";
import { persistentReadAccessTx, developmentReadPolicy } from "./development-read-policy";
import { win32 } from "node:path";
import { toolDigest } from "../agent-runtime/tools/tool-contract";
import { FileIntelligenceSecurityService } from "../file-intelligence/security/file-intelligence-security.service";
import { excludedFromWorkspaceDiscovery } from "../workspace-intelligence/workspace-discovery.policy";
import { workspaceTarget } from "../workspace-intelligence/workspace-runtime.contract";
import { runtimeError, WORKSPACE_READ_TOOLS, WORKSPACE_READ_TTL_MS, type RuntimeGrant, type WorkspaceReadConsent, type WorkspaceReadCoverage } from "./runtime.contract";

export function readConsentFingerprint(consent: Omit<WorkspaceReadConsent, "fingerprint" | "status" | "revokedAt">) {
  return toolDigest(consent);
}
export function readConsentUnexpired(consent: WorkspaceReadConsent, persistent = false): boolean {
  return persistent && developmentReadPolicy()
    ? consent.expiresAt === null || Number.isFinite(Date.parse(consent.expiresAt))
    : consent.expiresAt !== null && Number.isFinite(Date.parse(consent.expiresAt)) && Date.parse(consent.expiresAt) > Date.now();
}
export function readCoverage(grant: RuntimeGrant, expected: { workspaceId: string; bindingVersion: number; rootPath: string; runtimeId: string; runtimeFingerprint: string; userId: string; organizationId: string; projectId: string }, tool: string, path: string): WorkspaceReadCoverage | undefined {
  const c = grant.workspaceRead;
  if (!c || c.workspaceId !== expected.workspaceId || c.bindingVersion !== expected.bindingVersion) return;
  const { fingerprint, status, revokedAt, ...signed } = c;
  if (c.kind !== "WORKSPACE_READ" || c.bindingId !== c.workspaceId || fingerprint !== readConsentFingerprint(signed) ||
    c.runtimeId !== grant.runtimeId || c.userId !== grant.userId || c.projectId !== grant.projectId || c.organizationId !== grant.organizationId ||
    ["workspaceId", "bindingVersion", "rootPath", "runtimeId", "runtimeFingerprint", "userId", "organizationId", "projectId"].some(k => (c as any)[k] !== (expected as any)[k]) || c.approvedBy !== c.userId ||
    status !== "ACTIVE" || revokedAt || !readConsentUnexpired(c, grant.persistentReadAccess) ||
    (c.expiresAt !== null && Date.parse(c.expiresAt) - Date.parse(c.approvedAt) > WORKSPACE_READ_TTL_MS) || !Number.isFinite(Date.parse(c.approvedAt)) ||
    toolDigest([...c.capabilities].sort()) !== toolDigest([...WORKSPACE_READ_TOOLS].sort()) || !c.capabilities.includes(tool as any) ||
    grant.status !== "ACTIVE" || !grant.capabilities.includes(tool as any) || (grant.expiresAt && Date.parse(grant.expiresAt) <= Date.now() && !(developmentReadPolicy() && grant.persistentReadAccess))) runtimeError("WORKSPACE_READ_GRANT_INVALID");
  const target = workspaceTarget(c.rootPath, win32.relative(c.rootPath, path));
  if (target.absolutePath !== path) runtimeError("WORKSPACE_READ_SCOPE_DENIED");
  new FileIntelligenceSecurityService().assertSafeFileName(target.relativePath);
  if (target.relativePath.split("/").some(excludedFromWorkspaceDiscovery)) runtimeError("WORKSPACE_READ_PATH_DENIED");
  return { kind: "WORKSPACE_READ_GRANT", grantId: grant.grantId, grantVersion: grant.version, consent: c,
    ...(developmentReadPolicy() && grant.persistentReadAccess ? { lifecycle: "DEVELOPMENT_ENROLLED_READ" as const } : {}) };
}

/** New consent heads override historical inline consent, including expired/revoked heads. */
export async function workspaceReadConsentTx(ledger: RuntimeLedgerService, tx: any,
  expected: { userId: string; organizationId: string; projectId: string; workspaceId: string; bindingVersion: number }, grant?: RuntimeGrant) {
  const row = await ledger.read<WorkspaceReadConsent>(tx, "WORKSPACE_READ_CONSENT",
    [expected.userId, expected.organizationId, expected.projectId, expected.workspaceId, expected.bindingVersion]);
  return row?.payload ?? grant?.workspaceRead;
}
/** The grant is never persisted or modified here. Both authorities are validated independently. */
export async function readCoverageTx(ledger: RuntimeLedgerService, tx: any, grant: RuntimeGrant,
  expected: Parameters<typeof readCoverage>[1], tool: string, path: string) {
  const consent = await workspaceReadConsentTx(ledger, tx, expected, grant);
  return readCoverage({ ...grant, persistentReadAccess: await persistentReadAccessTx(ledger, tx, grant), workspaceRead: consent }, expected, tool, path);
}

import * as fs from "node:fs/promises";
import { isAbsolute, parse, relative, resolve, sep, join } from "node:path";
import { FileIntelligenceSecurityService } from "../file-intelligence/security/file-intelligence-security.service";
import { excludedFromWorkspaceDiscovery } from "../workspace-intelligence/workspace-discovery.policy";
import { WORKSPACE_READ_TOOLS, type RuntimeAttribution } from "./runtime.contract";

/** Additional checks for reusable consent on the already-trusted worker. Not an OS sandbox. */
export async function checkWorkspaceReadPath(a: RuntimeAttribution, path: string) {
  const coverage = a.workspaceRead;
  if (!coverage) return;
  const c = coverage.consent;
  if (coverage.kind !== "WORKSPACE_READ_GRANT" || coverage.grantId !== a.grantId || coverage.grantVersion !== a.grantVersion ||
    c.status !== "ACTIVE" || !!c.revokedAt || (coverage.lifecycle === "DEVELOPMENT_ENROLLED_READ"
      ? c.expiresAt !== null && !Number.isFinite(Date.parse(c.expiresAt))
      : c.expiresAt === null || Date.parse(c.expiresAt) <= Date.now() || !Number.isFinite(Date.parse(c.expiresAt))) ||
    !WORKSPACE_READ_TOOLS.includes(a.tool as any) || !c.capabilities.includes(a.tool as any) || c.runtimeId !== a.runtimeId ||
    c.userId !== a.userId || c.organizationId !== a.organizationId || c.projectId !== a.projectId) throw new Error("WORKSPACE_READ_SCOPE_DENIED");
  const root = resolve(c.rootPath), target = resolve(path), rel = relative(root, target);
  if (rel === ".." || rel.startsWith(`..${sep}`) || isAbsolute(rel)) throw new Error("WORKSPACE_READ_SCOPE_DENIED");
  new FileIntelligenceSecurityService().assertSafeFileName(rel.replace(/\\/g, "/"));
  if (rel.split(sep).some(excludedFromWorkspaceDiscovery)) throw new Error("WORKSPACE_READ_PATH_DENIED");
  // Reject links in the root as well as every addressed descendant. Never use an alias to widen consent.
  let current = parse(target).root;
  for (const part of target.slice(current.length).split(sep).filter(Boolean)) {
    current = join(current, part);
    const stat = await fs.lstat(current);
    if (stat.isSymbolicLink() || (stat.isFile() && stat.nlink !== 1)) throw new Error("WORKSPACE_READ_ALIAS_DENIED");
  }
  const canonical = await fs.realpath(target), canonicalRoot = await fs.realpath(root);
  const equal = (a: string, b: string) => process.platform === "win32" ? a.toLowerCase() === b.toLowerCase() : a === b;
  if (!equal(canonical, target) || !equal(canonicalRoot, root)) throw new Error("WORKSPACE_READ_ALIAS_DENIED");
}

import { Injectable } from "@nestjs/common";
import { promises as fs } from "node:fs";
import { FileIntelligenceError } from "../file-intelligence/file-intelligence.errors";
import { FileIntelligenceService } from "../file-intelligence/file-intelligence.service";
import type { NormalizedDocumentContent } from "../file-intelligence/models/normalized-document-content";
import { classifyByExtension, isImportantFile, languageForExtension } from "./workspace-classification";
import type {
  TrustedWorkspaceContext,
  Workspace,
  WorkspaceNode,
  WorkspaceSummary,
  WorkspaceTree
} from "./models/workspace.types";
import { WorkspaceDiscoveryService } from "./workspace-discovery.service";
import { WorkspaceSecurityService } from "./security/workspace-security.service";
import { toControlledWorkspaceError, WorkspaceIntelligenceError } from "./workspace-intelligence.errors";
import { WORKSPACE_INTELLIGENCE_LIMITS } from "./workspace-intelligence.limits";
import { WorkspacePathService } from "./workspace-path.service";

@Injectable()
export class WorkspaceIntelligenceService {
  constructor(
    private readonly discovery: WorkspaceDiscoveryService,
    private readonly fileIntelligence: FileIntelligenceService,
    private readonly security: WorkspaceSecurityService,
    private readonly paths: WorkspacePathService
  ) {}

  /**
   * Project is the durable workspace identity. No filesystem root is implied.
   */
  workspaceFromProject(project: { id: string; name: string; createdAt?: string; updatedAt?: string }): Workspace {
    return {
      id: project.id,
      projectId: project.id,
      name: project.name,
      source: "unknown",
      createdAt: project.createdAt,
      updatedAt: project.updatedAt
    };
  }

  unsupportedSource(_kind: "git" | "github" | "gitlab" | "attachment"): never {
    throw new WorkspaceIntelligenceError("WORKSPACE_SOURCE_UNSUPPORTED");
  }

  async inspectWorkspace(context: TrustedWorkspaceContext, query = ""): Promise<{ workspace: Workspace; tree: WorkspaceTree }> {
    const tree = await this.discovery.discoverTree(context, query);
    return {
      workspace: {
        id: context.workspaceId,
        projectId: context.projectId,
        name: context.name,
        source: "local"
      },
      tree
    };
  }

  async summarizeWorkspace(context: TrustedWorkspaceContext): Promise<WorkspaceSummary> {
    const { tree } = await this.inspectWorkspace(context);
    const languages: Record<string, number> = {};
    const fileCategories: Record<string, number> = {};
    const importantFiles: string[] = [];
    this.walkFiles(tree.root, (node) => {
      const kind = String(node.metadata?.kind ?? "unknown");
      fileCategories[kind] = (fileCategories[kind] ?? 0) + 1;
      const language = languageForExtension(node.extension ?? "") ?? (typeof node.metadata?.language === "string" ? node.metadata.language : undefined);
      if (language) {
        languages[language] = (languages[language] ?? 0) + 1;
      }
      if (isImportantFile(node.path)) {
        importantFiles.push(node.path);
      }
    });
    importantFiles.sort((a, b) => a.localeCompare(b, "en", { sensitivity: "base" }));
    return {
      workspaceId: context.workspaceId,
      name: context.name,
      fileCount: tree.fileCount,
      directoryCount: tree.directoryCount,
      totalBytes: tree.totalBytes,
      languages,
      fileCategories,
      importantFiles,
      warnings: tree.warnings
    };
  }

  async inspectFile(context: TrustedWorkspaceContext, relativePath: string): Promise<NormalizedDocumentContent> {
    const trustedRoot = this.discovery.assertTrustedRoot(context.trustedRoot, context.authorizedRoots);
    const safeRelative = this.paths.normalizeRelativePath(relativePath);
    const absPath = this.security.resolveReadablePath(trustedRoot, safeRelative);
    this.security.assertInsideRoot(trustedRoot, absPath);

    if (this.security.isEscapingSymlink(trustedRoot, absPath)) {
      throw new WorkspaceIntelligenceError("WORKSPACE_PATH_OUTSIDE_ROOT");
    }

    const fileName = this.paths.fileNameOf(safeRelative);
    if (this.security.isSensitiveFile(fileName) || safeRelative.split("/").some((segment) => this.security.isForbiddenDirectoryName(segment))) {
      throw new WorkspaceIntelligenceError("WORKSPACE_FILE_ACCESS_DENIED");
    }

    let stats;
    try {
      stats = await fs.stat(absPath);
    } catch {
      throw new WorkspaceIntelligenceError("WORKSPACE_FILE_NOT_FOUND");
    }
    if (!stats.isFile()) {
      throw new WorkspaceIntelligenceError("WORKSPACE_FILE_NOT_FOUND");
    }
    if (stats.size > WORKSPACE_INTELLIGENCE_LIMITS.MAX_SINGLE_FILE_BYTES) {
      throw new WorkspaceIntelligenceError("WORKSPACE_FILE_TOO_LARGE");
    }

    let buffer: Buffer;
    try {
      buffer = await fs.readFile(absPath);
    } catch {
      throw new WorkspaceIntelligenceError("WORKSPACE_INSPECTION_FAILED");
    }

    const classified = classifyByExtension(fileName, this.paths.extensionOf(fileName));
    try {
      return await this.fileIntelligence.extractFromBuffer({
        attachmentId: `${context.workspaceId}:${safeRelative}`,
        fileName,
        mimeType: classified.mimeType,
        interpretation: "source",
        sizeBytes: buffer.length,
        buffer
      });
    } catch (err) {
      if (err instanceof FileIntelligenceError) {
        throw new WorkspaceIntelligenceError(err.code === "FILE_ACCESS_DENIED" ? "WORKSPACE_FILE_ACCESS_DENIED" : "WORKSPACE_INSPECTION_FAILED", err.message, err.code);
      }
      throw toControlledWorkspaceError(err);
    }
  }

  private walkFiles(node: WorkspaceNode, visit: (node: WorkspaceNode) => void): void {
    if (node.type === "file") {
      visit(node);
      return;
    }
    for (const child of node.children ?? []) {
      this.walkFiles(child, visit);
    }
  }
}

import { BadRequestException, ConflictException, ForbiddenException, Inject, Injectable, UnauthorizedException } from "@nestjs/common";
import type { SessionClaims } from "../auth/auth.dto";
import { RuntimeIdentityService } from "../trusted-runtime/runtime-identity.service";
import { boundedRuntime } from "../trusted-runtime/runtime.contract";
import { isRecord, toolDigest, validToolId } from "../agent-runtime/tools/tool-contract";
import { AGENT_UNDERSTANDING_LIMITS } from "../agent-runtime/understanding/agent-understanding.types";
import { WorkspaceRuntimeService } from "./workspace-runtime.service";
import { WorkspaceStoreService } from "./workspace-store.service";
import { workspaceTarget, type WorkspaceBinding, type WorkspaceOperation, type RuntimeEvidenceRequest, type RuntimeEvidenceReference, type RuntimeEvidenceView, type RuntimeEvidenceState, type WorkspaceOperationView } from "./workspace-runtime.contract";
import { FileIntelligenceSecurityService } from "../file-intelligence/security/file-intelligence-security.service";
import { excludedFromWorkspaceDiscovery } from "./workspace-discovery.policy";

/** Admission only. This service never dispatches work except on explicit request(). */
@Injectable()
export class WorkspaceRuntimeEvidenceService {
  constructor(@Inject(WorkspaceStoreService) private readonly store: WorkspaceStoreService,
    @Inject(WorkspaceRuntimeService) private readonly runtime: WorkspaceRuntimeService,
    @Inject(RuntimeIdentityService) private readonly identity: RuntimeIdentityService) {}

  /** Called only by the persisted Agent loop in the same transaction as its exact plan/proposal. */
  async requestInspectionTx(tx: any, claims: SessionClaims, binding: WorkspaceBinding, runId: string, planVersion: number,
    action: { tool: "filesystem.list" | "filesystem.read" | "filesystem.search"; relativePath: string; query?: string }, conversationId: string, createdAt: string) {
    const target = workspaceTarget(binding.rootPath, action.relativePath);
    new FileIntelligenceSecurityService().assertSafeFileName(target.relativePath);
    if (target.relativePath.split("/").some(excludedFromWorkspaceDiscovery)) throw new ForbiddenException("INSPECTION_EXCLUDED_PATH");
    if (action.tool === "filesystem.read" && !target.relativePath) throw new BadRequestException("WORKSPACE_FILE_REQUIRED");
    await this.store.assertInspectionBindingTx(tx, { ...binding, bindingVersion: binding.version });
    if (binding.userId !== claims.sub || binding.organizationId !== claims.organizationId) throw new ForbiddenException("WORKSPACE_EVIDENCE_SCOPE_MISMATCH");
    const requestId = `inspection_${toolDigest([runId, planVersion])}`, operationId = `wsop_${toolDigest(requestId)}`;
    const request: RuntimeEvidenceRequest = { requestId, workspaceId: binding.workspaceId, bindingVersion: binding.version, runtimeId: binding.runtimeId,
      runtimeFingerprint: binding.runtimeFingerprint, relativePath: target.relativePath, projectId: binding.projectId, organizationId: binding.organizationId,
      userId: claims.sub, conversationId, operationId };
    const operation: WorkspaceOperation = { ...target, operationId, workspaceId: binding.workspaceId, bindingVersion: binding.version, runtimeId: binding.runtimeId,
      projectId: binding.projectId, organizationId: binding.organizationId, userId: claims.sub, conversationId, runtimeRequestId: requestId, runId, planVersion,
      tool: action.tool, kind: action.tool === "filesystem.read" ? "READ" : action.tool === "filesystem.list" ? "LIST" : "SEARCH",
      ...(action.tool === "filesystem.search" ? { query: action.query! } : {}), createdAt };
    await this.store.saveInspectionTx(tx, operation, request);
    return { request, operation };
  }

  private async actor(claims: SessionClaims, projectId: string, conversationId: string) {
    if (!claims.sessionId || !claims.exp) throw new UnauthorizedException("WORKSPACE_EVIDENCE_SESSION_REQUIRED");
    return this.identity.ledger.transaction(async tx => {
      const fresh = await this.identity.actor(tx, claims.sub, claims.organizationId!, projectId,
        { id: claims.sessionId, issuedAt: claims.iat ?? 0, expiresAt: claims.exp });
      const c = await tx.conversation.findUnique({ where: { id: conversationId } });
      if (!c || c.userId !== fresh.sub || c.projectId !== projectId) throw new ForbiddenException("WORKSPACE_EVIDENCE_CONVERSATION_DENIED");
      return fresh;
    });
  }

  async request(claims: SessionClaims, projectId: string, workspaceId: string, body: unknown): Promise<RuntimeEvidenceView> {
    boundedRuntime(body);
    if (!isRecord(body) || Object.keys(body).some(k => !["bindingVersion", "runtimeId", "relativePath", "conversationId", "requestId"].includes(k)) ||
      !Number.isSafeInteger(body.bindingVersion) || !validToolId(body.runtimeId) || !validToolId(body.conversationId) || !validToolId(body.requestId)) throw new BadRequestException("WORKSPACE_EVIDENCE_REQUEST_INVALID");
    const fresh = await this.actor(claims, projectId, body.conversationId as string);
    const binding = await this.runtime.getBinding(fresh, projectId, workspaceId, Number(body.bindingVersion));
    if (binding.runtimeId !== body.runtimeId) throw new ConflictException("WORKSPACE_EVIDENCE_RUNTIME_MISMATCH");
    const target = workspaceTarget(binding.rootPath, body.relativePath);
    if (!target.relativePath) throw new BadRequestException("WORKSPACE_FILE_REQUIRED");
    // Distinct namespace from viewer reads; an ordinary read cannot be promoted by a client.
    const requestId = `wsevidence_${toolDigest([claims.sub, workspaceId, body.requestId])}`;
    const operationId = `wsop_${toolDigest(`wsrequest_${toolDigest([workspaceId, binding.version, requestId])}`)}`;
    const request = await this.store.saveEvidenceRequest({ requestId, workspaceId, bindingVersion: binding.version,
      runtimeId: binding.runtimeId, runtimeFingerprint: binding.runtimeFingerprint, relativePath: target.relativePath,
      projectId, organizationId: fresh.organizationId!, userId: fresh.sub, conversationId: body.conversationId as string, operationId });
    await this.runtime.request(fresh, projectId, workspaceId, "READ", { bindingVersion: binding.version,
      relativePath: target.relativePath, conversationId: request.conversationId, requestId });
    return this.observe(fresh, projectId, workspaceId, binding.version, requestId);
  }

  private state(view: WorkspaceOperationView): RuntimeEvidenceState {
    switch (view.state) {
      case "READY": return "VERIFIED";
      case "TRUNCATED": return "TRUNCATED";
      case "LOADING": return "PENDING";
      case "APPROVAL_REQUIRED": case "EXECUTING": case "DENIED": case "FAILED": case "STALE": return view.state;
      case "REVOKED": case "UNAUTHORIZED": case "EXPIRED_GRANT": return "DENIED";
      default: return "UNAVAILABLE";
    }
  }

  private async observation(claims: SessionClaims, projectId: string, workspaceId: string, version: number, requestId: string) {
    const request = await this.store.getEvidenceRequest(requestId);
    if (!request || request.userId !== claims.sub || request.organizationId !== claims.organizationId || request.projectId !== projectId ||
      request.workspaceId !== workspaceId || request.bindingVersion !== version) throw new ForbiddenException("WORKSPACE_EVIDENCE_SCOPE_MISMATCH");
    const fresh = await this.actor(claims, projectId, request.conversationId);
    const binding = await this.runtime.getBinding(fresh, projectId, workspaceId, version);
    const historical = await this.store.getEvidenceReceipt(requestId);
    const active = await this.store.getActiveBinding(fresh.sub, projectId, fresh.organizationId!);
    if (active?.workspaceId !== workspaceId || active.version !== version || binding.runtimeId !== request.runtimeId || binding.runtimeFingerprint !== request.runtimeFingerprint) {
      return { view: { request, state: "STALE", reference: historical ?? undefined, historical: !!historical } as RuntimeEvidenceView };
    }
    if (["OFFLINE", "REVOKED", "EXPIRED_GRANT", "UNAUTHORIZED", "STALE"].includes(binding.status)) {
      const state: RuntimeEvidenceState = binding.status === "OFFLINE" ? "UNAVAILABLE" : binding.status === "STALE" ? "STALE" : "DENIED";
      return { view: { request, state, reference: historical ?? undefined, historical: !!historical } as RuntimeEvidenceView };
    }
    const operation = await this.store.getOperation(request.operationId);
    if (!operation) return { view: { request, state: "PENDING", historical: false } as RuntimeEvidenceView };
    if ((operation.kind !== "READ" && !(operation.planVersion && ["LIST", "SEARCH"].includes(operation.kind))) || operation.conversationId !== request.conversationId || operation.relativePath !== request.relativePath || operation.runtimeId !== request.runtimeId) throw new ConflictException("WORKSPACE_EVIDENCE_OPERATION_MISMATCH");
    const result = await this.runtime.operation(fresh, projectId, workspaceId, version, request.operationId);
    const state = this.state(result);
    // Listings/searches are labelled observations, never represented as having read each file.
    let file = result.file;
    if (result.receipt && operation.planVersion && (result.entries || result.matches)) {
      const security = new FileIntelligenceSecurityService();
      const entries = result.entries?.filter(e => {
        try { security.assertSafeFileName(e.path); return !e.path.split("/").some(excludedFromWorkspaceDiscovery); } catch { return false; }
      });
      file = { text: JSON.stringify({ operation: operation.tool, path: operation.relativePath, ...(entries ? { entries } : { matches: result.matches }) }),
        fileName: operation.relativePath || ".", mimeType: "application/json", warnings: ["Runtime directory/search observation only. Listed files were not read in full."] };
    }
    let reference = historical ?? undefined;
    if ((state === "VERIFIED" || state === "TRUNCATED") && file && result.receipt) {
      if (!historical) {
        reference = await this.store.saveEvidenceReceipt({ ...request, receiptId: result.receipt.receiptId,
          observationTime: result.receipt.observedAt, contentIdentity: { status: "UNAVAILABLE" }, truncated: result.receipt.truncated,
          encoding: "utf-8-decoded", sourceType: "runtime-workspace", verificationState: "VERIFIED" });
      }
    }
    return { view: { request, state, reference, historical: !!reference && state !== "VERIFIED" && state !== "TRUNCATED",
      operation, message: result.message } as RuntimeEvidenceView, file };
  }

  async observe(claims: SessionClaims, projectId: string, workspaceId: string, version: number, requestId: string) {
    return (await this.observation(claims, projectId, workspaceId, version, requestId)).view;
  }

  /** Client references are coordinates, never content or proof. Revalidate the authoritative receipt. */
  async admit(claims: SessionClaims, projectId: string, conversationId: string, reference: RuntimeEvidenceReference) {
    boundedRuntime(reference);
    if (!isRecord(reference) || !validToolId(reference.requestId) || reference.conversationId !== conversationId) throw new ForbiddenException("WORKSPACE_EVIDENCE_REFERENCE_INVALID");
    const result = await this.observation(claims, projectId, reference.workspaceId, reference.bindingVersion, reference.requestId);
    if (!["VERIFIED", "TRUNCATED"].includes(result.view.state) || !result.file || !result.view.reference) throw new ConflictException(`WORKSPACE_EVIDENCE_${result.view.state}`);
    if (toolDigest(reference) !== toolDigest(result.view.reference)) throw new ConflictException("WORKSPACE_EVIDENCE_RECEIPT_MISMATCH");
    return { reference: result.view.reference, file: result.file, operation: result.view.operation };
  }

  async validateReferences(claims: SessionClaims, projectId: string, conversationId: string, references: unknown): Promise<RuntimeEvidenceReference[]> {
    if (!Array.isArray(references) || !references.length || references.length > AGENT_UNDERSTANDING_LIMITS.MAX_EVIDENCE_ITEMS) throw new BadRequestException("WORKSPACE_EVIDENCE_REFERENCES_INVALID");
    const result: RuntimeEvidenceReference[] = [];
    for (const reference of references) result.push((await this.admit(claims, projectId, conversationId, reference)).reference);
    return result;
  }
}

import { BadRequestException } from "@nestjs/common";
import { win32 } from "node:path";
import { runtimePath } from "../trusted-runtime/runtime.contract";

export const WORKSPACE_PRIVATE_MODULE = "SEKHEM_WORKSPACE_V1";
export type WorkspaceBindingVersion = number;
export type WorkspaceStatus = "VERIFYING" | "READY" | "OFFLINE" | "REVOKED" | "EXPIRED_GRANT" | "DIRECTORY_MISSING" | "UNAUTHORIZED" | "STALE";
export interface RuntimeWorkspaceReference { workspaceId: string; bindingVersion: WorkspaceBindingVersion }
export interface WorkspaceBinding {
  workspaceId: string; version: WorkspaceBindingVersion; revision: number;
  projectId: string; organizationId: string; userId: string; runtimeId: string; runtimeFingerprint: string;
  rootPath: string; displayName: string; status: WorkspaceStatus; verifiedAt: string | null;
  verificationReceiptId: string | null; createdAt: string; updatedAt: string;
}
export interface WorkspaceFileReference extends RuntimeWorkspaceReference { runtimeId: string; relativePath: string; receiptId: string }
export interface WorkspaceReceiptReference extends WorkspaceFileReference { observedAt: string; operationId: string; truncated: boolean }
export type RuntimeEvidenceState = "PENDING" | "APPROVAL_REQUIRED" | "EXECUTING" | "VERIFIED" | "TRUNCATED" | "UNAVAILABLE" | "DENIED" | "FAILED" | "STALE";
/** Explicit user intent, never derived from file content or an ordinary viewer receipt. */
export interface RuntimeEvidenceRequest extends RuntimeWorkspaceReference {
  requestId: string; runtimeId: string; runtimeFingerprint: string; relativePath: string;
  projectId: string; organizationId: string; userId: string; conversationId: string; operationId: string;
}
export interface RuntimeEvidenceReference extends RuntimeEvidenceRequest {
  receiptId: string; observationTime: string; contentIdentity: { status: "UNAVAILABLE" };
  truncated: boolean; encoding: "utf-8-decoded"; sourceType: "runtime-workspace"; verificationState: "VERIFIED";
}
