    assert.equal(h.run().status, "FAILED");
    assert.equal(h.run().failureReason, "INVALID_STRUCTURED_OUTPUT");
    assert.equal(h.skillCalls(), 0); assert.equal(h.modelCalls(), 1);
    assert.deepEqual(h.decisionStages, []);
  });
});

