import { it } from 'node:test';
import { readAgentEventPage, resolveAgentEventCursor } from '../src/agent-runtime/agent-run-event-replay';

function fixture(count = 5, status = 'RUNNING') {
  const events = Array.from({ length: count }, (_, i) => ({ id: `e${i}`, agentRunId: 'r', seq: i + 1, timestamp: new Date(1000 - i), eventType: 'LOG' }));
  const run = { status, eventSeq: count, eventTerminalSeq: status === 'COMPLETED' ? count : null };
  let reads = 0;
  const db: any = { agentRun: { findUnique: async () => run }, agentRunEvent: {
    findUnique: async ({ where }: any) => events.find(e => e.id === where.id),
    findMany: async ({ where, orderBy, take }: any) => { reads++; assert.deepEqual(orderBy, { seq: 'asc' }); return events.filter(e => e.agentRunId === where.agentRunId && e.seq > where.seq.gt && e.seq <= where.seq.lte).slice(0, take); },
  } };
  db.$transaction = async (fn: any, options: any) => { assert.equal(options.isolationLevel, 'RepeatableRead'); return fn(db); };
  return { db, events, run, reads: () => reads };
}

it('sequence cursor pagination is bounded and strictly after cursor', async () => {
  const f = fixture(); const p = await readAgentEventPage(f.db, 'r', 2, 2);
  assert.deepEqual(p.events.map((e: any) => e.seq), [3, 4]); assert.equal(p.nextCursor, 4); assert.equal(p.hasMore, true);
});
it('reconnect/reload uses persisted sequence without duplicating events or creating authority', async () => {
  const f = fixture(3, 'COMPLETED'); const p = await readAgentEventPage(f.db, 'r', 0, 2);
  const cursor = await resolveAgentEventCursor(f.db, 'r', `r:${p.nextCursor}`);
  const restored = await readAgentEventPage(f.db, 'r', cursor);
  assert.deepEqual(restored.events.map((e: any) => e.seq), [3]);
  assert.deepEqual(await readAgentEventPage(f.db, 'r', cursor), restored);
  assert.equal(f.events.length, 3); assert.equal(f.run.eventSeq, 3);
});
it('terminal watermark becomes complete only after all bounded pages', async () => {
  const f = fixture(3, 'COMPLETED');
  assert.equal((await readAgentEventPage(f.db, 'r', 0, 2)).replayComplete, false);
  const p = await readAgentEventPage(f.db, 'r', 2); assert.equal(p.terminalWatermark, 3); assert.equal(p.replayComplete, true);
});
it('running and paused runs cannot claim terminal replay completeness', async () => {
  for (const status of ['RUNNING', 'PAUSED', 'AWAITING_APPROVAL']) {
    const f = fixture(0, status); assert.equal((await readAgentEventPage(f.db, 'r')).replayComplete, false);
  }
});
it('rejects out-of-bounds cursors and page sizes', async () => {
  const f = fixture();
  for (const [cursor, limit] of [[-1, 1], [6, 1], [0, 129], [0, 0], [NaN, 1]]) await assert.rejects(readAgentEventPage(f.db, 'r', cursor, limit), /CURSOR_INVALID/);
});
it('foreign run cursors fail closed; legacy IDs resolve to sequence', async () => {
  const f = fixture(); assert.equal(await resolveAgentEventCursor(f.db, 'r', 'e2'), 3);
  await assert.rejects(resolveAgentEventCursor(f.db, 'other', 'e2'), /CURSOR_INVALID/);
  await assert.rejects(resolveAgentEventCursor(f.db, 'r', 'other:3'), /CURSOR_INVALID/);
});
it('missing persisted sequence or inconsistent watermark fails closed', async () => {
  const f = fixture(2, 'COMPLETED'); f.run.eventTerminalSeq = 1;
  await assert.rejects(readAgentEventPage(f.db, 'r'), /WATERMARK_INVALID/);
  f.run.eventTerminalSeq = 2; f.events.splice(0, 1);
  await assert.rejects(readAgentEventPage(f.db, 'r'), /SEQUENCE_GAP/);
});
it('SSE/transient frames are not inputs to the authoritative replay read model', async () => {
  const f = fixture(0); const transient = { type: 'stream-drained', data: { status: 'COMPLETED', seq: 99 } };
  assert.equal(transient.data.status, 'COMPLETED');
  const p = await readAgentEventPage(f.db, 'r'); assert.equal(p.watermark, 0); assert.equal(p.replayComplete, false); assert.deepEqual(p.events, []);
});

import { AgentRunRecoveryService } from "../src/agent-runtime/recovery/agent-run-recovery.service";
import { AgentContextProjectionService } from "../src/agent-runtime/context-projection/agent-context-projection.service";
import assert from 'node:assert/strict';
import { it } from 'node:test';
import { isolatedDatabaseUrl } from './helpers/isolated-database';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { PrismaClient } from '@prisma/client';

it('PostgreSQL durable append serializes concurrent writers, isolates runs, rolls back counters and restores terminal state', { skip: process.env.SEKHEM_RUNTIME_DB_TEST !== '1' }, async () => {
  // Only a disposable test schema is touched; never application/runtime/workspace records.
  const url = isolatedDatabaseUrl();
  const db = new PrismaClient({ datasources: { db: { url } } });
  const schema = `event_seq_test_${randomUUID().replaceAll('-', '')}`;
  const scoped = (fn: (tx: any) => Promise<any>) => db.$transaction(async tx => {
    await tx.$executeRawUnsafe(`SET LOCAL search_path TO "${schema}"`);
    return fn(tx);
  }, { timeout: 30000, maxWait: 30000 });
  let created = false;
  try {
    await db.$executeRawUnsafe(`CREATE SCHEMA "${schema}"`); created = true;
    await scoped(async tx => {
      await tx.$executeRawUnsafe('CREATE TABLE "AgentRun" ("id" TEXT PRIMARY KEY, "status" TEXT NOT NULL, "currentStepIndex" INTEGER NOT NULL DEFAULT 0, "planVersion" INTEGER NOT NULL DEFAULT 1, "failureReason" TEXT, "pausedAt" TIMESTAMP, "completedAt" TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP)');
      await tx.$executeRawUnsafe('CREATE TABLE "AgentRunEvent" ("id" TEXT PRIMARY KEY, "agentRunId" TEXT NOT NULL REFERENCES "AgentRun"("id"), "timestamp" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "actor" TEXT NOT NULL DEFAULT \'system\', "stepIndex" INTEGER DEFAULT 0, "eventType" TEXT NOT NULL DEFAULT \'STATUS_CHANGE\', "payload" JSONB NOT NULL DEFAULT \'{}\')');
      await tx.$executeRawUnsafe(`INSERT INTO "AgentRun" ("id","status") VALUES ('r','RUNNING'), ('s','COMPLETED')`);
      await tx.$executeRawUnsafe(`INSERT INTO "AgentRunEvent" ("id","agentRunId","timestamp") VALUES ('legacy-b','r','2020-01-01'), ('legacy-a','r','2020-01-01')`);
      const sql = readFileSync('prisma/migrations/20261004180000_agent_run_event_sequence/migration.sql', 'utf8').replace(/^BEGIN;\s*/, '').replace(/COMMIT;\s*$/, '');
      for (const statement of sql.split('-- statement').map(x => x.trim()).filter(Boolean)) await tx.$executeRawUnsafe(statement);
    });
    const append = (id: string, run: string) => scoped(tx => tx.$queryRawUnsafe('INSERT INTO "AgentRunEvent" ("id", "agentRunId", "timestamp", "seq") VALUES ($1,$2,$3,999) RETURNING "seq"', id, run, new Date(1)));
    const result = await Promise.all(Array.from({ length: 12 }, (_, i) => append(`new-${i}`, 'r')));
    assert.deepEqual(result.map(x => x[0].seq).sort((a,b) => a-b), Array.from({length:12}, (_,i) => i+3));
    assert.equal((await append('other', 's'))[0].seq, 1);
    await assert.rejects(scoped(async tx => { await tx.$executeRawUnsafe(`INSERT INTO "AgentRunEvent" ("id","agentRunId","timestamp") VALUES ('rollback','r',now())`); throw new Error('rollback'); }), /rollback/);
    assert.equal((await append('after-rollback', 'r'))[0].seq, 15);
    await assert.rejects(scoped(tx => tx.$executeRawUnsafe(`UPDATE "AgentRunEvent" SET "seq"=50 WHERE "id"='new-0'`)), /IMMUTABLE/);
    await scoped(tx => tx.$executeRawUnsafe(`UPDATE "AgentRun" SET "status"='COMPLETED' WHERE "id"='r'`));
    const restored: any = await scoped(tx => tx.$queryRawUnsafe(`SELECT * FROM "AgentRun" WHERE "id"='r'`));
    assert.equal(restored[0].eventSeq, 15); assert.equal(restored[0].eventTerminalSeq, 15);
    assert.equal((await append('trailing', 'r'))[0].seq, 16);
    const terminal: any = await scoped(tx => tx.$queryRawUnsafe(`SELECT * FROM "AgentRun" WHERE "id"='r'`));
    assert.equal(terminal[0].eventTerminalSeq, 16);
    await scoped(tx => tx.$executeRawUnsafe(`UPDATE "AgentRun" SET "status"='RUNNING' WHERE "id"='r'`));
    const resumed: any = await scoped(tx => tx.$queryRawUnsafe(`SELECT * FROM "AgentRun" WHERE "id"='r'`));
    assert.equal(resumed[0].eventTerminalSeq, null);
    const projectionUrl = new URL(url!); projectionUrl.searchParams.set('schema', schema);
    const reloadedClient = new PrismaClient({ datasources: { db: { url: projectionUrl.toString() } } });
    try {
      const projection = await new AgentContextProjectionService(reloadedClient as any).build('r', { cursor: 15 });
      assert.equal(projection.cursor, 15); assert.equal(projection.events.length, 15);
      assert.deepEqual(projection.events.map(e => e.seq), Array.from({length:15}, (_,i)=>i+1));
      assert.deepEqual(await new AgentContextProjectionService(reloadedClient as any).build('r', {cursor:15}), projection);
      const recovery = new AgentRunRecoveryService(reloadedClient as any, new AgentContextProjectionService(reloadedClient as any));
      let unlock!: () => void, acquired!: () => void;
      const release = new Promise<void>(r => { unlock = r; });
      const ready = new Promise<void>(r => { acquired = r; });
      const blocker = scoped(async tx => {
        await tx.$executeRawUnsafe('SELECT pg_advisory_xact_lock(hashtextextended($1,0))', 'agent-run-recovery:r');
        acquired(); await release;
      });
      await ready;
      try { await assert.rejects(recovery.parkInterrupted('r'), /RECOVERY_BUSY/); }
      finally { unlock(); await blocker; }
      assert.equal(await recovery.parkInterrupted('r'), true);
      assert.equal(await recovery.parkInterrupted('r'), false);
      const restored = await recovery.snapshot('r', 16);
      assert.equal(restored.status, 'PAUSED'); assert.equal(restored.recoveryState, 'UNCERTAIN');
      assert.equal(restored.replay.events.length, 1); assert.equal(restored.replay.events[0].eventType, 'RECOVERY_REQUIRED');
      assert.equal(restored.replay.events[0].seq, 17);
      assert.deepEqual(await recovery.snapshot('r', 16), restored);

    } finally { await reloadedClient.$disconnect(); }

  } finally {
    if (created) await db.$executeRawUnsafe(`DROP SCHEMA "${schema}" CASCADE`);
    await db.$disconnect();
  }
});

import "reflect-metadata";
import assert from "node:assert/strict";
import { test } from "node:test";
import { AgentRuntimeService } from "../src/agent-runtime/agent-runtime.service";
import type { EvidenceReceipt } from "../src/agent-runtime/understanding/agent-presentation";
import type { RuntimeEvidenceReference } from "../src/workspace-intelligence/workspace-runtime.contract";

function runtimeReference(overrides: Partial<RuntimeEvidenceReference> = {}): RuntimeEvidenceReference {
  return {
    requestId: "inspection-request",
    workspaceId: "workspace-a",
    bindingVersion: 39,
    runtimeId: "runtime-a",
    runtimeFingerprint: "fingerprint-a",
    relativePath: "index.html",
    projectId: "project-a",
    organizationId: "org-a",
    userId: "user-a",
    conversationId: "conversation-a",
    operationId: "operation-a",
    receiptId: "receipt-a",
    observationTime: "2026-10-01T10:57:02.939Z",
    contentIdentity: { status: "UNAVAILABLE" },
    truncated: true,
    encoding: "utf-8-decoded",
    sourceType: "runtime-workspace",
    verificationState: "VERIFIED",
    ...overrides
  };
}

const presentationEvidence = (id: string, reference?: RuntimeEvidenceReference): EvidenceReceipt => ({
  id,
  sourceType: "workspace",
  ...(reference ? { runtimeReference: reference, operation: "filesystem.read" } : {}),
  label: reference?.relativePath ?? id,
  ...(reference ? { relativePath: reference.relativePath } : {}),
  outcome: "READ",
  discovered: true,
  read: true,
  selected: true,
  usedInAnswer: "UNKNOWN",
  truncated: false,
  selectionReason: "Existing plan evidence."
});

test("getRun projects verified truncated inspection evidence without losing or duplicating existing evidence", async () => {
  const verifiedTruncated = runtimeReference();
  const duplicate = runtimeReference({ requestId: "request-duplicate", operationId: "operation-duplicate", receiptId: "receipt-duplicate", relativePath: "already-read.ts", truncated: false });
  const unverified = runtimeReference({ requestId: "request-unverified", operationId: "operation-unverified", receiptId: "receipt-unverified", relativePath: "unverified.ts", verificationState: "UNVERIFIED" as any });
  const planOnly = presentationEvidence("plan-only");
  const planDuplicate = presentationEvidence("plan-duplicate", duplicate);
  const executionOnly = presentationEvidence("execution-only", runtimeReference({ requestId: "execution-request", operationId: "execution-operation", receiptId: "execution-receipt", relativePath: "executed.ts", truncated: false }));
  const inspection: any = {
    evidence: [verifiedTruncated, duplicate, unverified],
    operations: [
      { request: { operationId: verifiedTruncated.operationId }, action: { tool: "filesystem.read", relativePath: "index.html" }, state: "TRUNCATED", verification: "VERIFIED", evidence: verifiedTruncated },
      { request: { operationId: duplicate.operationId }, action: { tool: "filesystem.read", relativePath: "already-read.ts" }, state: "VERIFIED", verification: "VERIFIED", evidence: duplicate },
      { request: { operationId: unverified.operationId }, action: { tool: "filesystem.read", relativePath: "unverified.ts" }, state: "VERIFIED", verification: "UNVERIFIED", evidence: unverified }
    ]
  };
  const run: any = {
    id: "run-a", conversationId: "conversation-a", projectId: "project-a", userId: "user-a", agentName: "Agent", title: "Inspect index.html",
    status: "RUNNING", planVersion: 1, currentStepIndex: 0, progressPercent: 0, pausedAt: null, startedAt: null, completedAt: null,
    failureReason: null, cancellationReason: null, createdAt: new Date(), updatedAt: new Date(),
    plans: [{ id: "plan-a", agentRunId: "run-a", version: 1, summary: "Inspection", steps: [{ parameters: { inspectionLoop: true, evidenceReceipt: [planOnly, planDuplicate] } }] }],
    approvals: [], artifacts: []
  };
  const claims: any = { sub: "user-a", organizationId: "org-a", sessionId: "session-a", exp: 2_000_000_000 };
  const service: any = Object.create(AgentRuntimeService.prototype);
  Object.assign(service, {
    prisma: { agentRun: { findUnique: async () => run } },
    resourceAuthz: { assertAuthorized: async () => undefined },
    planExecution: { view: async () => ({ planVersion: 1, receipts: [executionOnly] }) },
    inspections: { view: async () => inspection }
  });

  const result = await service.getRun("run-a", claims);
  const evidence = result.presentation.evidence as EvidenceReceipt[];
  const projected = evidence.find(item => item.runtimeReference?.receiptId === verifiedTruncated.receiptId);

  assert.ok(projected);
  assert.equal(projected.operation, "filesystem.read");
  assert.equal(projected.relativePath, "index.html");
  assert.equal(projected.runtimeReference?.operationId, verifiedTruncated.operationId);
  assert.equal(projected.runtimeReference?.workspaceId, verifiedTruncated.workspaceId);
  assert.equal(projected.runtimeReference?.bindingVersion, verifiedTruncated.bindingVersion);
  assert.equal(projected.runtimeReference?.verificationState, "VERIFIED");
  assert.equal(projected.truncated, true);
  assert.ok(evidence.some(item => item.id === "plan-only"));
  assert.ok(evidence.some(item => item.id === "execution-only"));
  assert.equal(evidence.filter(item => item.runtimeReference?.receiptId === duplicate.receiptId).length, 1);
  assert.equal(evidence.some(item => item.runtimeReference?.receiptId === unverified.receiptId), false);
  service.planExecution.view = async () => ({ planVersion: 2, receipts: [executionOnly] });
  const mismatched = await service.getRun("run-a", claims);
  assert.equal(mismatched.presentation.evidence.some((item: EvidenceReceipt) => item.id === "execution-only"), false);
});

import assert from 'node:assert/strict';
import { it } from 'node:test';
import { AgentRunRecoveryService } from '../src/agent-runtime/recovery/agent-run-recovery.service';
import { AgentContextProjectionService } from '../src/agent-runtime/context-projection/agent-context-projection.service';
import { AgentRuntimeService } from '../src/agent-runtime/agent-runtime.service';
import { AgentRuntimeEventsController } from '../src/agent-runtime/agent-runtime.events.controller';

function fixture() {
  const run:any={id:'r',status:'RUNNING',eventSeq:2,eventTerminalSeq:null,currentStepIndex:0,planVersion:2,failureReason:null};
  const events:any[]=[{id:'a',agentRunId:'r',seq:1,stepIndex:0,eventType:'TOOL_CALL',payload:{actionId:'x'}},
    {id:'b',agentRunId:'r',seq:2,stepIndex:0,eventType:'TOOL_RESULT',payload:{actionId:'x',output:'not verification authority'}}];
  let held=false, writes=0;
  const tx:any={
    $queryRawUnsafe:async(sql:string)=>{
      if(sql.includes('pg_try_advisory')) { if(held) return [{locked:false}]; held=true; return [{locked:true}]; }
      assert.match(sql,/FOR UPDATE/);return [{id:run.id}];
    },
    agentRun:{findUnique:async()=>({...run}),update:async({data}:any)=>{writes++;Object.assign(run,data);return {...run};}},
    agentRunEvent:{
      aggregate:async()=>({_count:{seq:events.length},_min:{seq:events.length?Math.min(...events.map(e=>e.seq)):null},_max:{seq:events.length?Math.max(...events.map(e=>e.seq)):null}}),
      findMany:async(q:any)=>{let rows=events.filter(e=>e.agentRunId===q.where.agentRunId);
        if(q.where.seq.gt!==undefined) rows=rows.filter(e=>e.seq>q.where.seq.gt);
        if(q.where.seq.lte!==undefined) rows=rows.filter(e=>e.seq<=q.where.seq.lte);
        if(q.where.eventType) rows=rows.filter(e=>q.where.eventType.in.includes(e.eventType));
        return rows.sort((a,b)=>q.orderBy.seq==='desc'?b.seq-a.seq:a.seq-b.seq).slice(0,q.take);},
      create:async({data}:any)=>{writes++;const e={...data,seq:++run.eventSeq};events.push(e);if(['COMPLETED','FAILED','CANCELLED'].includes(run.status))run.eventTerminalSeq=run.eventSeq;return e;}
    }
  };
  const db:any={$transaction:async(fn:any)=>{const wasHeld=held;try{return await fn(tx);}finally{if(!wasHeld)held=false;}}};
  const service=()=>new AgentRunRecoveryService(db,new AgentContextProjectionService(db));
  return {run,events,db,tx,service,writes:()=>writes};
}
it('earlier cursor replays only missing seq and rebuilds full durable context without authority writes',async()=>{
  const f=fixture(),before=JSON.stringify(f.events);const p=await f.service().snapshot('r',1);
  assert.deepEqual(p.replay.events.map((e:any)=>e.seq),[2]);assert.deepEqual(p.projection.events.map(e=>e.seq),[1,2]);
  assert.equal(p.projection.events[1].actionReference,p.projection.events[0].reference);assert.equal(p.stepIndex,0);assert.equal(p.planVersion,2);
  assert.equal(p.automaticDispatch,false);assert.equal(p.executionAuthority,'NONE');assert.equal(f.writes(),0);assert.equal(JSON.stringify(f.events),before);
});
it('browser/SSE reconnect and reload are identical and never dispatch or consume a permit',async()=>{
  const f=fixture();const first=await f.service().snapshot('r',1);const reloaded=await f.service().snapshot('r',1);
  assert.deepEqual(first,reloaded);assert.equal(f.writes(),0);assert.equal(f.events.length,2);
  const exhausted=await f.service().snapshot('r',2);assert.deepEqual(exhausted.replay.events,[]);
});
