      .get(`/agent-runs/${runId}/events`)
      .set('Accept', 'text/event-stream')
      .set('Cookie', cookie);
    const abort = setTimeout(() => req.abort(), 100);
    try {
      await req;
    } catch (e) {
      // Expected abort, test passes if server does not crash
    } finally {
      clearTimeout(abort);
    }
  });
});

