          return committedPlans;
        }
      },
      agentRunEvent: {
        create: async ({ data }: any) => {
          committedEvents.push(data);
          return data;
        }
      },
      agentApproval: {
        create: async ({ data }: any) => {
          committedApprovals.push(data);
          return data;
        }
      },
      agentArtifact: {
        create: async ({ data }: any) => {
          committedArtifacts.push(data);
