// A transactional in-memory database only. Real identity, authorization, approval,
// permit, result verification, workspace admission and context services run unmodified.
export async function inspectionHarness() {
  const tables: Record<string, Map<string, any>> = {}, db: any = {}; let serial = 0, queue = Promise.resolve();
  const equal = (a: any, b: any) => a instanceof Date || b instanceof Date ? +new Date(a) === +new Date(b) : a === b;
  const matches = (row: any, where: any): boolean => !where || Object.entries(where).every(([key, v]: any) => {
    if (key === "AND") return (Array.isArray(v) ? v : [v]).every((x: any) => matches(row, x));
    if (key === "OR") return v.some((x: any) => matches(row, x));
    if (key === "NOT") return !matches(row, v);
    if (!row) return false;
    if (key === "agentRun") return matches(tables.agentRun.get(row.agentRunId), v);
    const a = row[key];
    if (v && typeof v === "object" && !(v instanceof Date)) {
      if (v.path) return equal(v.path.reduce((n: any, k: string) => n?.[k], a), v.equals);
      if ("in" in v) return v.in.includes(a);
      if ("equals" in v) return equal(a, v.equals);
      if ("startsWith" in v) return typeof a === "string" && a.startsWith(v.startsWith);
      if ("notIn" in v) return !v.notIn.includes(a);
      return matches(a, v);
    }
    return equal(a, v);
  });
  const project = (name: string, row: any, arg: any) => {
    if (!row) return null;
    const result = structuredClone(row);
    if (name === "agentRun") {
      if (arg.include?.project) result.project = structuredClone(tables.project.get(row.projectId));
      if (arg.include?.plans) result.plans = [...tables.agentPlan.values()].filter(p => p.agentRunId === row.id).sort((a, b) => b.version - a.version).slice(0, arg.include.plans.take ?? 100).map(p => structuredClone(p));
    }
    return result;
  };
  for (const name of ["auditEvent", "user", "userSession", "project", "projectMember", "groupMember", "conversation", "conversationMessage", "agentRun", "agentPlan", "agentRunEvent", "agentApproval", "agentArtifact"]) {
    tables[name] = new Map(); const rows = tables[name];
    db[name] = {
      findUnique: async (arg: any) => project(name, [...rows.values()].find(r => matches(r, arg.where)), arg),
      findFirst: async (arg: any) => project(name, [...rows.values()].find(r => matches(r, arg.where)), arg),
      findMany: async (arg: any = {}) => [...rows.values()].filter(r => matches(r, arg.where)).slice(0, arg.take ?? 10000).map(r => project(name, r, arg)),
      create: async ({ data }: any) => { const row = structuredClone({ id: `fixture-${++serial}`, createdAt: new Date(), updatedAt: new Date(), ...data }); if (rows.has(row.id)) throw new Error("duplicate PK"); rows.set(row.id, row); return structuredClone(row); },
      update: async ({ where, data }: any) => { const row = [...rows.values()].find(r => matches(r, where)); if (!row) throw new Error("missing row"); Object.assign(row, structuredClone(data)); return structuredClone(row); },
      updateMany: async ({ where, data }: any) => { let count = 0; for (const r of rows.values()) if (matches(r, where)) { Object.assign(r, structuredClone(data)); count++; } return { count }; },
      upsert: async ({ where, create, update }: any) => rows.has(where.id) ? db[name].update({ where, data: update }) : db[name].create({ data: create })
    };
  }
  db.$queryRawUnsafe = async () => []; db.$executeRawUnsafe = async () => 1;
  db.$transaction = async (work: any) => { const before = queue; let unlock!: () => void; queue = new Promise(r => { unlock = r }); await before;
    const backup = Object.fromEntries(Object.entries(tables).map(([k, v]) => [k, structuredClone([...v])]));
    try { return await work(db); } catch (error) { for (const [k, rows] of Object.entries(backup)) { tables[k].clear(); for (const [id, row] of rows) tables[k].set(id, row); } throw error; } finally { unlock(); } };
  const claims: any = { sub: "user-a", organizationId: "org-a", role: "Admin", email: "test@example.invalid", displayName: "Test", sessionId: "session-a", iat: Math.floor(Date.now() / 1000), exp: Math.floor(Date.now() / 1000) + 3600 };
  await db.user.create({ data: { id: claims.sub, organizationId: claims.organizationId, status: "active", email: claims.email, displayName: "Test", roles: [{ role: { key: "Admin" } }] } });
  await db.userSession.create({ data: { id: claims.sessionId, userId: claims.sub, expiresAt: new Date(claims.exp * 1000), revokedAt: null } });
  await db.project.create({ data: { id: "project-a", organizationId: claims.organizationId } });
  await db.conversation.create({ data: { id: "conversation-a", projectId: "project-a", userId: claims.sub, metadata: {} } });
  const ledger = new RuntimeLedgerService(db), identity = new RuntimeIdentityService(ledger), resources = new ResourceAuthorizationService(db);
  const audit: any = { recordWithClaimsTx: async () => {}, recordWithClaims: async () => {} };
  const registry = new ToolRegistryService(), paths = new WorkspacePathService(), scopes = new ToolScopeService(new WorkspaceSourceResolver(), paths, new WorkspaceSecurityService(paths));
  const approvals = new ToolApprovalService(resources, audit), gate = new ToolAuthorizationService(registry, scopes, new ToolPermissionService(resources), new ToolRiskService(), approvals, resources, audit, db);
  const store = new WorkspaceStoreService(db), control = new RuntimeControlService(ledger, identity, gate, approvals, registry, store), folders = new RuntimeFolderService(identity, store), executions = new RuntimeExecutionService(ledger, identity, control, folders);
  const runtime = new WorkspaceRuntimeService(store, identity, control, new ProjectAccessService(db, resources));
  const evidence = new WorkspaceRuntimeEvidenceService(store, runtime, identity);
  const collector = new EvidenceCollectorService({} as any, { discover: () => { throw new Error("BACKEND_FALLBACK") } } as any, undefined, undefined, undefined, undefined, undefined, undefined, store, evidence);
  const contexts = new AgentContextBuilderService(new AgentUnderstandingService(), collector, new AgentContextSerializerService());
  const keys = generateKeyPairSync("ed25519"), publicKey = String(keys.publicKey.export({ type: "spki", format: "pem" }));
  const enrollment = await identity.enrollment(publicKey, "1.0.0"), timestamp = new Date().toISOString();
  await identity.proveEnrollment(enrollment.code, timestamp, sign(null, Buffer.from(runtimeSigningText(enrollment.challenge, timestamp)), keys.privateKey).toString("base64"));
  const device = await identity.enroll(claims, enrollment.code, "Windows test runtime");
  const request = async (op: "connect" | "poll" | "started" | "heartbeat" | "result" | "folder-result", body: any = {}) => {
    const c = await identity.challenge(device.runtimeId, op, body), time = new Date().toISOString();
    return executions.request(op, body, { runtimeId: device.runtimeId, connectionEpoch: c.connectionEpoch, challengeId: c.challengeId, timestamp: time,
      signature: sign(null, Buffer.from(runtimeSigningText(c, time)), keys.privateKey).toString("base64") }) as Promise<any>;
  };
  await request("connect", { workspaceReadProtocol: 1, conditionalWriteProtocol: 1 }); await identity.grant(claims, device.runtimeId, "project-a", ["filesystem.list", "filesystem.read", "filesystem.search"]);
  const complete = async (e: any, text = "export function authenticate() {}", override: any = {}) => {
    const started = await request("started", { executionId: e.attribution.executionId, operationDigest: e.attribution.operationDigest });
    if (!started.execute) return started;
    const now = new Date().toISOString(), path = e.attribution.validatedInput.path;
    return request("result", { executionId: e.attribution.executionId, operationDigest: e.attribution.operationDigest, state: "SUCCEEDED", startedAt: now, finishedAt: now,
      durationMs: 1, pid: null, exitCode: null, stdout: e.attribution.tool === "filesystem.read" ? text : "", stderr: "", error: null, truncated: false,
      result: e.attribution.tool === "filesystem.list" ? { path, entries: [{ name: "session.ts", type: "file" }] } : e.attribution.tool === "filesystem.search" ? { matches: [{ path: `${path}\\session.ts`, line: 1, text }], inspected: 2 } : { path, bytesRead: Buffer.byteLength(text), size: Buffer.byteLength(text) },
      verificationState: "VERIFIED", verificationResult: { observed: true }, ...override });
  };
  let binding = await runtime.createBinding(claims, "project-a", { runtimeId: device.runtimeId, rootPath: "D:\\Fixture", displayName: "Fixture", requestId: "bind" });
  const verify = await runtime.request(claims, "project-a", binding.workspaceId, "VERIFY", { bindingVersion: binding.version, relativePath: "", conversationId: "conversation-a", requestId: "verify" });
  const verifySnapshot = await control.snapshot(claims, verify.operation.runId);
  await control.approve(claims, verify.operation.runId, verifySnapshot!.proposal.approvalFingerprint!, "APPROVED");
  await complete((await request("poll")).execution); await runtime.operation(claims, "project-a", binding.workspaceId, binding.version, verify.operation.operationId);
  binding = (await store.getBinding(binding.workspaceId))!;
  const responses: Array<string | ((input: any) => string | Promise<string>)> = [];
  const calls: any[] = [], gateway: any = { requestAgentConversation: async (input: any) => { calls.push(input); if (!responses.length) throw new Error("no model fixture"); const response = responses.shift()!; return typeof response === "function" ? response(input) : response; } };
  gateway.requestStructuredReasoning = async (input: any) => { calls.push({ ...input, structured: true }); if (!responses.length) throw new Error("no model fixture"); const response = responses.shift()!; return typeof response === "function" ? response(input) : response; };
  const newService = () => new AgentInspectionService(ledger, identity, control, store, evidence, contexts, collector, gateway);
  const service = newService();
  const run = await db.agentRun.create({ data: { id: "agent-inspection-a", conversationId: "conversation-a", userId: claims.sub, projectId: "project-a", status: "QUEUED", planVersion: 1, title: "Understand authentication" } });
  await ledger.transaction(tx => service.initializeTx(tx, run, claims, binding, "Understand this project and identify where authentication is implemented."));
  const state = () => ledger.transaction(async tx => (await ledger.read<InspectionLoop>(tx, "AGENT_INSPECTION", run.id))!.payload);
  const approve = async () => { const s = await state(); return service.approve(run.id, claims, { planVersion: s.current!.planVersion, fingerprint: s.current!.fingerprint, decision: "APPROVED" }); };
  const inspect = (tool = "filesystem.list", relativePath = "", query = "") => JSON.stringify({ decision: "INSPECT", tool, relativePath, query, purpose: "Inspect authentication sources", report: null });
  const inspectStructured = (tool = "filesystem.list", relativePath = "", query = "") => JSON.stringify({ ...JSON.parse(inspect(tool, relativePath, query)), recommendation: null });
  return { db, tables, ledger, folders, identity, control, executions, registry, store, runtime, evidence, collector, contexts, claims, device, request, complete, binding, responses, calls, service, newService, run, state, approve, inspect, inspectStructured };
}

import { ForbiddenException } from "@nestjs/common";
import { toolDigest } from "../../src/agent-runtime/tools/tool-contract";
import { ResourceAuthorizationService } from "../../src/auth/resource-authz.service";
import { ProjectAccessService } from "../../src/auth/project-access.service";
import { WorkspaceStoreService } from "../../src/workspace-intelligence/workspace-store.service";
import { WorkspaceRuntimeService } from "../../src/workspace-intelligence/workspace-runtime.service";

export function workspaceHarness() {
  const rows = new Map<string, any>(), snapshots = new Map<string, any>(), calls: any[] = [];
  let queue = Promise.resolve(), tick = 0;
  const claims: any = { sub: "user-a", organizationId: "org-a", role: "Admin", email: "", displayName: "", sessionId: "session-a", exp: Math.floor(Date.now() / 1000) + 3600 };
  const device: any = { runtimeId: "runtime-a", userId: "user-a", organizationId: "org-a", fingerprint: "a".repeat(64), displayName: "Windows test", status: "ACTIVE", lastSeenAt: new Date().toISOString() };
  const grant: any = { grantId: "grant-a", runtimeId: device.runtimeId, userId: claims.sub, organizationId: claims.organizationId, projectId: "project-a", status: "ACTIVE", version: 1, mode: "TRUSTED_MACHINE", capabilities: ["filesystem.list", "filesystem.read"], expiresAt: null };
  const db: any = {
    agentApproval: { findUnique: async () => ({ status: "PENDING", dueAt: new Date(Date.now() + 900000) }) },
    $executeRawUnsafe: async () => 1,
    auditEvent: {
      findUnique: async ({ where }: any) => structuredClone(rows.get(where.id) ?? null),
      create: async ({ data }: any) => { if (rows.has(data.id)) throw new Error("duplicate PK"); const row = { ...structuredClone(data), createdAt: ++tick }; rows.set(data.id, row); return row; },
      updateMany: async ({ where, data }: any) => { const row = rows.get(where.id); if (!row || row.module !== where.module || row.metadata.revision !== where.metadata.equals) return { count: 0 }; rows.set(where.id, { ...row, ...structuredClone(data) }); return { count: 1 }; },
      findMany: async ({ where, take }: any) => structuredClone([...rows.values()].filter(r => (typeof where.module === "string" ? r.module === where.module : !where.module.notIn.includes(r.module)) && (!where.action || r.action === where.action)).sort((a, b) => b.createdAt - a.createdAt).slice(0, take))
    },
    user: { findUnique: async ({ where }: any) => ({ id: where.id, organizationId: "org-a", status: "active" }) },
    project: { findUnique: async ({ where }: any) => ({ id: where.id, organizationId: "org-a" }) },
    conversation: { findUnique: async ({ where }: any) => ({ id: where.id, projectId: "project-a", userId: "user-a", metadata: {} }), update: async () => ({}) }
  };
  db.$transaction = async (work: any) => { const before = queue; let unlock!: () => void; queue = new Promise(resolve => { unlock = resolve }); await before;
    const snapshot = structuredClone([...rows]); try { return await work(db) } catch (error) { rows.clear(); for (const [key, value] of snapshot) rows.set(key, value); throw error } finally { unlock() } };
  const store = new WorkspaceStoreService(db), projects = new ProjectAccessService(db, new ResourceAuthorizationService(db));
  const identity: any = { devices: async () => [structuredClone(device)], ledger: { transaction: async (work: any) => work(db), read: async () => ({ payload: structuredClone(grant) }) },
    device: async () => ({ payload: structuredClone(device) }), activeGrant: async () => { calls.push({ gate: "activeGrant" }); if (grant.status !== "ACTIVE" || device.status !== "ACTIVE") throw new ForbiddenException(); return grant } };
  const control: any = { propose: async (c: any, body: any) => {
    calls.push(body); const runId = `rtrun_${toolDigest([c.sub, body.conversationId, body.requestId])}`;
    if (!snapshots.has(runId)) snapshots.set(runId, { proposal: { ...body, runId, userId: c.sub, organizationId: c.organizationId, toolId: body.tool, validatedInput: body.input, proposalId: `proposal-${runId}`, grantId: grant.grantId, grantVersion: grant.version, approvalId: `approval-${runId}`, state: "AWAITING_APPROVAL" }, execution: null });
    return { runId, proposal: snapshots.get(runId).proposal };
  }, snapshot: async (_c: any, runId: string) => structuredClone(snapshots.get(runId)) };
  const service = new WorkspaceRuntimeService(store, identity, control, projects);
  const create = (requestId = "create-one", rootPath = "D:\\Projects\\test") => service.createBinding(claims, "project-a", { runtimeId: device.runtimeId, rootPath, displayName: "test", requestId });
  const request = (b: any, kind: "VERIFY" | "LIST" | "READ", path = "", requestId = `request-${++tick}`) => service.request(claims, "project-a", b.workspaceId, kind, { bindingVersion: b.version, relativePath: path, conversationId: "conversation-a", requestId });
  const complete = (v: any, options: { text?: string; truncated?: boolean; entries?: any[]; error?: string; state?: string } = {}) => {
    const s = snapshots.get(v.operation.runId), o = v.operation, text = options.text ?? "# Hello from Windows\n";
    s.execution = { state: options.state ?? (options.error ? "FAILED" : "SUCCEEDED"), verificationState: options.error ? "FAILED" : "VERIFIED",
      attribution: { executionId: `receipt-${o.operationId}`, operationDigest: "digest", proposalId: s.proposal.proposalId, runtimeId: o.runtimeId, tool: o.tool, validatedInput: { path: o.absolutePath } },
      result: { executionId: `receipt-${o.operationId}`, operationDigest: "digest", stdout: o.tool === "filesystem.read" ? text : "", finishedAt: new Date().toISOString(), error: options.error, truncated: options.truncated ?? false,
        result: o.tool === "filesystem.read" ? { path: o.absolutePath, bytesRead: Buffer.byteLength(text), size: Buffer.byteLength(text) } : { path: o.absolutePath, entries: options.entries ?? [{ name: "HELLO.md", type: "file" }, { name: "src", type: "directory" }] } } };
  };
  const observe = (v: any) => service.operation(claims, "project-a", v.operation.workspaceId, v.operation.bindingVersion, v.operation.operationId);
  const verified = async () => { const b = await create(), op = await request(b, "VERIFY"); complete(op); await observe(op); return (await store.getBinding(b.workspaceId))! };
  return { db, rows, store, projects, service, identity, control, claims, device, grant, calls, snapshots, create, request, complete, observe, verified };
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { AgentUnderstandingService } from "../src/agent-runtime/understanding/agent-understanding.service";
import { interpretContext, validatePlanningProposal, type AgentPlanningProposal } from "../src/agent-runtime/understanding/agent-planning.contract";
import { arabicHeroRequest, heroConstrainedResult, heroTitle } from "../src/agent-runtime/understanding/hero-title-constraint";
import { resolvedHeroPlanningObjective } from "../src/agent-runtime/understanding/persisted-planning";
import { prepareExactActions } from "../src/agent-runtime/execution/exact-plan-proposal";

const source = '\uFEFF<!doctype html>\r\n<style>.hero{color:red}</style>\r\n<section class="hero" id="home">\r\n<h1>\r\nBuilding\r\n<span>simple</span>\r\ndigital experiences.\r\n</h1>\r\n<p>simple elsewhere</p>\r\n</section>\r\n';
const objective = 'Change the Hero title in index.html from "Building simple digital experiences." to "Building intelligent digital experiences."\nAcceptance: exact target index.html; change only the Hero title, preserving its existing markup; preserve CSS; preserve encoding.';
const ref = "runtime:verified-source-receipt";
const arabicRequest = 'غيّر Hero heading من "Building intelligent digital experiences." إلى "Building intelligent digital products." مع الحفاظ على باقي محتوى الملف كما هو.';

test("bounded Arabic Hero change resolves verbatim quoted values and preservation", () => {
  const current = source.replace("<span>simple</span>", "<span>intelligent</span>");
  const f = fixture(current, arabicRequest);
  const constraint = f.base.constraints.find(c => c.rule === "HERO_TITLE_TEXT_ONLY")!;
  assert.equal(constraint.requestQuote, "مع الحفاظ على باقي محتوى الملف كما هو");
  assert.equal(constraint.textChange?.before, "Building intelligent digital experiences.");
  assert.equal(constraint.textChange?.after, "Building intelligent digital products.");
  assert.equal(heroConstrainedResult(current, constraint.textChange!), current.replace("digital experiences.", "digital products."));
  assert.equal(f.base.readiness, "UNDERSTANDING_READY");
  assert.equal(validate(f).plan.readiness, "PLAN_READY");
  assert.equal(validate(f).plan.authorization, "NOT_GRANTED");
});

test("Arabic quoted OLD/NEW are never trimmed or normalized into an accepted change", () => {
  const current = source.replace("<span>simple</span>", "<span>intelligent</span>");
  const paddedOld = arabicRequest.replace('من "Building', 'من " Building');
  assert.equal(arabicHeroRequest(paddedOld)?.before, " Building intelligent digital experiences.");
  assert.ok(!fixture(current, paddedOld).base.constraints.some(c => c.textChange));
  const paddedNew = arabicRequest.replace('إلى "Building', 'إلى " Building');
  assert.equal(arabicHeroRequest(paddedNew)?.after, " Building intelligent digital products.");
  assert.ok(!fixture(current, paddedNew).base.constraints.some(c => c.textChange));
});

test("Arabic preservation requires successfully verified Hero change", () => {
  const mismatch = fixture(source, arabicRequest);
  assert.equal(mismatch.base.constraints.find(c => c.requestQuote === "مع الحفاظ على باقي محتوى الملف كما هو")?.rule, "UNRESOLVED");
  assert.equal(mismatch.base.readiness, "NEEDS_CLARIFICATION");
});

test("unsupported Arabic restrictions on the bounded Hero command remain fail-closed", () => {
  const current = source.replace("<span>simple</span>", "<span>intelligent</span>");
  for (const restriction of ["بدون تغيير الصلاحيات", "مع الحفاظ على كل شيء آمن", "مع الحفاظ على باقي محتوى الملف كما هو وتغيير اللون", "لا تطلب موافقة"]) {
    const f = fixture(current, arabicRequest.replace("مع الحفاظ على باقي محتوى الملف كما هو.", restriction + "."));
    assert.ok(f.base.constraints.some(c => c.rule === "UNRESOLVED" && c.requestQuote === restriction));
    assert.equal(f.base.readiness, "NEEDS_CLARIFICATION");
  }
  assert.equal(arabicHeroRequest('غيّر navbar من "old" إلى "new"'), undefined);
});

function resolvedEnvelopeFixture() {
  const current = source.replace("<span>simple</span>", "<span>intelligent</span>");
  const runtimeReference = { receiptId: "verified-source-receipt", relativePath: "index.html", verificationState: "VERIFIED", truncated: false };
  const checkpoint = { status: "GROUNDED", evidence: [{ id: ref, read: true, runtimeReference }], understanding: {
    readiness: "UNDERSTANDING_READY", facts: [{ id: "hero-heading", text: heroTitle(current)!.excerpt, evidenceRef: ref }],
    inferences: [{ text: "The Hero heading", factIds: ["hero-heading"] }]
  } };
  const target = { concept: "hero", path: "index.html", evidenceId: "verified-source-receipt", factId: "hero-heading" };
  const envelope = `Create an engineering plan to modify only the resolved hero source target.\nOriginal request: ${arabicRequest}\nResolved source target (context, not authorization): ${JSON.stringify(target)}`;
  return { current, envelope, certified: { checkpoint, references: [runtimeReference] } as any };
}

test("certified server target wrapper stays separate from user constraint interpretation", () => {
  const { current, envelope, certified } = resolvedEnvelopeFixture();
  const objective = resolvedHeroPlanningObjective(envelope, certified);
  assert.equal(objective, arabicRequest);
  const f = fixture(current, objective);
  assert.ok(!f.base.constraints.some(c => c.rule === "UNRESOLVED"));
  assert.ok(f.base.constraints.every(c => !c.requestQuote?.includes("resolved hero source target")));
  assert.equal(validate(f).plan.readiness, "PLAN_READY");
});

test("unmatched or uncertified resolved-target wrappers cannot discard restrictions", () => {
  for (const mutate of [(s: any) => { s.references[0].receiptId = "other"; }, (s: any) => { s.checkpoint.status = "PARTIAL"; },
    (s: any) => { s.references[0].truncated = true; }, (s: any) => { s.checkpoint.understanding.facts[0].text = '<section class="hero">'; }]) {
    const { current, envelope, certified } = resolvedEnvelopeFixture(); mutate(certified);
    assert.equal(resolvedHeroPlanningObjective(envelope, certified), envelope);
    assert.equal(fixture(current, envelope).base.readiness, "NEEDS_CLARIFICATION");
  }
});
test("bounded multiline from/to labels resolve the exact Hero change", () => {
  const current = source.replace("<span>simple</span>", "<span>intelligent</span>");
  for (const instruction of [
    'Change the Hero heading in index.html from:\n"Building intelligent digital experiences."\nto:\n"Building intelligent digital products."',
    'Change the Hero heading text in index.html.\n\nTarget:\nChange the existing heading from:\n"Building intelligent digital experiences."\nto:\n"Building intelligent digital products."',
    'Change the Hero heading in index.html from "Building intelligent digital experiences." to "Building intelligent digital products."'
  ]) {
    const f = fixture(current, instruction);
    const change = f.base.constraints.find(c => c.rule === "HERO_TITLE_TEXT_ONLY")?.textChange;
