const valid = { title: "PRIVATE_TITLE", objective: "PRIVATE_OBJECTIVE", strategy: "CONTENT", changeKind: "TEXT", preservation: "UNSPECIFIED" };
const report = { constraintIds: [], facts: [], inferences: [], hypotheses: [], unknowns: [] };
