function collectPaths(node: { path: string; children?: unknown[] }): string[] {
  const out: string[] = [];
  if (node.path) out.push(node.path);
  for (const child of (node.children ?? []) as Array<{ path: string; children?: unknown[] }>) {
    out.push(...collectPaths(child));
  }
  return out;
}

